/* テキスト拡充・第4弾(担当:civ 地理総合・倫理・政治経済) */
(function (L) {
  function add(id, o) { var x = L[id]; if (!x) return; ['pat', 'more'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); }); }
  add('gg_map', {
    pat: [
      { name: '時差の計算(東経どうし・東経と西経)', freq: 'とてもよく出る', when: '2つの都市の標準時の経度と、片方の日時が示され、もう片方の日時を問われたら、この型です。', how: ['2都市の経度の差を求める(東経と西経のときは足し算、同じ側なら引き算)。', '経度の差を15でわって、時差(時間)を出す。', '東にある都市ほど時刻が進んでいるので、東の都市を求めるなら足し、西なら引く。', '24時をこえたら翌日、0時より前なら前日に直す。'], ex: { q: '東京(東経135度の標準時)が2月10日午後8時のとき、カイロ(東経30度の標準時)は何月何日の何時?', a: '2月10日午後1時', exp: '経度の差は 135−30=105度、105÷15=7時間です。カイロは東京より西にあるので7時間おくれています。午後8時(20時)の7時間前は13時、つまり同じ日の午後1時です。' } },
      { name: '地形図の縮尺から実際の距離・面積を求める', freq: 'よく出る', when: '「2万5千分の1の地形図上で○cm」のように、地図上の長さと縮尺が与えられたら、この型です。', how: ['地図上の長さに縮尺の分母をかけて、実際の長さ(cm)を出す。', 'cm を m(100でわる)や km(10万でわる)に直す。', '面積は、たてと横をそれぞれ実際の長さに直してからかける(縮尺の分母を2回かけるのと同じ)。'], ex: { q: '2万5千分の1の地形図上で3cmの道のりは、実際には何mか。', a: '750m', exp: '3cm×25000=75000cm です。100cm=1m なので、75000÷100=750m になります。面積を求めるときは、たて・横をそれぞれこのように直してからかけ算をします。' } },
      { name: '等高線から勾配(傾き)を求める', freq: 'よく出る', when: '2地点の標高差と、地図上の水平の長さが読みとれる問題は、この型です。', how: ['2地点の標高を等高線や標高点から読みとり、標高差を出す。', '地図上の長さを縮尺で実際の水平距離(m)に直す。', '勾配=標高差÷水平距離 として、分数(1/○)で表す。'], ex: { q: '2万5千分の1の地形図で、2地点の間が地図上で2cm、標高差が50mだった。平均の勾配を分数で答えよ。', a: '1/10', exp: '水平距離は 2cm×25000=50000cm=500m です。勾配は 50÷500=1/10 になります。標高差と水平距離の単位をそろえる(どちらもm)ことが、まちがえないためのポイントです。' } },
      { name: '目的に合う図法を選ぶ', freq: 'とてもよく出る', when: '「航海に使う」「最短コースを示す」「分布図に使う」など、地図の使い道が書かれていたら、この型です。', how: ['何を正しく表したいか(角度・距離と方位・面積)を、使い道から決める。', '角度ならメルカトル図法(海図)、中心からの距離と方位なら正距方位図法(航空図)、面積ならモルワイデ図法など(分布図)と結びつける。', 'のこりの性質はゆがんでいることも確かめる(すべてを正しくする地図はない)。'], ex: { q: '世界の米の産地の分布を点で示し、地域ごとの広がりを正しく比べたい。適した図法は、メルカトル図法・正距方位図法・モルワイデ図法のどれか。', a: 'モルワイデ図法', exp: '分布の広がりを比べるには、面積が正しい正積図法が適しています。モルワイデ図法は正積図法です。メルカトル図法は高緯度ほど面積が大きくなるので、分布図には向きません。' } },
      { name: '統計地図の選び方(絶対値か相対値か)', freq: 'よく出る', when: '「人口」「生産量」などの量か、「人口密度」「割合」などの比率かを見て地図の種類を選ぶ問題は、この型です。', how: ['データが量(絶対値)か、割合や密度(相対値)かを見分ける。', '絶対値なら、図形表現図(円や棒の大きさ)やドットマップを選ぶ。', '相対値なら、階級区分図(色のこさで分ける)を選ぶ。', '絶対値を階級区分図にすると、面積の大きい地域が目立ってしまうことに注意する。'], ex: { q: '都道府県ごとの「人口密度」を表すのに適した統計地図はどれか。図形表現図・階級区分図・流線図から選べ。', a: '階級区分図', exp: '人口密度は「面積あたりの人口」という相対値なので、色のこさで段階を表す階級区分図が適しています。人口そのもの(絶対値)なら、円の大きさなどで表す図形表現図を使います。' } }
    ],
    more: [
      { lv: 1, q: '地球上の位置を表す線のうち、赤道と平行に引かれた線を何というか。', a: '緯線', exp: '緯線は赤道と平行な線で、緯度を表します。経線は北極と南極を結ぶ線で、経度を表します。「緯=横」と覚えるとまちがえにくいです。' },
      { lv: 1, q: '経度は、本初子午線から東と西にそれぞれ何度まであるか。', a: '180度', exp: '経度は東経0〜180度、西経0〜180度です。東経180度と西経180度は同じ経線で、これにほぼ沿って日付変更線が引かれています。' },
      { lv: 1, q: '面積が正しくえがかれる図法をまとめて何というか。', choices: ['正角図法', '正積図法', '正距図法', '正方位図法'], a: 'B(正積図法)', exp: '面積が正しい図法を正積図法といい、サンソン図法・モルワイデ図法・グード図法などがあります。分布図に向いています。' },
      { lv: 1, q: '地形図に方位記号がないとき、地図の上はどの方位を表しているか。', a: '北', exp: '地形図は、ふつう上が北になるようにつくられています。方位記号がある場合は、その記号の向きにしたがいます。' },
      { lv: 1, q: '地形図の地図記号「文」は何を表しているか。', a: '小・中学校', exp: '「文」は小・中学校を表します。高等学校は「文」を丸で囲んだ記号です。地図記号は、土地利用や施設を読みとる手がかりになります。' },
      { lv: 1, q: 'コンピュータ上で、さまざまな地理情報を重ね合わせて分析・表示するしくみを、アルファベット3文字で何というか。', a: 'GIS(地理情報システム)', exp: 'GISは、地図に人口・土地利用・災害の危険などの情報を重ねて分析するしくみです。ハザードマップや店の出店計画などに使われます。' },
      { lv: 1, q: 'オーストラリア東部は東経150度を標準時の基準にしている。日本(東経135度)と比べて何時間進んでいるか。', a: '1時間', exp: '経度の差は 150−135=15度で、15度で1時間の時差になります。オーストラリア東部は日本より東にあるので、1時間進んでいます。' },
      { lv: 2, q: '東京(東経135度の標準時)が1月20日午前10時のとき、ニューヨーク(西経75度の標準時)は何月何日の何時か。サマータイムは考えない。', a: '1月19日午後8時', exp: '東経と西経なので 135+75=210度、210÷15=14時間の時差です。ニューヨークは西にあるので14時間おくれ、午前10時の14時間前は前日の午後8時です。' },
      { lv: 2, q: '2万5千分の1の地形図上で、たて4cm・横6cmの長方形の土地がある。実際の面積は何km²か。', a: '1.5km²', exp: 'たては 4cm×25000=100000cm=1km、横は 6cm×25000=150000cm=1.5km です。面積は 1×1.5=1.5km² になります。先に長さを直してからかけるのがコツです。' },
      { lv: 2, q: '5万分の1の地形図で、2地点の間が地図上で5cm、標高差が100mだった。平均の勾配を分数で答えよ。', a: '1/25', exp: '水平距離は 5cm×50000=250000cm=2500m です。勾配は 100÷2500=1/25 になります。縮尺の分母を5万にすることを忘れないようにしましょう。' },
      { lv: 2, q: '国ごとの小麦の生産量(絶対値)を地図に表すのに、最も適したものはどれか。', choices: ['階級区分図', '図形表現図', '等値線図', '流線図'], a: 'B(図形表現図)', exp: '生産量は量そのもの(絶対値)なので、円や棒の大きさで表す図形表現図が適しています。階級区分図は割合や密度などの相対値に使います。' },
      { lv: 2, q: 'メルカトル図法の地図上で2地点を結んだ直線について、正しいものはどれか。', choices: ['2地点間の最短コースを表す', '経線と一定の角度で交わるコース(等角航路)を表す', '2地点間の正しい距離を表す', '面積が正しい範囲を表す'], a: 'B(経線と一定の角度で交わるコース(等角航路)を表す)', exp: 'メルカトル図法は正角図法で、直線は等角航路になります。最短コース(大圏航路)は、メルカトル図法では曲線になることに注意します。' },
      { lv: 2, q: '南緯35度・東経140度の地点の対蹠点(地球の裏側の地点)の緯度と経度を答えよ。', a: '北緯35度・西経40度', exp: '緯度は数字はそのままで南北を入れかえます。経度は180度から引いて東西を入れかえます(180−140=40)。だから北緯35度・西経40度です。' },
      { lv: 2, q: '地形図で、等高線の間隔がせまい所と広い所では、どちらの傾斜が急か。', a: '間隔がせまい所', exp: '等高線は同じ高さを結んだ線です。間隔がせまいほど、短い水平距離で高さが大きく変わるので、傾斜が急になります。' },
      { lv: 2, q: '赤道一周を4万kmとすると、赤道上で経度1度離れた2地点の距離はおよそ何kmか。小数第1位を四捨五入せよ。', a: '約111km', exp: '赤道一周は360度なので、40000÷360=111.1…km です。この「1度≒111km」は、緯度1度の長さ(南北方向)にもほぼあてはまります。' },
      { lv: 3, q: '東京(東経135度の標準時)を1月10日午後5時に出発した飛行機が、10時間かかってロサンゼルス(西経120度の標準時)に着いた。到着した現地の日時を答えよ。', a: '1月10日午前10時', exp: '到着は東京時間で1月11日午前3時です。時差は (135+120)÷15=17時間で、ロサンゼルスは17時間おくれているので、1月10日午前10時になります。出発より「前の日時」に着くように見えるのは日付変更線をこえたためです。' },
      { lv: 3, q: '日本のある地点で、太陽が南中したとき、日本標準時は午前11時40分だった。この地点の経度を答えよ。', a: '東経140度', exp: '東経135度では正午に南中します。それより20分早く南中したので、東に位置します。地球は4分で経度1度回るので、20÷4=5度東、つまり東経140度です。' },
      { lv: 3, q: '北緯60度の緯線上で、経度が10度離れた2地点の緯線にそった距離はおよそ何kmか。赤道一周を4万km、cos60°=0.5とし、十の位を四捨五入して答えよ。', a: '約600km', exp: '北緯60度の緯線の長さは 40000×0.5=20000km です。その10/360なので、20000×10÷360=555.5…km、十の位を四捨五入して約600km です。高緯度ほど同じ経度差でも距離が短くなります。' },
      { lv: 3, q: '東京を中心とした正距方位図法の地図で、東京から真東に向かって進み続けると、最初にたどり着く大陸はどこか。', choices: ['北アメリカ大陸', '南アメリカ大陸', 'ユーラシア大陸', 'オーストラリア大陸'], a: 'B(南アメリカ大陸)', exp: '真東は、正距方位図法の中心から右へのびる直線の方向です。この線は大圏(地球を二分する大きな円)にそって南東へ曲がるように進み、南アメリカ大陸に着きます。緯線にそって進むのとはちがいます。' },
      { lv: 3, q: '国ごとの人口(絶対値)を階級区分図で表すのが適切でない理由を、「面積」ということばを使って説明せよ。', a: '階級区分図は地域全体を同じ色でぬるため、面積の大きい国が目立ち、人口が多い印象を与えてしまう。人口と面積は関係がないので、量を正しく比べられないから。', exp: '階級区分図は面積の広さが見た目に強くひびきます。そのため、密度や割合のような「面積や人口でわった値」に使います。量そのものは図形表現図などで表すのが基本です。' }
    ]
  });

  add('gg_climate', {
    pat: [
      { name: '雨温図からケッペンの気候区分を判定する', freq: 'とてもよく出る', when: '最暖月・最寒月の気温と、降水の季節のかたよりが示され、気候区分を問われたら、この型です。', how: ['最暖月が10℃未満なら寒帯(E)と決める。', '次に乾燥限界と年降水量を比べて乾燥帯(B)かを決める。', 'のこりは最寒月の気温で、18℃以上→A、−3℃以上→C、−3℃未満→Dと分ける。', '降水の季節(f・s・w)と、温帯なら最暖月22℃以上か(a・b)で細かく決める。'], ex: { q: '最寒月−1℃、最暖月24℃、1年中降水が多い地点の気候区分を記号で答えよ。', a: 'Cfa(温暖湿潤気候)', exp: '最暖月24℃なので寒帯ではなく、降水が多いので乾燥帯でもありません。最寒月−1℃は−3℃以上なので温帯(C)です。1年中降水があるのでf、最暖月が22℃以上なのでaです。−3℃の線を見落とさないようにします。' } },
      { name: '乾燥限界を計算してBW・BSを判定する', freq: 'よく出る', when: '年平均気温・年降水量・雨の季節がそろっていて、「乾燥帯か」「砂漠かステップか」を問われたら、この型です。', how: ['雨の季節で式を選ぶ(1年中 r=20(t+7)、夏に多い r=20(t+14)、冬に多い r=20t)。', '年降水量が r より少なければ乾燥帯。', 'さらに r/2 と比べ、少なければ砂漠(BW)、以上ならステップ(BS)。'], ex: { q: '年平均気温20℃、年降水量250mmで、雨の大部分が夏に降る地点の気候区分を答えよ。', a: '砂漠気候(BW)', exp: '夏に雨が多いので r=20(20+14)=680mm です。250mm は680mm より少ないので乾燥帯です。r/2=340mm よりも少ないので、砂漠気候(BW)になります。' } },
      { name: '標高による気温の変化を計算する', freq: 'よく出る', when: '高い所の都市と低い所の都市の気温を比べたり、山の上の気温を求めたりする問題は、この型です。', how: ['気温は100m高くなるごとに約0.65℃下がる(気温の逓減率)。', '標高差(m)÷100×0.65 で、下がる気温を出す。', '低い所の気温から引けば高い所の気温、足せば低い所の気温になる。'], ex: { q: '標高1500mの地点の気温が15℃のとき、同じ空気の条件で標高0mの気温はおよそ何℃か。逓減率は100mにつき0.65℃とする。', a: '約24.8℃', exp: '1500÷100×0.65=9.75℃ なので、標高0mでは 15+9.75=24.75℃、およそ24.8℃です。赤道近くでも高地の都市が過ごしやすい(常春)のは、この気温の低下があるからです。' } },
      { name: '雨の季節を気圧帯の移動で説明する', freq: 'とてもよく出る', when: '「なぜ夏に乾燥するのか」「なぜ雨季と乾季があるのか」と、降水の季節の理由を問われたら、この型です。', how: ['その地点の緯度を確かめ、近くにある気圧帯(赤道低圧帯・亜熱帯高圧帯・亜寒帯低圧帯)を考える。', '気圧帯は太陽の動きにあわせて、夏は高緯度側、冬は低緯度側へ移ることを思い出す。', '低圧帯におおわれる季節は雨、高圧帯におおわれる季節は乾燥、と結びつける。'], ex: { q: '地中海沿岸が夏に乾燥し、冬に雨が多くなる理由を、気圧帯を使って説明せよ。', a: '夏は北へ移った亜熱帯高圧帯におおわれて乾燥し、冬は南へ移った偏西風や前線(亜寒帯低圧帯)の影響を受けて雨が降るから。', exp: '高圧帯では下降気流になるので雲ができにくく、乾燥します。地中海性気候(Cs)は、亜熱帯高圧帯と偏西風帯の「境目」にあり、季節によってどちらかにおおわれることが特徴です。' } },
      { name: 'フェーン現象の気温の計算', freq: '難関大で出る', when: '空気が山をこえ、風上と風下で気温を比べる問題は、この型です。', how: ['雲ができていない空気は100mで約1℃、雲ができている空気は100mで約0.5℃変化することを確かめる。', '風上では、雲ができるまでとできてからに分けて、上がるときの気温を順に計算する。', '風下では雲が消えた乾いた空気が下りるので、100mで1℃ずつ上がると考える。', '風上のふもとと風下のふもとの気温を比べる。'], ex: { q: '標高0mで15℃の湿った空気が、はじめから雲をつくりながら標高2000mの山頂まで上がり、風下側を雲をつくらずに標高0mまで下りた。風下のふもとの気温は何℃か。', a: '25℃', exp: '上がるときは雲ができているので 2000÷100×0.5=10℃下がり、山頂で5℃です。下りるときは乾いているので 2000÷100×1=20℃上がり、5+20=25℃になります。上りと下りで変わり方がちがうことが、気温上昇の原因です。' } }
    ],
    more: [
      { lv: 1, q: '中緯度で、1年中ほぼ西から東へ向かって吹く恒常風を何というか。', a: '偏西風', exp: '偏西風は、亜熱帯高圧帯から亜寒帯低圧帯に向かって吹く風で、地球の自転の影響で西寄りの風になります。ヨーロッパの西岸に海の空気を運びます。' },
      { lv: 1, q: '夏と冬で風向きがほぼ反対になる風を何というか。', a: '季節風(モンスーン)', exp: '季節風は、夏は海から大陸へ、冬は大陸から海へ吹く風です。陸と海のあたたまりやすさのちがいから生まれ、東アジアや南アジアの雨の季節を決めます。' },
      { lv: 1, q: '大陸の内部と海沿いでは、一般に気温の年較差(1年の最高と最低の差)が大きいのはどちらか。', a: '大陸の内部', exp: '陸は海よりあたたまりやすく冷めやすいので、海から遠い大陸の内部ほど夏は暑く冬は寒くなります。これを大陸性気候といいます。' },
      { lv: 1, q: '1年中高温で雨が多い熱帯雨林気候を、ケッペンの記号で答えよ。', a: 'Af', exp: 'Aは熱帯(最寒月18℃以上)、fは1年中雨が多いことを表します。アマゾン川流域やコンゴ盆地、東南アジアの島々などに分布します。' },
      { lv: 1, q: '夏に乾燥する地中海性気候で、乾燥に強いため多くつくられている樹木作物はどれか。', choices: ['カカオ', 'オリーブ', '天然ゴム', '茶'], a: 'B(オリーブ)', exp: 'オリーブは乾燥した夏に強く、地中海沿岸で古くから栽培されています。カカオや天然ゴムは高温多雨の熱帯、茶は雨が多く水はけのよい土地に向いています。' },
      { lv: 1, q: '熱帯に広く分布する、鉄やアルミニウムをふくむ赤色のやせた土を何というか。', a: 'ラトソル', exp: 'ラトソルは、高温多雨で養分が雨に流されてできる、赤くやせた土です。アルミニウムの原料ボーキサイトがとれることもあります。' },
      { lv: 1, q: '寒帯のうち、最暖月の平均気温も0℃未満で、1年中氷と雪におおわれる気候を何というか。', a: '氷雪気候(EF)', exp: '氷雪気候は南極大陸やグリーンランドの内陸に分布します。最暖月が0℃以上10℃未満で、夏にこけ類が生えるのはツンドラ気候(ET)です。' },
      { lv: 2, q: '平地の気温が20℃のとき、標高2400mの山の上の気温はおよそ何℃か。逓減率は100mにつき0.65℃とする。', a: '約4.4℃', exp: '2400÷100×0.65=15.6℃ 下がるので、20−15.6=4.4℃ です。高い山では、平地よりかなり寒くなることがわかります。' },
      { lv: 2, q: '年平均気温15℃、年降水量300mmで、雨が1年中ほぼ平均して降る地点の気候区分を答えよ。', a: 'ステップ気候(BS)', exp: '1年中降るので r=20(15+7)=440mm です。300mm は440mm より少ないので乾燥帯です。r/2=220mm 以上なので、砂漠ではなくステップ気候になります。' },
      { lv: 2, q: '最寒月−8℃、最暖月20℃で、冬の降水がとても少なく夏に多い地点の気候区分を記号で答えよ。', a: 'Dw(冷帯冬季少雨気候)', exp: '最暖月が10℃以上なので寒帯ではありません。最寒月が−3℃未満なので冷帯(D)、冬に乾燥するのでwです。冬にシベリア高気圧が発達する地域に見られます。' },
      { lv: 2, q: '最寒月20℃、最暖月28℃で、雨季と乾季がはっきりしており、乾季には草原になる地点の気候区分を答えよ。', a: 'サバナ気候(Aw)', exp: '最寒月18℃以上なので熱帯です。雨季と乾季がはっきり分かれ、背の高い草原にまばらに木が生えるのがサバナ気候(Aw)の特徴です。' },
      { lv: 2, q: '夏は亜熱帯高圧帯におおわれて乾燥し、冬は偏西風の影響で雨が多い気候はどれか。', choices: ['西岸海洋性気候', '地中海性気候', '温暖冬季少雨気候', '温暖湿潤気候'], a: 'B(地中海性気候)', exp: '地中海性気候(Cs)は、緯度30〜40度付近の大陸西岸に分布します。夏の乾燥が強いので、乾燥に強い樹木作物の栽培がさかんです。' },
      { lv: 2, q: '南半球のある地点は、7月が最も寒く平均8℃、1月が最も暑く平均19℃で、1年中雨が降る。気候区分を記号で答えよ。', a: 'Cfb(西岸海洋性気候)', exp: '最寒月8℃は−3℃以上18℃未満なので温帯です。1年中雨が降るのでf、最暖月が22℃未満なのでbです。南半球では季節が北半球と逆になることに注意します。' },
      { lv: 2, q: 'サバナ気候の地域で雨季になるのは、赤道低圧帯がその地点に近づく季節である。それは夏と冬のどちらか。', a: '夏(高日季)', exp: '気圧帯は太陽が高くなる側へ移るので、夏には赤道低圧帯がその地点に近づき、上昇気流で雨が降ります。冬は亜熱帯高圧帯の影響で乾季になります。' },
      { lv: 2, q: '熱帯のうち、短い乾季があるが、全体として雨がとても多く、森林が育つ気候を記号で答えよ。', a: 'Am(熱帯モンスーン気候)', exp: 'Amは、季節風の影響で雨季に大量の雨が降り、弱い乾季があっても森林が保たれる気候です。インドの西海岸や東南アジアの一部などに見られます。' },
      { lv: 3, q: '年平均気温24℃、年降水量500mmで、雨の大部分が夏に降る地点がある。乾燥限界を計算し、気候区分を答えよ。', a: '乾燥限界760mm。ステップ気候(BS)', exp: '夏に雨が多いので r=20(24+14)=760mm です。500mm は760mm より少ないので乾燥帯です。r/2=380mm 以上なので、ステップ気候(BS)になります。' },
      { lv: 3, q: '年平均気温28℃で雨が夏に集中する地点は、年降水量が800mmあっても乾燥帯になる。乾燥限界を計算して、そうなる理由を説明せよ。', a: '乾燥限界は20(28+14)=840mmで、800mmはこれより少ないから。気温が高く、夏の雨は蒸発しやすいため、多めの雨でも乾燥した状態になる。', exp: '乾燥帯かどうかは、降水量の多さだけでなく「蒸発する量」と比べて決まります。気温が高いほど、また雨が夏に降るほど、乾燥限界は大きくなります。800÷2=400mm 以上なのでBSです。' },
      { lv: 3, q: '標高0mで22℃の空気が、標高600mまでは雲をつくらずに上がり、そこから標高1800mの山頂までは雲をつくりながら上がった。その後、風下側を雲をつくらずに標高0mまで下りた。風下のふもとの気温は何℃か。', a: '28℃', exp: '0〜600mは100mで1℃下がり16℃、600〜1800mは100mで0.5℃下がり 16−6=10℃ です。下りは1800mを100mで1℃上がるので 10+18=28℃ になります。風上より6℃高くなります。' },
      { lv: 3, q: 'ヨーロッパでは西岸海洋性気候が内陸の奥まで広がるが、北アメリカでは西岸のせまい範囲に限られる。この理由を地形から説明せよ。', a: '北アメリカの西部には南北に山脈が連なり、偏西風が運ぶ海からの空気をさえぎるが、ヨーロッパには南北方向の大きな山脈がなく、偏西風が内陸まで入りこむから。', exp: 'ヨーロッパの大山脈であるアルプス山脈などは東西方向にのびるので、西風をさえぎりにくいのです。北アメリカではロッキー山脈などが西風をさえぎり、その東側は乾燥しやすくなります。' },
      { lv: 3, q: '北半球のある地点は、7月が最も暑く平均28℃、1月が最も寒く平均4℃で、夏の雨がとても多く冬はほとんど雨が降らない。気候区分を記号で答えよ。', a: 'Cw(温暖冬季少雨気候)', exp: '最寒月4℃は−3℃以上18℃未満なので温帯です。冬に乾燥するのでwです。季節風の影響が強い中国南部やインド北部などに見られます。Cfaとのちがいは冬の乾燥です。' }
    ]
  });

  add('gg_landform', {
    pat: [
      { name: '地形図から扇状地を読みとり、土地利用を説明する', freq: 'とてもよく出る', when: '山地のふもとで、等高線が扇の形(同心円状)に広がっている地形図が出たら、この型です。', how: ['等高線が谷の出口から扇形に広がっていれば扇状地と判断する。', '扇頂・扇央・扇端の3つに分ける。', '扇央は砂や石が多く水が地下にしみこむので、畑・果樹園になりやすいと考える。', '扇端では地下水がわき出るので、集落や水田が並ぶと結びつける。'], ex: { q: '地形図で、谷の出口から等高線が扇形に広がり、中央部に果樹園の記号が多く、末端には集落と水田が帯のように並んでいた。末端に集落が並ぶ理由を答えよ。', a: '扇状地の末端(扇端)では、扇央で地下にしみこんだ水がわき出し、水が得やすいから。', exp: '扇状地は粒の大きい砂れきでできているため、扇央では川の水が地下を流れます。その水が扇端でわき出すので、生活用水や水田の水が得やすく、古くから集落が並びました。' } },
      { name: '三角州の形から、川と海の力を推理する', freq: '難関大で出る', when: '三角州の形(円弧状・鳥趾状・カスプ状)や、河口の土砂と波の強さが話題になったら、この型です。', how: ['川が運ぶ土砂の量と、海の波や流れの強さの「綱引き」と考える。', '土砂がとても多く波が弱いと、川が沖へのびて鳥の足のような鳥趾状になる。', '両方がつりあうと円弧状、波が強いと河口だけがとがったカスプ状になる。'], ex: { q: 'ある川は土砂の量が少なく、河口付近の波が強い。この川の河口にできやすい三角州の形はどれか。円弧状・鳥趾状・カスプ状から選べ。', a: 'カスプ状', exp: '波が強いと、運ばれた土砂は横にけずられて広がり、河口の部分だけがとがった形になります。これがカスプ状三角州で、イタリアのテヴェレ川が代表例です。' } },
      { name: '大地形と資源を結びつける', freq: 'とてもよく出る', when: '山脈や地域の名前から、そこでとれる資源を問われたら、この型です。', how: ['その地域が安定陸塊・古期造山帯・新期造山帯のどれかを決める。', '安定陸塊なら鉄鉱石、古期造山帯なら石炭、新期造山帯なら銅や石油と結びつける。', '理由(地層の年代や、造山運動・マグマの活動)も一言そえる。'], ex: { q: 'ロシアのウラル山脈は大地形のどれにあたるか。また、その周辺で多く産出する資源を1つ答えよ。', a: '古期造山帯。石炭', exp: 'ウラル山脈は古生代の造山運動でできた古期造山帯で、長い侵食でなだらかになっています。古生代にしげった植物が地層にうもれて石炭になったので、古期造山帯には炭田が多いのです。' } },
      { name: 'プレート境界の種類を見分ける', freq: 'よく出る', when: '海嶺・海溝・地溝帯・大山脈・断層などの名前から、プレートの動きを問われたら、この型です。', how: ['プレートどうしが離れる境界(海嶺・地溝帯)か、近づく境界(海溝・大山脈)か、すれちがう境界(横ずれ断層)かを見分ける。', '近づく境界は、海のプレートが沈みこむ(海溝・弧状列島)か、大陸どうしがぶつかる(大山脈)かに分ける。', '火山や地震が多いかどうかも、境界の種類から説明する。'], ex: { q: 'アフリカ東部の大地溝帯(グレートリフトヴァレー)は、どのような種類のプレート境界にあたるか。', a: '広がる境界(プレートが離れていく境界)', exp: '大地溝帯は、大地が両側に引きはなされて落ちこんでできた細長い谷です。プレートが離れていく境界なので、火山も見られます。海の底では、同じしくみで海嶺ができます。' } },
      { name: '沈水海岸と離水海岸を見分ける', freq: 'よく出る', when: '入り組んだ海岸や、海ぞいの階段状の地形など、海岸の形から成り立ちを問われたら、この型です。', how: ['海面が上がったり土地が沈んだりしてできたのが沈水海岸、その反対が離水海岸と整理する。', '沈んだのがV字谷ならリアス海岸、U字谷ならフィヨルド、河口ならエスチュアリーとする。', '海岸段丘や海岸平野は、離水によってできたと判断する。'], ex: { q: '三陸海岸の南部や志摩半島に見られる、のこぎりの歯のように入り組んだ海岸は、何が沈んでできたか。地形の名前とあわせて答えよ。', a: 'リアス海岸。川がけずったV字谷が沈んでできた。', exp: 'リアス海岸は、山地の谷(V字谷)に海水が入りこんでできた沈水海岸です。湾の奥は波がおだやかで養殖や漁港に向きますが、津波の高さが増しやすい点に注意が必要です。' } }
    ],
    more: [
      { lv: 1, q: 'プレートどうしが近づき、片方がもう一方の下に沈みこむような境界を何というか。', choices: ['広がる境界', '狭まる境界', 'ずれる境界', '安定陸塊'], a: 'B(狭まる境界)', exp: '狭まる境界では、海のプレートが沈みこんで海溝や弧状列島ができたり、大陸どうしがぶつかって大山脈ができたりします。日本列島は狭まる境界にあります。' },
      { lv: 1, q: '扇状地の中央部(扇央)で、川の水が地下にしみこみ、ふだんは水が流れていない川を何というか。', a: '水無川', exp: '扇央は粒の大きい砂れきでできているので、水が地下にしみこみやすく、ふだんは川が干上がっています。大雨のときだけ水が流れます。' },
      { lv: 1, q: '川が海や湖に注ぐ河口付近に、細かい土砂が積もってできる低く平らな地形を何というか。', a: '三角州', exp: '三角州は、川の流れがゆるやかになる河口で、泥などの細かい土砂がたまってできます。低くて水が得やすいので、水田や大都市が発達しやすい地形です。' },
      { lv: 1, q: 'ヒマラヤ山脈やアンデス山脈は、大地形のうちどれにあたるか。', a: '新期造山帯', exp: '新期造山帯は、中生代の終わりから新生代に造山運動を受けた地域で、高くけわしい山脈が多く、今も地震や火山の活動がさかんです。' },
      { lv: 1, q: '氾濫原で、川の両岸にそってできる、まわりより少し高い土地を何というか。', a: '自然堤防', exp: '洪水のとき、川からあふれた水は岸の近くで勢いを失い、砂を積もらせます。こうしてできた微高地が自然堤防で、水につかりにくいので集落や畑に使われます。' },
      { lv: 1, q: '谷が海に沈んでできた、のこぎりの歯のように出入りの多い海岸を何というか。', a: 'リアス海岸', exp: 'リアス海岸は、川がけずったV字谷が沈んでできた海岸です。日本では三陸海岸の南部や若狭湾などに見られます。' },
      { lv: 1, q: '火山活動や地殻変動など、地球の内部から地形をつくる力を何というか。', a: '内的営力', exp: '地形をつくる力には、地球内部からの内的営力と、川・風・氷河などが地表をけずったり積もらせたりする外的営力があります。内的営力は大地を高くし、外的営力はならす方向に働きます。' },
      { lv: 2, q: '氾濫原の自然堤防と後背湿地の、ふつうの土地利用の組み合わせとして正しいものはどれか。', choices: ['自然堤防=水田、後背湿地=集落', '自然堤防=集落や畑、後背湿地=水田', '自然堤防=森林、後背湿地=果樹園', '自然堤防=水田、後背湿地=畑'], a: 'B(自然堤防=集落や畑、後背湿地=水田)', exp: '自然堤防は少し高く水はけがよいので、集落や畑に使われます。その背後の後背湿地は低く水はけが悪いので、水田に利用されてきました。' },
      { lv: 2, q: '扇状地の末端(扇端)に、古くから集落が帯のように並ぶことが多い理由を答えよ。', a: '扇央で地下にしみこんだ水が扇端でわき出し(湧水)、水が得やすいから。', exp: '扇央では水が得にくいのに対し、扇端では湧水が出るので、飲み水や水田の水を確保できます。そのため集落や水田は扇端に集まりました。' },
      { lv: 2, q: '古期造山帯に石炭が多い理由として正しいものはどれか。', choices: ['新しい時代の火山活動で生まれたから', '古生代にしげった植物が地層にうもれて変化したから', '海の生物の死がいが背斜構造にたまったから', '先カンブリア時代の岩盤に鉄がふくまれていたから'], a: 'B(古生代にしげった植物が地層にうもれて変化したから)', exp: '石炭は、古生代の石炭紀などに大量にしげった植物が、地層にうもれて長い時間をかけて変化したものです。そのころの地層が多い古期造山帯の周辺に炭田が分布します。' },
      { lv: 2, q: '河岸段丘で、高い位置にある段丘面と低い位置にある段丘面では、一般にどちらが古くできたか。', a: '高い位置にある段丘面', exp: '河岸段丘は、土地の隆起などで川が川底を深くけずり直すたびに、もとの川原が段として取り残されてできます。だから上の段ほど古い時代の川原です。' },
      { lv: 2, q: '川が沖へ向かって何本にも分かれてのび、鳥の足のような形をした鳥趾状三角州が見られる代表的な川はどれか。', choices: ['ナイル川', 'ミシシッピ川', 'テヴェレ川', 'テムズ川'], a: 'B(ミシシッピ川)', exp: 'ミシシッピ川は運ぶ土砂がとても多く、メキシコ湾の波が比較的弱いので、川が沖へのびる鳥趾状三角州になります。ナイル川は円弧状、テヴェレ川はカスプ状です。' },
      { lv: 2, q: 'ヨーロッパ南部のアルプス山脈から、西アジアを通ってヒマラヤ山脈へと連なる新期造山帯を何というか。', a: 'アルプス=ヒマラヤ造山帯', exp: '新期造山帯は、太平洋をとりまく環太平洋造山帯と、アルプス=ヒマラヤ造山帯の2つに大きく分けられます。どちらも地震が多い地域です。' },
      { lv: 2, q: '海岸から細長く突き出した砂の地形で、先がかぎのように曲がっているものを何というか。', a: '砂嘴', exp: '砂嘴は、沿岸流が運んだ砂が積もってできます。静岡県の三保松原や北海道の野付半島が代表例です。砂嘴がのびて対岸とつながると砂州になります。' },
      { lv: 2, q: '大地が両側に引きはなされて落ちこんだ、アフリカ東部の巨大な谷を何というか。また、プレート境界の種類を答えよ。', a: '大地溝帯(グレートリフトヴァレー)。広がる境界', exp: 'アフリカ東部では大地が引き裂かれつつあり、細長い谷や湖、火山が並んでいます。プレートが離れていく「広がる境界」の、陸上での例です。' },
      { lv: 3, q: '扇状地の扇央が畑や果樹園に、扇端が水田に利用されやすい理由を、「粒の大きさ」と「水」ということばを使って説明せよ。', a: '扇状地は粒の大きい砂れきでできているため、扇央では水が地下にしみこんで水田に必要な水が得にくい。扇端ではその水がわき出すので、水田に使いやすいから。', exp: '粒が大きいと、すき間が多く水がすぐしみこみます。水が少なくても育つ果樹や畑作物は扇央に、多くの水が必要な稲は扇端に、という分担になります。' },
      { lv: 3, q: 'オーストラリア大陸の東部と西部で、多く産出する鉱産資源のちがいを、大地形と結びつけて説明せよ。', a: '東部には古期造山帯(グレートディヴァイディング山脈)があり石炭が多い。西部は安定陸塊で、鉄鉱石が多い。', exp: '東部の山地は古生代の造山運動でできた古期造山帯で、炭田が分布します。西部は先カンブリア時代の古い岩盤が広がる安定陸塊で、大規模な鉄鉱石の鉱山があります。' },
      { lv: 3, q: '北ヨーロッパやカナダなどには、たくさんの湖が見られる。その理由を、かつての氷河の働きから説明せよ。', a: '氷期に大陸をおおった氷河が地面をけずってくぼ地をつくり、氷河が運んだ土砂(モレーン)が川をせき止めたため、水がたまって多くの湖ができたから。', exp: '氷河は大きな力で地面をけずり、とけた後に土砂を残します。フィンランドが「森と湖の国」とよばれるのも、五大湖ができたのも、氷河の働きと関係があります。' },
      { lv: 3, q: '海のプレートが沈みこむ所では、火山が海溝とほぼ平行に、海溝から一定の距離をおいて並ぶ。その理由を説明せよ。', a: '沈みこんだプレートが一定の深さに達すると、そこでマグマが生まれる。そのため、海溝から同じくらい離れた位置に火山が並ぶから。', exp: 'プレートは海溝から斜めに沈みこむので、マグマができる深さに達する地点は、海溝から一定の距離の所になります。火山が並ぶ前線を火山フロントといい、日本列島にも見られます。' },
      { lv: 3, q: '土砂の量が少ない川が、波の強い海に注いでいる。この河口に三角州が発達しにくい理由と、かわりにできやすい地形を答えよ。', a: '運ばれた土砂が強い波や潮の流れで運び去られ、河口にたまりにくいから。かわりに、河口がラッパ状に広がったエスチュアリー(三角江)などができやすい。', exp: '三角州ができるかどうかは、川の土砂と海の力の「綱引き」で決まります。土砂が少なく海の力が強いと土砂がたまらず、沈んだ河口がそのまま残ってエスチュアリーになります。' }
    ]
  });

  add('gg_agri', {
    pat: [
      { name: 'チューネンの地代曲線で作物の範囲を求める', freq: '難関大で出る', when: '「地代=a−bd」のような式が2つ以上与えられ、どの距離でどの作物がつくられるかを問われたら、この型です。', how: ['各作物の地代が0になる距離(つくれる限界)を求める。', '2つの式が等しくなる距離(入れかわる地点)を求める。', 'その距離より市場に近い側では、地代が高い方の作物(傾きが急な方)がつくられると判断する。'], ex: { q: '市場からの距離をd(km)として、1haあたりの地代が作物Xは60−3d、作物Yは30−dで表される。Xがつくられる範囲とYがつくられる範囲を答えよ。', a: 'X:0〜15km、Y:15〜30km', exp: '60−3d=30−d を解くと d=15 です。それより近い所ではXの地代が高いのでX、遠い所ではYがつくられます。Yの地代は d=30 で0になるので、Yは30kmまでです。' } },
      { name: '気候条件から農業の型を判定する', freq: 'とてもよく出る', when: '気温・降水の季節・土地のやせ方などが示され、行われている農業を問われたら、この型です。', how: ['夏に乾燥する(Cs)なら、樹木作物と冬小麦の地中海式農業を考える。', '冷涼で穀物が育ちにくい・やせた土地なら、牧草を使う酪農を考える。', '乾燥しすぎて作物が育たない所は遊牧や放牧、熱帯で欧米向けの作物ならプランテーションと結びつける。'], ex: { q: '夏はほとんど雨が降らず、冬に雨が多い地域で、ぶどう・オリーブと小麦を組み合わせて行う農業を何というか。', a: '地中海式農業', exp: '夏に乾燥するので、根を深くはる乾燥に強い樹木作物を夏に育て、雨の多い冬に小麦を育てます。気候のリズムに合わせた組み合わせが、地中海式農業の特徴です。' } },
      { name: '土地生産性と労働生産性で農業を比べる', freq: 'よく出る', when: '「集約的」「粗放的」、あるいは面積あたり・1人あたりの生産量を比べる問題は、この型です。', how: ['土地生産性=面積あたりの収穫、労働生産性=働く人1人あたりの収穫と定義を確かめる。', '狭い土地に多くの人手や肥料を入れる農業は、土地生産性が高く労働生産性は低いと考える。', '広い土地を大型機械で少人数で耕す農業は、労働生産性が高く土地生産性は低いと考える。'], ex: { q: '日本の稲作とアメリカの企業的穀物農業を比べたとき、土地生産性が高いのはどちらか。また、労働生産性が高いのはどちらか。', a: '土地生産性は日本の稲作、労働生産性はアメリカの企業的穀物農業が高い。', exp: '日本は狭い田に手間と肥料をかけるので、面積あたりの収穫が多くなります。アメリカは広大な畑を大型機械で少人数で耕すので、1人あたりの生産量がとても多くなります。' } },
      { name: '生産と輸出の「ずれ」から国を判定する', freq: 'よく出る', when: '同じ作物の生産量の上位国と輸出量の上位国が、資料のなかで食いちがっていたら、この型です。', how: ['生産が多いのに輸出が少ない国は、人口が多く国内で消費していると考える。', '生産のわりに輸出が多い国は、人口が少ないか、輸出向けに大規模につくっていると考える。', '輸出の多さは、商品作物や企業的農業の国と結びつける。'], ex: { q: 'ある作物について、人口がとても多い国Pは生産量が多いのに、輸出量はほとんどない。この理由として考えられることを答えよ。', a: '国内の人口が多く、生産した作物の多くを国内で消費しているから。', exp: '輸出できるのは、国内で使い切れずに余った分です。人口大国では主食などの作物の多くが国内で消費されるため、生産量が多くても輸出量は少なくなります。資料を読むときは人口の大きさも思い出しましょう。' } },
      { name: '作物の栽培条件から作物を判定する', freq: 'よく出る', when: '「高温多雨」「乾季がある」「水はけのよい斜面」など、作物の育つ条件が書かれ、作物名を問われたら、この型です。', how: ['気温(熱帯・温帯・冷涼)の条件を見る。', '降水の量と季節(多雨・乾季が必要・乾燥に強い)を見る。', '地形の条件(水はけのよい斜面・平らな低地)を見て、作物を一つにしぼる。'], ex: { q: '温暖で雨が多く、しかも水はけのよい丘陵や山の斜面が栽培に向いている作物はどれか。米・茶・なつめやし・小麦から選べ。', a: '茶', exp: '茶は雨を多く必要としますが、根が水につかると弱るため、水はけのよい斜面が適しています。米は水を張れる平らな低地、なつめやしは乾燥地のオアシス、小麦はやや乾燥した冷涼な所が向いています。' } }
    ],
    more: [
      { lv: 1, q: '作物の栽培と家畜の飼育を組み合わせて行う、ヨーロッパで発達した農業を何というか。', a: '混合農業', exp: '混合農業は、小麦などの食用作物と、えさになる作物を順番に育て、豚や牛などの家畜を飼う農業です。家畜のふんは肥料になり、土地の力を保てます。' },
      { lv: 1, q: '熱帯の地域で、欧米の資本などにより、輸出向けの作物を大規模に単一栽培する農業を何というか。', a: 'プランテーション農業', exp: 'プランテーションでは、コーヒー・カカオ・天然ゴム・バナナなどが大規模につくられてきました。植民地時代に始まったものが多く、特定の作物にたよる経済の原因にもなりました。' },
      { lv: 1, q: '乳牛を飼い、牛乳やバター・チーズなどを生産する農業を何というか。', a: '酪農', exp: '酪農は、牧草がよく育つ冷涼な地域でさかんです。牛乳はいたみやすいので、昔は大都市の近くで行われましたが、冷蔵輸送の発達で遠い地域でも行われるようになりました。' },
      { lv: 1, q: '農業の立地条件のうち、市場までの距離や交通の便は、自然条件と社会条件のどちらにあたるか。', a: '社会条件', exp: '気温・降水量・地形・土壌は自然条件、市場との距離・交通・技術・政策などは社会条件です。農業の場所は、この両方の組み合わせで決まります。' },
      { lv: 1, q: '次のうち、自給的農業ではないものはどれか。', choices: ['遊牧', '焼畑農業', 'アジアの集約的稲作', '企業的穀物農業'], a: 'D(企業的穀物農業)', exp: '企業的穀物農業は、大規模に穀物をつくって売ることを目的にした商業的な農業です。遊牧・焼畑・アジアの稲作は、自分たちが食べることを中心に発達した自給的農業です。' },
      { lv: 1, q: '森林や草原を焼き、その灰を肥料に作物を育て、土地がやせると別の場所へ移る農業を何というか。', a: '焼畑農業', exp: '焼畑農業は、熱帯の森林地域などで行われてきた自給的な農業です。十分な休閑期間をおけば森林は回復しますが、期間が短くなると森林破壊につながります。' },
      { lv: 1, q: 'アジアの季節風(モンスーン)の影響を受ける地域で、稲作がさかんな理由を、気候の特色から答えよ。', a: '夏に高温で雨が多いから。', exp: '稲は、育つ時期に高い気温とたくさんの水を必要とします。季節風が夏に海から湿った空気を運ぶアジアの地域は、稲作に適しています。' },
      { lv: 2, q: 'チューネンの孤立国のモデルで、市場に最も近い所で行われる農業はどれか。', choices: ['三圃式農業', '林業', '自由式農業(野菜・牛乳など)', '牧畜'], a: 'C(自由式農業(野菜・牛乳など))', exp: '野菜や牛乳は、いたみやすく輸送費が高いので、市場の近くでつくられます。市場から遠ざかるにつれ、林業・輪栽式・穀草式・三圃式・牧畜の順に並びます。' },
      { lv: 2, q: '市場からの距離をd(km)として、1haあたりの地代が作物Xは50−5d、作物Yは20−dで表される。Xがつくられる範囲とYがつくられる範囲を答えよ。', a: 'X:0〜7.5km、Y:7.5〜20km', exp: '50−5d=20−d より 4d=30、d=7.5 です。それより近い所ではXの地代が高いのでXがつくられます。Yの地代は d=20 で0になるので、Yは20kmまでです。' },
      { lv: 2, q: '日本の稲作の特色として正しいものはどれか。', choices: ['土地生産性も労働生産性も低い', '土地生産性は高いが、労働生産性は低い', '土地生産性は低いが、労働生産性は高い', '土地生産性も労働生産性も高い'], a: 'B(土地生産性は高いが、労働生産性は低い)', exp: '日本はせまい田に多くの手間や肥料をかける集約的な稲作なので、面積あたりの収穫は多いですが、1人あたりの経営面積がせまく、労働生産性は低くなります。' },
      { lv: 2, q: '酪農が、冷涼な地域や氷河に土をけずられたやせた土地で発達しやすい理由を答えよ。', a: '冷涼でやせた土地では穀物は育ちにくいが、牧草は育つので、牧草を食べる乳牛を飼う酪農が向いているから。', exp: '北海道や、ヨーロッパの北海沿岸のように、穀物には不向きでも牧草がよく育つ所で酪農がさかんです。気候と土地の条件を生かした農業の例です。' },
      { lv: 2, q: '北極海沿岸のツンドラ地域で、遊牧されている家畜はどれか。', choices: ['ラクダ', 'トナカイ', 'リャマ', 'ヤク'], a: 'B(トナカイ)', exp: 'ツンドラでは、こけ類を食べるトナカイが遊牧されます。ラクダは乾燥地、リャマやアルパカはアンデスの高地、ヤクはチベットなどの高地で飼われます。' },
      { lv: 2, q: '焼畑農業で、休閑期間(土地を休ませる期間)が短くなると、どのような問題が起こるか。', a: '森林が十分に回復しないうちに再び焼くため、土地がやせて森林破壊が進む。', exp: '人口が増えると、同じ土地を早く使い回すようになります。すると森林も土の養分も戻らず、収穫が減り、さらに新しい森林を焼くという悪循環になります。' },
      { lv: 2, q: 'アメリカやオーストラリアの企業的穀物農業の特色として正しいものはどれか。', choices: ['せまい土地に多くの人手をかける', '大型機械を使い、労働生産性が高い', '家族が食べる分だけをつくる', '市場の近くでいたみやすい作物をつくる'], a: 'B(大型機械を使い、労働生産性が高い)', exp: '企業的穀物農業は、広い土地で小麦などを大型機械を使って少人数でつくり、輸出します。労働生産性は高いですが、面積あたりの収穫(土地生産性)は高くありません。' },
      { lv: 2, q: '高収量品種の導入による「緑の革命」には、どのような問題点があったか。1つ答えよ。', a: '灌漑設備や化学肥料・農薬を買える豊かな農家と、買えない貧しい農家の格差が広がった。', exp: '高収量品種は、水や肥料をたっぷり与えて初めて多く実ります。そのため、お金のある農家ほど恩恵を受けました。農薬・肥料の使いすぎによる環境への影響も指摘されています。' },
      { lv: 3, q: '市場からの距離をd(km)として、1haあたりの地代が作物Xは72−4d、作物Yは36−1.5dで表される。Xがつくられる範囲とYがつくられる範囲を答えよ。', a: 'X:0〜14.4km、Y:14.4〜24km', exp: '72−4d=36−1.5d より 2.5d=36、d=14.4 です。Yの地代が0になるのは 36÷1.5=24km です。傾きが急なX(輸送費が高い作物)が市場の近くを占めます。' },
      { lv: 3, q: '冷凍・保冷輸送や航空輸送の発達は、チューネンのモデルで説明される農業の配置にどのような変化をもたらしたか。具体例をあげて説明せよ。', a: 'いたみやすい作物も遠くから運べるようになり、市場からの距離より気候などの条件が重視されるようになった。たとえば、遠くの暖かい地域で野菜や花をつくる輸送園芸が発達した。', exp: 'チューネンのモデルは「輸送費は距離に比例する」という前提にもとづきます。輸送技術が進むと距離の制約が小さくなり、同心円の配置はくずれます。遠い国の酪農が成り立つのも同じ理由です。' },
      { lv: 3, q: '畜産物を国内で生産していても、カロリーで計算した食料自給率が上がりにくいことがある。その理由を「飼料」ということばを使って説明せよ。', a: '家畜のえさ(飼料)を輸入にたよっている場合、その分は国産とみなされないため、畜産物を国内で生産しても自給率には十分反映されないから。', exp: 'カロリーベースの自給率では、輸入飼料で育てた家畜の肉や卵は、その飼料の分を国産から差し引いて計算します。食べ物の「もと」がどこから来ているかまで考えるのがポイントです。' },
      { lv: 3, q: 'アメリカ合衆国では、西経100度付近を境に、西側と東側で農業が大きくちがう。その理由と、それぞれの主な農業を説明せよ。', a: '西経100度付近はおよそ年降水量500mmの線にあたり、それより西は乾燥しているので牛の放牧や灌漑農業が中心になる。東は降水が多いので、とうもろこしや大豆の栽培と家畜の飼育などがさかんである。', exp: 'アメリカでは、降水量や気温に合わせて作物を分ける「適地適作」が行われています。降水量の線と農業の分布が重なることは、地図で確かめておきたいポイントです。' },
      { lv: 3, q: '食料を輸入している国は、間接的に輸出国の水も使っているといえる。この考え方を何というか。また、その意味を説明せよ。', a: '仮想水(バーチャルウォーター)。輸入した食料を自国でつくるとしたら必要だった水の量のことで、食料の輸入を通して、他国の水資源を使っていると考える。', exp: '穀物や肉をつくるには大量の水が必要です。食料を多く輸入する国は、その分の水を輸出国にたよっていることになります。水不足の地域で輸出用の作物をつくることの問題も見えてきます。' }
    ]
  });

  add('gg_industry', {
    pat: [
      { name: '原料指数で工業の立地の型を判定する', freq: 'とてもよく出る', when: '製品1tをつくるのに必要な原料の重さが示され、工場の立地を問われたら、この型です。', how: ['特定の産地でしかとれない局地原料と、どこでも手に入る普遍原料(水など)を分ける。', '原料指数=局地原料の重さ÷製品の重さ を計算する。', '1より大きければ原料地(重さが減る前に近くで加工)、1より小さければ市場(普遍原料を市場で加える)に立地すると判断する。'], ex: { q: '製品2.4tをつくるのに、局地原料0.8tと、どこでも手に入る水1.6tを使う工業がある。原料指数を求め、立地の型を答えよ。', a: '原料指数は約0.33。市場指向型', exp: '原料指数は 0.8÷2.4≒0.33 で、1より小さくなります。重い水はどこでも手に入るので、市場で加えて製品にすれば輸送費が安くすみます。ビールや清涼飲料水の工場がこの型です。' } },
      { name: '輸送費を比べて工場の位置を決める', freq: 'よく出る', when: '原料地と市場の距離、原料と製品の1tあたりの輸送費が与えられ、どこに工場を建てるかを問われたら、この型です。', how: ['工場を原料地に置いたときの輸送費(製品を市場まで運ぶ)を計算する。', '工場を市場に置いたときの輸送費(原料を市場まで運ぶ)を計算する。', '2つを比べ、安い方を選ぶ。重さだけでなく、1tあたりの輸送費のちがいにも注意する。'], ex: { q: '製品1tをつくるのに局地原料2tを使う。原料地Pと市場Qは100km離れ、輸送費は原料も製品も1tを1km運ぶごとに1円かかる。工場はP・Qのどちらに置くと輸送費が安いか。', a: 'P(原料地)', exp: 'Pに置くと製品1tを100km運ぶので100円、Qに置くと原料2tを100km運ぶので200円かかります。原料が重く、加工すると軽くなる工業は、原料地に立地すると有利です。' } },
      { name: '工業の特色から立地のタイプを当てる', freq: 'とてもよく出る', when: '「製品が軽くて高価」「人手が多く必要」「大量の電力を使う」など、工業の性質が書かれていたら、この型です。', how: ['費用のうちで何が最も大きいか(原料・輸送・人件費・電力・情報など)を見つける。', '人件費なら労働力指向(賃金の安い地域)、電力なら電力指向、製品が軽く高価なら臨空港型と結びつける。', '情報や流行が大事な工業は、大都市に立地する(市場・情報指向)と考える。'], ex: { q: '衣類の縫製工場が、賃金の安い国や地域に多く移ってきた。この工業の立地の型を答えよ。', a: '労働力指向型', exp: '衣類の縫製は機械化が難しく、多くの人手が必要なので、費用にしめる人件費の割合が大きくなります。そのため、賃金の安い地域に工場を置くと有利になります。' } },
      { name: '国際分業とスマイルカーブ', freq: '難関大で出る', when: '製品の開発・部品・組み立て・販売などの工程が国ごとに分かれている話や、付加価値の高い工程を問う問題は、この型です。', how: ['工程を「研究開発・部品」「組み立て」「販売・サービス」の順に並べる。', '付加価値(もうけ)は両端の研究開発や販売で大きく、まん中の組み立てで小さい(スマイルカーブ)ことを思い出す。', '組み立ては賃金の安い国へ、研究開発やブランド管理は先進国に残りやすいと説明する。'], ex: { q: 'スマートフォンの生産で、先進国の企業が設計やブランド管理を自国で行い、組み立てを外国の工場に任せることが多い。その理由を付加価値から説明せよ。', a: '設計やブランド管理は付加価値が高く利益が大きいが、組み立ては付加価値が低く、賃金の安い国で行う方が費用をおさえられるから。', exp: '組み立てはまねしやすく競争が激しいので、もうけが小さくなります。一方、技術開発やデザイン、販売はまねしにくく利益が大きい工程です。これをグラフにすると笑った口の形になるので、スマイルカーブとよばれます。' } },
      { name: 'エネルギー資源の分布と、その理由', freq: 'よく出る', when: '石炭・石油・天然ガスなどが「どこで多くとれるか」「なぜそこなのか」を問われたら、この型です。', how: ['石炭は古期造山帯の周辺、石油や天然ガスは新期造山帯や大きな堆積盆地(背斜構造)に多いと整理する。', '日本はエネルギー資源のほとんどを輸入にたよっていることを確かめる。', '原油はペルシア湾岸(中東)の産油国にかたよって分布していることと結びつける。'], ex: { q: '日本が輸入する原油の多くは、どの地域の国々から来ているか。また、それがエネルギー政策の課題になる理由を答えよ。', a: '中東(ペルシア湾岸)の国々。特定の地域にたよると、その地域で紛争などが起きたときに輸入がとだえるおそれがあるから。', exp: '原油はペルシア湾岸に埋蔵がかたよっています。日本は長く中東から多くの原油を輸入してきたため、石油危機のような事態に弱いのです。輸入先やエネルギーの種類を分散させることが課題になります。' } }
    ],
    more: [
      { lv: 1, q: '18世紀後半に、世界で最初に産業革命が始まった国はどこか。', a: 'イギリス', exp: 'イギリスでは、綿工業で機械が使われ、蒸気機関が動力になりました。豊富な石炭と鉄、植民地の市場などが、産業革命を支えました。' },
      { lv: 1, q: '主なエネルギー源が、石炭から石油へと大きく移り変わったことを何というか。', a: 'エネルギー革命', exp: '日本では1960年代にエネルギー革命が進みました。石油は液体で運びやすく、燃料としても化学製品の原料としても使いやすいためです。' },
      { lv: 1, q: '次のうち、再生可能エネルギーではないものはどれか。', choices: ['太陽光', '風力', '地熱', '天然ガス'], a: 'D(天然ガス)', exp: '天然ガスは石油や石炭と同じ化石燃料で、使えばなくなります。太陽光・風力・地熱・水力などは、自然の中でくり返し生まれるので再生可能エネルギーといいます。' },
      { lv: 1, q: '日本で、原料や燃料を輸入して大規模に生産するため、海ぞい(臨海部)に立地しやすい工業はどれか。', choices: ['IC(集積回路)工業', '鉄鋼業', '出版・印刷業', '衣類の縫製業'], a: 'B(鉄鋼業)', exp: '鉄鋼業は、鉄鉱石や石炭を大量に輸入して使います。重い原料を船からすぐ工場に入れられる臨海部が有利です。石油化学工業も同じ理由で臨海部に多く見られます。' },
      { lv: 1, q: '多くの工場が一か所に集まることで、部品の調達や情報交換がしやすくなる利点を何というか。', a: '集積の利益', exp: '工場が集まると、部品工場との取引や輸送が効率よくなり、技術者や情報も集まります。自動車工業の周りに部品工場が集まるのはこのためです。' },
      { lv: 1, q: 'アメリカ合衆国で、北緯37度付近より南にある、温暖で1970年代以降に工業が発達した地域を何とよぶか。', a: 'サンベルト', exp: 'サンベルトは、温暖な気候、安い土地や労働力、豊富な石油などを背景に、航空宇宙産業や先端技術産業が発達しました。北部の古い工業地域はスノーベルト(フロストベルト)ともよばれます。' },
      { lv: 1, q: '国内の企業が工場を海外に移した結果、国内の製造業がおとろえることを何というか。', a: '産業の空洞化', exp: '人件費の安い国へ工場が移ると、国内の工場が減り、働く場所が少なくなります。特に、工場に依存していた地方の町では大きな影響が出ます。' },
      { lv: 2, q: '製品1tをつくるのに、局地原料0.5tと、どこでも手に入る水1.5tを使う工業がある。原料指数を求め、立地の型を答えよ。', a: '原料指数0.5。市場指向型', exp: '原料指数は 0.5÷1=0.5 で1より小さいので、市場の近くに工場を置く方が輸送費が安くなります。重い水を遠くから運ぶ必要がないからです。' },
      { lv: 2, q: 'IC(集積回路)の工場が、空港や高速道路のインターチェンジの近くに多く立地する理由を答えよ。', a: '製品が小さく軽いのに高価なので、航空機やトラックで運んでも輸送費の負担が小さく、すばやく出荷できるから。', exp: '値段のわりに輸送費が小さいので、遠くへ運んでも利益が出ます。九州や東北の空港・高速道路ぞいに半導体工場が多いのは、この性質のためです。' },
      { lv: 2, q: '製品1tをつくるのに局地原料1tを使い、重さは変わらないが、製品は形がこわれやすく、1tあたりの輸送費が原料の3倍かかる工業がある。工場は原料地と市場のどちらに置くと有利か。', a: '市場', exp: '重さが変わらないので、輸送する重さはどちらでも同じです。しかし製品の方が運びにくく輸送費が高いので、原料を運んで市場で製品にする方が安くすみます。' },
      { lv: 2, q: '繊維・衣類の工業が、先進国から発展途上国へ移りやすいのはなぜか。', a: '機械化しにくく多くの人手が必要で、賃金の安い国で生産すると費用を大きくおさえられるから(労働力指向)。', exp: '繊維工業は、設備にあまりお金がかからず、技術も比較的身につけやすい工業です。そのため、工業化を始める国の最初の産業にもなりやすいのです。' },
      { lv: 2, q: 'アメリカの五大湖の周辺で、鉄鋼業が早くから発達した理由を答えよ。', a: '五大湖の西側で鉄鉱石が、アパラチア山脈で石炭がとれ、五大湖の水運を使って原料を安く運ぶことができたから。', exp: '鉄鋼業には鉄鉱石と石炭が大量に必要です。五大湖周辺は両方の原料を水運で結びつけられたので、ピッツバーグなどに鉄鋼業が発達しました。' },
      { lv: 2, q: '太陽光や風力による発電の弱点として正しいものはどれか。', choices: ['燃料を輸入しなければならない', '天候や時間によって発電量が大きく変わる', '発電のときに二酸化炭素を大量に出す', '資源がいずれなくなる'], a: 'B(天候や時間によって発電量が大きく変わる)', exp: '太陽光は夜や雨の日に発電できず、風力は風の強さで発電量が変わります。安定して電気を送るには、蓄電池やほかの発電との組み合わせが必要です。' },
      { lv: 2, q: '先端技術産業(ハイテク産業)が、大学や研究機関の近くに集まりやすい理由を答えよ。', a: '新しい技術の開発に、専門知識をもつ研究者や技術者、最新の研究成果が欠かせないから。', exp: '先端技術産業では、原料や輸送費より「知識」が重要です。アメリカのシリコンヴァレーのように、大学と企業が協力する地域に企業が集まります。' },
      { lv: 2, q: '日本で地熱発電の資源が豊富だといわれる理由を答えよ。', a: '火山が多く、地下に高温のマグマや熱水があるから。', exp: '日本は新期造山帯にあり、火山が多い国です。地熱発電は天候に左右されにくい長所がありますが、適地が国立公園や温泉地と重なることが多く、開発には調整が必要です。' },
      { lv: 3, q: '製品1tをつくるのに局地原料1.5tを使う。原料地Pと市場Qは120km離れている。輸送費は、原料が1tを1km運ぶごとに1円、製品が1tを1km運ぶごとに2円かかる。工場はP・Qのどちらに置くと輸送費が安いか。それぞれの輸送費も答えよ。', a: 'Q(市場)。Pに置くと240円、Qに置くと180円', exp: 'Pでは製品1tを120km、2円で運ぶので 1×120×2=240円、Qでは原料1.5tを120km、1円で運ぶので 1.5×120×1=180円です。原料指数が1より大きくても、製品の輸送費が高いと市場が有利になります。' },
      { lv: 3, q: 'アルミニウムの精錬工場が、水力発電などで電力が安く得られる地域に立地しやすい理由を答えよ。', a: '原料のボーキサイトからアルミニウムを取り出すときに、大量の電力が必要で、費用にしめる電気代の割合が大きいから(電力指向)。', exp: 'アルミニウムは「電気のかたまり」とよばれるほど電力を使います。そのため、電気代の高い日本では精錬がほとんど行われなくなり、電力の安い国から地金を輸入するようになりました。' },
      { lv: 3, q: '工業がある地域に集まりすぎると、どのような不利益が生じるか。また、その結果として工場はどのように動くか。', a: '地価の上昇、交通渋滞、用地や労働力の不足、公害などの不利益が生じる。そのため、工場は郊外や地方、海外へ分散するようになる。', exp: '集積には利益だけでなく不利益(集積の不経済)もあります。日本でも高度経済成長期に太平洋ベルトへ工場が集中し、その後、地方や海外への移転が進みました。' },
      { lv: 3, q: '1970年代の石油危機の後、日本の工業の中心が「重厚長大」型から「軽薄短小」型へ移っていった理由を説明せよ。', a: '石油の値段が大きく上がり、大量のエネルギーと原料を使う鉄鋼・石油化学などの重化学工業の費用が増えた。そのため、エネルギーをあまり使わず付加価値の高い電子機器などの工業が成長したから。', exp: '重厚長大は鉄鋼・造船などの重くて大きい製品の工業、軽薄短小は半導体・電子機器などの小さく高付加価値な製品の工業を指します。エネルギーの値段の変化が、産業構造を変えた例です。' },
      { lv: 3, q: '先進国の企業が発展途上国に工場を移すと、受け入れた国にはどのような利点と課題があるか。それぞれ1つずつ答えよ。', a: '利点:雇用が生まれ、技術や資本が入ってきて工業化が進む。課題:外国企業の都合で工場が撤退すると雇用が失われるなど、経済が外国企業に左右されやすい。', exp: '外国からの直接投資は工業化の大きな力になります。一方で、より賃金の安い国が現れると工場が移ってしまうこともあり、自国の技術や企業を育てることが課題になります。' }
    ]
  });

  add('gg_pop', {
    pat: [
      { name: '人口ピラミッドの型から国や地域を判定する', freq: 'とてもよく出る', when: '年齢別・男女別の人口のグラフが示され、どの国・地域か、どの段階かを問われたら、この型です。', how: ['すその幅(子どもの多さ)を見て、出生率の高低を判断する。', '上の方(高齢者)の幅を見て、平均寿命や高齢化の進み具合を判断する。', '富士山型=発展途上国、釣鐘型=安定、つぼ型=少子化の進んだ先進国と結びつける。', '特定の年代だけがふくらむ・へこむときは、人口移動(星型=都市、ひょうたん型=農村)を考える。'], ex: { q: '20〜30歳代の人口がとくに多く、子どもや高齢者が少ない、星のような形の人口ピラミッドは、大都市と農村のどちらに多いか。', a: '大都市', exp: '大都市には、進学や就職のために若い人が多く集まってきます。その結果、生産年齢の中でも若い世代がふくらんだ星型になります。反対に、若者が流出する農村ではその部分がへこんだひょうたん型になります。' } },
      { name: '自然増加と社会増加から人口の変化を計算する', freq: 'よく出る', when: '出生率・死亡率・転入・転出などの割合が示され、人口の増減を問われたら、この型です。', how: ['自然増加率=出生率−死亡率 を求める。', '社会増加率=転入率−転出率 を求める。', '人口増加率=自然増加率+社会増加率 とし、もとの人口にかけて増減を出す。'], ex: { q: 'ある町の1年間の出生率は0.6%、死亡率は1.4%、社会増加率は+0.3%だった。人口5万人のこの町の1年後の人口を答えよ。', a: '49750人', exp: '自然増加率は 0.6−1.4=−0.8% で、社会増加率を足すと −0.8+0.3=−0.5% です。50000×0.005=250人減るので、1年後は49750人です。死亡が出生を上回る、高齢化の進んだ町の姿です。' } },
      { name: '70の法則で人口が2倍になる年数を求める', freq: 'よく出る', when: '人口や経済の年増加率(%)が示され、「何年で2倍になるか」を問われたら、この型です。', how: ['2倍になる年数 ≒ 70 ÷ 年増加率(%) を使う。', '反対に、2倍になる年数がわかれば、70÷年数 で増加率を出せる。', '増加率が小さいほど、2倍になるまでの年数が長くなることを確かめる。'], ex: { q: '人口の年増加率が2%の国の人口は、この増加率が続くと、およそ何年で2倍になるか。', a: '約35年', exp: '70÷2=35 なので、およそ35年で2倍になります。わずか2%の増加でも、35年で人口が倍になるので、学校や仕事・食料をそれだけ増やす必要があります。' } },
      { name: '昼夜間人口比率で都市の性格を読む', freq: 'よく出る', when: '夜間人口(住んでいる人口)と、通勤・通学で出入りする人数が示されたら、この型です。', how: ['昼間人口=夜間人口+流入人口−流出人口 を求める。', '昼夜間人口比率=昼間人口÷夜間人口×100 を計算する。', '100より大きければ人が集まる中心都市、100より小さければ周りの都市へ通う衛星都市(ベッドタウン)と判断する。'], ex: { q: '夜間人口30万人の都市に、通勤・通学で9万人が入ってきて、3万人が出ていく。昼夜間人口比率を求め、都市の性格を答えよ。', a: '120。周りから人が集まる中心都市', exp: '昼間人口は 30+9−3=36万人で、36÷30×100=120 です。100を上回るので、昼間に人が集まる中心都市です。オフィスや学校が多い都市で高くなります。' } },
      { name: '人口転換の段階を判定する', freq: 'とてもよく出る', when: '出生率と死亡率の高さの組み合わせや、その変化が示され、国の発展段階を問われたら、この型です。', how: ['多産多死→多産少死→少産少死の順に進むことを思い出す。', '死亡率は医療や衛生の改善で先に下がり、出生率はあとから下がることを確かめる。', '多産少死の段階で人口が急増し、少産少死では増加がゆるやかになると説明する。'], ex: { q: 'ある国では、出生率は高いままだが、医療の普及で死亡率が急に下がった。この国は人口転換のどの段階にあり、人口はどう変化するか。', a: '多産少死の段階。人口が急に増える(人口爆発)。', exp: '死亡率が下がっても、子どもを多く産む習慣や考え方はすぐには変わりません。生まれる人が亡くなる人を大きく上回るので、人口が急増します。多くの発展途上国がこの段階を経験してきました。' } }
    ],
    more: [
      { lv: 1, q: '人口転換で、医療や教育が普及した先進国が最後に到達する段階を何というか。', a: '少産少死', exp: '少産少死では、出生率も死亡率も低くなり、人口の増加はゆるやかになります。さらに出生率が下がると、人口が減り始めることもあります。' },
      { lv: 1, q: '1人の女性が一生のうちに産む子どもの平均の数を表す指標を何というか。', a: '合計特殊出生率', exp: '合計特殊出生率は、少子化の進み具合を表す代表的な指標です。この値が人口置換水準(約2.1)を下回る状態が続くと、長い目で見て人口は減っていきます。' },
      { lv: 1, q: '総人口にしめる65歳以上の人口の割合が21%をこえた社会を何というか。', choices: ['高齢化社会', '高齢社会', '超高齢社会', '少子社会'], a: 'C(超高齢社会)', exp: '65歳以上の割合が7%をこえると高齢化社会、14%をこえると高齢社会、21%をこえると超高齢社会とよびます。数字の区切り(7・14・21)を覚えておきましょう。' },
      { lv: 1, q: '出生率・死亡率がともに低く、子どもから高齢者まで各年代の人口がほぼ同じくらいの人口ピラミッドの型を何というか。', a: '釣鐘型', exp: '釣鐘型は、少産少死になって人口がほぼ安定している状態を表します。さらに出生率が下がり、すそがすぼまるとつぼ型になります。' },
      { lv: 1, q: '若者が都市へ流出して人口が大きく減り、地域の生活を維持することが難しくなることを何というか。', a: '過疎', exp: '過疎の地域では、学校や病院、商店、公共交通などが維持しにくくなります。反対に、人口が集中しすぎて問題が起こることを過密といいます。' },
      { lv: 1, q: '大都市に人口や産業が集まりすぎて、住宅不足・交通渋滞・ごみ問題などが起こる状態を何というか。', a: '過密', exp: '過密は、人や企業が限られた場所に集中することで起こります。通勤ラッシュや地価の上昇も、過密の代表的な問題です。' },
      { lv: 1, q: '発展途上国の大都市で、仕事を求めて農村から移ってきた人々などが住む、生活環境の悪い地区を何というか。', a: 'スラム', exp: 'スラムは、上下水道や電気などが整っていない住宅が密集した地区です。急激な都市化に、住宅や雇用の整備が追いつかないことが原因です。' },
      { lv: 2, q: 'ある市の1年間の自然増加率は+0.3%、社会増加率は−0.8%だった。人口8万人のこの市の1年後の人口を答えよ。', a: '79600人', exp: '人口増加率は 0.3+(−0.8)=−0.5% です。80000×0.005=400人減るので、79600人になります。子どもは生まれているが、それ以上に人が転出している市です。' },
      { lv: 2, q: '人口の年増加率が3.5%の国の人口は、この増加率が続くと、およそ何年で2倍になるか。', a: '約20年', exp: '70の法則を使うと 70÷3.5=20 なので、およそ20年で2倍になります。増加率が大きい国ほど、2倍になる年数が短くなります。' },
      { lv: 2, q: '夜間人口40万人の都市から、通勤・通学で12万人が出ていき、4万人が入ってくる。昼夜間人口比率を求め、都市の性格を答えよ。', a: '80。大都市へ通う人が多く住む衛星都市(ベッドタウン)', exp: '昼間人口は 40−12+4=32万人で、32÷40×100=80 です。100を下回るので、昼は人が周りの都市へ出かけていく、住宅中心の都市だとわかります。' },
      { lv: 2, q: 'つぼ型の人口ピラミッドを示す国で、将来起こりやすい問題として正しいものはどれか。', choices: ['子どもが急に増えて学校が足りなくなる', '働く世代が減り、社会保障の負担が重くなる', '若い世代が多すぎて失業が増える', '死亡率が上がって平均寿命が短くなる'], a: 'B(働く世代が減り、社会保障の負担が重くなる)', exp: 'つぼ型は、子どもが少なく高齢者が多い型です。これから働く世代が減るので、年金や医療をささえる人が少なくなり、1人あたりの負担が重くなります。' },
      { lv: 2, q: 'ある町の人口ピラミッドは、20〜30歳代の部分がくびれるようにへこみ、子どもと高齢者の部分がふくらんだ形をしていた。このような形を何型といい、どのような地域に多いか。', a: 'ひょうたん型。若い世代が都市へ流出する農村や地方の町', exp: '進学や就職で若者が出ていくため、その年代だけがへこみます。残った親世代や祖父母世代、その地域で育つ子どもの部分がふくらんで、ひょうたんのように見えます。' },
      { lv: 2, q: '発展途上国で、首都などの一つの大都市に人口が集中しやすい理由を答えよ。', a: '農村では仕事や収入が少ない一方、首都には工場や商業、政府の機関、学校などが集まり、仕事や豊かな生活を求めて人が移り住むから。', exp: '農村から押し出す力(貧困・土地不足)と、都市に引きよせる力(仕事・教育・医療)の両方が働きます。その結果、プライメートシティが生まれ、スラムなどの問題も起こります。' },
      { lv: 2, q: '街道にそって家が並び、宿場町などとして商業が発達した村落の形態を何というか。', choices: ['路村', '街村', '円村', '散村'], a: 'B(街村)', exp: '街村は、街道ぞいに家が並び、商業機能をもつ村落です。路村も道にそって家が並びますが、農業が中心で商業機能は弱いのがちがいです。' },
      { lv: 2, q: '人口1000万人の国で、65歳以上の人口が220万人いる。高齢化率を求め、高齢化の段階を答えよ。', a: '22%。超高齢社会', exp: '220÷1000×100=22% です。21%をこえているので超高齢社会です。割合を計算してから、7%・14%・21%の区切りと比べましょう。' },
      { lv: 3, q: 'ある国の人口が、一定の増加率で28年かかって2倍になった。この国の人口の年増加率はおよそ何%か。', a: '約2.5%', exp: '70の法則を逆に使うと、年増加率≒70÷28=2.5% です。「年数×増加率≒70」という関係を覚えておくと、どちらの方向にも計算できます。' },
      { lv: 3, q: 'ある国の人口の割合は、年少人口(0〜14歳)が15%、生産年齢人口(15〜64歳)が60%、老年人口(65歳以上)が25%である。従属人口指数(生産年齢人口100人あたりの年少・老年人口)を求めよ。小数第1位を四捨五入せよ。', a: '約67', exp: '従属人口は 15+25=40% で、40÷60×100=66.6… なので約67です。働く世代100人で、子どもと高齢者を約67人ささえている計算になります。' },
      { lv: 3, q: '人口が減っている地方都市で、「コンパクトシティ」をめざす取り組みが進められている。そのねらいを説明せよ。', a: '住宅や商業施設、病院などを中心部や駅の近くに集め、郊外への広がりをおさえる。そうすることで、道路や上下水道などの維持費をおさえ、車がなくても暮らしやすい町にすることがねらい。', exp: '人口が減っても市街地が広いままだと、インフラの維持に多くの費用がかかり、公共交通も成り立ちにくくなります。高齢者が歩いて暮らせるようにすることも大きな目的です。' },
      { lv: 3, q: '1990年代後半ごろから、東京の都心部で人口が再び増える「都心回帰」が見られるようになった。その理由を説明せよ。', a: 'バブル経済の崩壊後に地価が下がり、都心に高層マンションなどの住宅が多く建てられて、通勤に便利な都心に住む人が増えたから。', exp: '地価が高かった時期には、人々は郊外に住み、長時間かけて通勤していました(ドーナツ化現象)。地価の下落や再開発で、都心に住宅を手に入れやすくなったことが、流れを変えました。' },
      { lv: 3, q: '少子高齢化が進む国が、外国から働き手を受け入れることには、どのような利点と課題があるか。それぞれ1つずつ答えよ。', a: '利点:人手不足の産業で働き手を確保できる。課題:言語や生活習慣のちがいへの支援、労働条件や権利を守るしくみが必要になる。', exp: '外国人労働者は、介護や建設、農業などで欠かせない存在になっています。受け入れるだけでなく、子どもの教育や地域での共生など、生活全体をささえる取り組みが課題です。' }
    ]
  });

  add('gg_region', {
    pat: [
      { name: '言語・宗教から植民地の歴史と国を判定する', freq: 'とてもよく出る', when: '国の公用語や主な宗教が手がかりとして示され、国名や旧宗主国を問われたら、この型です。', how: ['公用語がヨーロッパの言語なら、旧宗主国を考える(英語→イギリス、フランス語→フランス、スペイン語→スペイン、ポルトガル語→ポルトガル)。', '宗教の分布を思い出す(西アジア・北アフリカ・インドネシアはイスラーム、フィリピンや中南米はカトリックなど)。', '言語と宗教の組み合わせで国を一つにしぼる。'], ex: { q: '東南アジアの国で、かつてスペインの植民地、のちにアメリカの統治を受け、カトリックの信者が多く、英語も公用語の国はどこか。', a: 'フィリピン', exp: 'フィリピンはスペインの植民地時代にカトリックが広まりました。その後アメリカに統治されたため英語が広く使われ、フィリピノ語とともに公用語になっています。歴史の順番が手がかりになります。' } },
      { name: '「決め手の指標」で国を判定する', freq: 'よく出る', when: '複数の国の統計や特徴が並び、それぞれがどの国かを問われたら、この型です。', how: ['ほかの国と大きくちがう「とびぬけた特徴」を一つ探す(宗教・言語・主な輸出品・気候など)。', '最も確実な一国を先に決める。', 'のこりの国を、消去法で残りの特徴とつき合わせる。'], ex: { q: 'A〜Cは、タイ・マレーシア・インドネシアのいずれか。Aは東南アジアで唯一植民地にならなかった仏教国、Bは島が多くイスラームの信者がとても多い国、Cはマレー系・中国系・インド系の人々が暮らす国である。A〜Cを答えよ。', a: 'A:タイ、B:インドネシア、C:マレーシア', exp: '「植民地にならなかった」「仏教」はタイの決め手です。島が多くイスラームの信者が多いのはインドネシア、マレー系・中国系・インド系の多民族国家はマレーシアです。確実な手がかりから順に決めます。' } },
      { name: '工業化の道すじ(輸入代替から輸出指向へ)', freq: 'よく出る', when: 'アジアやラテンアメリカの国の工業化の進め方や、その転換の理由を問われたら、この型です。', how: ['輸入代替型=輸入していた製品を国内でつくり、国内の市場を守る方法と確かめる。', '輸出指向型=外国企業をまねき、安い労働力で輸出向けの製品をつくる方法と確かめる。', '国内市場が小さい国では輸入代替が行きづまり、輸出指向型に転換したと説明する。'], ex: { q: '東南アジアの国々が、輸出加工区を設けて外国企業の工場をまねいたのはなぜか。工業化の型の名前とあわせて答えよ。', a: '輸出指向型工業化。税の優遇などで外国企業をまねき、資本や技術を取り入れて、輸出向けの製品をつくり外貨をかせぐため。', exp: '国内の市場が小さい国では、国内向けの生産だけでは工業が大きく育ちません。外国企業の工場を受け入れれば、雇用が生まれ、技術も学べます。韓国などのNIEsに続いてASEANの国々もこの道を進みました。' } },
      { name: 'EUの統合の利点と課題', freq: 'とてもよく出る', when: 'EUの共通通貨・人の移動・加盟国の格差などが話題になったら、この型です。', how: ['人・モノ・お金・サービスの移動が自由になったこと(単一市場)を確かめる。', '加盟国の間に賃金や所得の格差があることを確かめる。', '格差があると、労働者の移動や工場の移転が起こることを説明する。', '共通通貨ユーロでは、国ごとに金融政策を行えないという課題も考える。'], ex: { q: 'EUの中で、西ヨーロッパの企業が東ヨーロッパに工場を移す動きが見られた。その理由を答えよ。', a: '東ヨーロッパは西ヨーロッパより賃金が安く、EU内では関税がかからずに製品を西ヨーロッパへ運べるから。', exp: '同じ単一市場の中で、賃金の安い地域に工場を移せば、費用をおさえつつ大きな市場で売れます。一方、西ヨーロッパでは働く場所が減るという課題も生まれました。' } },
      { name: '移民がつくった社会の特色', freq: 'よく出る', when: 'アメリカ・カナダ・オーストラリアや中南米の民族構成、言語、多文化社会が話題になったら、この型です。', how: ['先住民がいた土地に、どの国からいつ移民が来たかを整理する。', '奴隷として連れてこられた人々や、労働力として来た人々も確かめる。', 'その歴史が、言語・宗教・民族構成・多文化主義などにどう表れているかを説明する。'], ex: { q: 'オーストラリアが、1970年代に白豪主義をやめて多文化主義をとるようになった背景を答えよ。', a: 'イギリスとの結びつきが弱まり、アジアとの経済的な関係が強まったことや、人種差別への国際的な批判が高まったことから、アジアなどからの移民を受け入れるようになった。', exp: 'オーストラリアは、かつてイギリス系を中心にした白人の国をめざしていました。地理的に近いアジアとの貿易が重要になり、多様な民族がともに暮らす社会へと方針を変えました。' } }
    ],
    more: [
      { lv: 1, q: '東南アジアで、ヨーロッパの国の植民地にならなかった唯一の国はどこか。', a: 'タイ', exp: 'タイは、イギリス領とフランス領の間の緩衝地帯となり、独立を保ちました。仏教(上座部仏教)の信者が多い国です。' },
      { lv: 1, q: '中国の人口の大部分(約9割)をしめる民族を何というか。', a: '漢民族(漢族)', exp: '中国は多民族国家で、漢民族のほかに50以上の少数民族が暮らしています。少数民族の多い地域には自治区が設けられています。' },
      { lv: 1, q: '韓国で使われている、表音文字を何というか。', a: 'ハングル', exp: 'ハングルは15世紀に朝鮮でつくられた文字です。母音と子音を表す記号を組み合わせて、1つの音節を表します。' },
      { lv: 1, q: 'EUの主な機関が置かれている、ベルギーの首都はどこか。', a: 'ブリュッセル', exp: 'ブリュッセルには、EUの行政を担うヨーロッパ委員会などの本部があります。ベルギーはフランス語とオランダ語などを話す人々が暮らす国です。' },
      { lv: 1, q: 'アフリカには、国境線がまっすぐな国が多い。その理由を答えよ。', a: '植民地時代に、ヨーロッパの国々が緯線や経線を使って勝手に境界を引いたから。', exp: 'ヨーロッパの国々は、そこに住む民族の分布を考えずに境界を決めました。そのため、一つの民族が複数の国に分かれたり、対立する民族が同じ国になったりして、独立後の紛争の原因にもなりました。' },
      { lv: 1, q: '東南アジアのフィリピンで、最も信者の多い宗教はどれか。', choices: ['仏教', 'イスラーム', 'キリスト教(カトリック)', 'ヒンドゥー教'], a: 'C(キリスト教(カトリック))', exp: 'フィリピンは長くスペインの植民地だったため、カトリックが広まりました。東南アジアでは、タイなどは仏教、インドネシア・マレーシアはイスラームの信者が多いのとくらべて覚えましょう。' },
      { lv: 1, q: 'インドで、ヒンディー語とともに広く使われ、ICT産業が発達する助けにもなった、旧宗主国の言語は何か。', a: '英語', exp: 'インドはかつてイギリスの植民地だったため、英語が広く使われています。英語を話せる技術者が多いことは、アメリカなどの企業から仕事を受けるうえで大きな強みになりました。' },
      { lv: 2, q: '東南アジアで、島が多く、世界でもイスラームの信者がとても多い国はどこか。', a: 'インドネシア', exp: 'インドネシアは1万をこえる島々からなる国で、イスラームの信者が多数をしめます。ただし、バリ島ではヒンドゥー教の信者が多いなど、地域による違いもあります。' },
      { lv: 2, q: 'アフリカ東部にあり、かつてイギリスの植民地で、英語とスワヒリ語を公用語とする国はどれか。', choices: ['ケニア', 'セネガル', 'アンゴラ', 'コートジボワール'], a: 'A(ケニア)', exp: 'ケニアはイギリスの植民地だったため英語が公用語で、東アフリカで広く使われるスワヒリ語も公用語です。セネガルとコートジボワールは旧フランス領、アンゴラは旧ポルトガル領です。' },
      { lv: 2, q: 'EUの多くの国の間で、国境での出入国の検査をなくし、人が自由に行き来できるようにした取り決めを何というか。', a: 'シェンゲン協定', exp: 'シェンゲン協定に加わる国の間では、パスポートの検査なしで国境をこえられます。通勤や旅行が便利になる一方、不法な移動への対策が課題になることもあります。' },
      { lv: 2, q: '西アジアや北アフリカの多くの国で、広く信仰されている宗教と、広く話されている言語の組み合わせとして正しいものはどれか。', choices: ['仏教・ペルシア語', 'イスラーム・アラビア語', 'キリスト教・ヘブライ語', 'ヒンドゥー教・トルコ語'], a: 'B(イスラーム・アラビア語)', exp: '西アジアや北アフリカでは、イスラームとアラビア語が広がっています。ただし、イランはペルシア語、トルコはトルコ語が話されるなど、すべての国がアラビア語ではない点に注意します。' },
      { lv: 2, q: 'ラテンアメリカで、ヨーロッパ系の白人と先住民の間の混血の人々を何というか。', a: 'メスチソ(メスティーソ)', exp: 'ラテンアメリカでは、先住民、ヨーロッパ系、アフリカ系の人々が混ざり合い、多様な社会がつくられました。白人とアフリカ系の混血はムラートとよばれます。' },
      { lv: 2, q: 'オーストラリアの主な貿易相手が、かつてのイギリスから、日本や中国などのアジアの国々へ変わった理由を答えよ。', a: 'イギリスがヨーロッパの統合(EC)に加わって結びつきが弱まり、一方で地理的に近いアジアの国々が経済成長して、鉄鉱石や石炭などの資源の需要が高まったから。', exp: 'イギリスがECに加盟した1970年代から、オーストラリアはアジア太平洋との関係を強めました。資源を必要とするアジアの工業化が、貿易相手の変化をうながしました。' },
      { lv: 2, q: 'カナダで、フランス系の住民が多く、フランス語が広く話されている州はどれか。', choices: ['オンタリオ州', 'ケベック州', 'ブリティッシュコロンビア州', 'アルバータ州'], a: 'B(ケベック州)', exp: 'ケベック州は、かつてフランスが開拓した地域です。カナダは英語とフランス語の両方を公用語とし、多文化主義を国の方針にしています。' },
      { lv: 2, q: '国の経済が特定の一次産品にかたよると、どのような問題が起こりやすいか。', a: 'その産品の国際価格が下がったり、天候不順で不作になったりすると、国の収入が大きく減り、経済が不安定になる。', exp: '輸出品が一つの作物や鉱産資源にかたよると、その値段の上がり下がりに国全体の経済がふり回されます。輸出品の多様化や工業化が課題になります。' },
      { lv: 3, q: 'ラテンアメリカの国々が、国内の産業を守る輸入代替型の工業化から、輸出指向型へと政策を変えていった理由を説明せよ。', a: '輸入代替型では、国内市場を守るために関税を高くしたが、競争がないため生産の効率が上がらず、国内市場の小ささもあって成長が行きづまったから。', exp: '国内向けの保護された産業は、品質や価格の面で国際競争力がつきにくくなります。外国企業や外国資本を取り入れ、世界市場に向けて輸出する方向へと転換が進みました。' },
      { lv: 3, q: 'ユーロを導入した国では、景気が悪くなっても自国だけで金利を下げるなどの金融政策ができない。その理由と、それによって起こりうる問題を説明せよ。', a: 'ユーロ圏の金融政策は、ヨーロッパ中央銀行がまとめて決めるから。そのため、景気の悪い国と良い国が同じ金利になり、一部の国の不況や失業が長引くことがある。', exp: '共通通貨には、両替の手間がなくなり取引がしやすくなる利点があります。一方で、国ごとの事情に合わせた金融政策や為替の調整ができないという弱点もあります。' },
      { lv: 3, q: 'アメリカ合衆国の南部に、アフリカ系の人々が多く住んでいる歴史的な理由を説明せよ。', a: 'かつて南部では綿花などのプランテーションがさかんで、その労働力としてアフリカから多くの人々が奴隷として連れてこられたから。', exp: '奴隷制度は南北戦争の後に廃止されましたが、その後も人種差別が続き、公民権運動などを通じて権利の改善が進められました。地域の民族構成には、こうした歴史が表れています。' },
      { lv: 3, q: '東南アジアの国々には、中国から移り住んだ人々とその子孫(華人・華僑)が多い。彼らが多く移り住んだ時期と、現在の経済での役割を説明せよ。', a: '主に19世紀から20世紀前半に、鉱山やプランテーションの労働者、商人として移り住んだ。現在は、商業や金融、製造業などで大きな経済的な役割をはたしている。', exp: '華人は、同じ出身地どうしのネットワークを生かして商業で力をつけました。経済力の差が、マレーシアのブミプトラ政策のように、民族間の政策の背景になった国もあります。' },
      { lv: 3, q: 'アフリカの多くの国で、独立後に民族の対立による紛争が起こった理由を、植民地時代の国境線と関連づけて説明せよ。', a: '植民地時代に、民族の分布を無視して国境が引かれたため、独立後の国の中に対立する民族が同じ国に入ったり、一つの民族が国境で分断されたりしたから。', exp: '国の範囲と民族の範囲がずれていると、政治の主導権や資源の分け方をめぐって争いが起こりやすくなります。独立後も国境はそのまま引きつがれたことがポイントです。' }
    ]
  });

  add('gg_disaster', {
    pat: [
      { name: '地形と災害を結びつける', freq: 'とてもよく出る', when: '地形図や地形の名前が示され、起こりやすい災害を問われたら、この型です。', how: ['その土地の地形(扇状地・後背湿地・埋立地・三角州・急な斜面など)を見分ける。', 'できた材料(砂れき・泥)や高さ・水の集まり方を考える。', '急な谷の出口なら土石流、低くて水がたまりやすい所なら浸水、水をふくんだ砂地なら液状化、海ぞいの低地なら高潮・津波と結びつける。'], ex: { q: '海を埋め立ててつくられた、砂を多くふくむ低い土地で、地震のときに特に注意が必要な災害は何か。', a: '液状化', exp: '埋立地は、水をたっぷりふくんだ砂の地盤です。強い揺れで砂の粒どうしのかみ合わせが外れると、地盤が液体のようになり、建物がかたむいたり、マンホールが浮き上がったりします。' } },
      { name: '台風の気圧と高潮の高さを見積もる', freq: 'よく出る', when: '台風の中心気圧とまわりの気圧が示され、海面の上がり方を問われたら、この型です。', how: ['気圧が1hPa下がるごとに、海面はおよそ1cm上がる(吸い上げ効果)ことを使う。', 'まわりの気圧−中心気圧 で気圧の差を出し、cmに直す。', '実際の高潮には、強い風による吹き寄せ効果も加わることを付け加える。'], ex: { q: 'まわりの気圧が1000hPaのとき、中心気圧950hPaの台風が近づいた。吸い上げ効果だけを考えると、海面はおよそ何cm上がるか。', a: '約50cm', exp: '気圧の差は 1000−950=50hPa で、1hPaにつき約1cm上がるので約50cmです。実際には、湾の奥へ海水を押しやる吹き寄せ効果が加わり、もっと高くなることがあります。' } },
      { name: '風向きから台風・火山灰の影響を推理する', freq: '難関大で出る', when: '台風の進む向きや偏西風の向きが示され、被害の大きい地域を問われたら、この型です。', how: ['北半球の台風は反時計回りに風が吹きこむことを確かめる。', '進む方向の右側では、台風の風と台風を動かす風が同じ向きになり、風が強くなると判断する。', '日本の上空では偏西風が西から東へ吹くので、火山灰は火山の東側に多く降ると考える。'], ex: { q: '日本のある火山が噴火し、上空の風は西から東へ吹いていた。火山灰が多く積もると考えられるのは、火山の東側と西側のどちらか。', a: '東側', exp: '日本の上空には偏西風が吹いているので、噴き上げられた火山灰は風に流されて東側に多く降ります。富士山が噴火した場合も、東京など東側に火山灰が降ると想定されています。' } },
      { name: 'ハザードマップの読み方と避難の判断', freq: 'よく出る', when: 'ハザードマップや避難の場面が示され、適切な行動を問われたら、この型です。', how: ['自分のいる場所が、浸水・土砂災害・津波などの想定区域に入っているかを確かめる。', '避難所までの道に、川・低地・がけなどの危険な場所がないかを確かめる。', 'ハザードマップは想定にもとづくもので、それをこえる災害もありうると考え、早めに安全な所へ移る。'], ex: { q: '大雨のとき、近くの避難所に行く道が、浸水想定区域の低い土地を通っている。すでに道路が水につかり始めているとき、どのような行動が適切か。', a: '無理に避難所へ向かわず、自宅の2階以上など、近くのより高く安全な場所に移る(垂直避難)。', exp: '水につかった道は、流れの強さや深さ、ふたの外れた側溝などが見えず危険です。避難所に行くことだけが避難ではありません。状況に応じて、命を守る行動を選ぶことが大切です。' } },
      { name: '環境問題と原因物質・国際的な取り決めを結びつける', freq: 'とてもよく出る', when: '地球温暖化・オゾン層の破壊・酸性雨などの問題と、その原因や対策が問われたら、この型です。', how: ['問題ごとに主な原因物質を思い出す(温暖化=二酸化炭素など、オゾン層=フロン、酸性雨=硫黄酸化物・窒素酸化物)。', 'その物質がどこから出るかを考える(化石燃料、冷蔵庫・スプレーなど)。', '対策となる取り決めを結びつける(京都議定書・パリ協定、モントリオール議定書など)。'], ex: { q: '2015年に採択され、先進国だけでなく発展途上国もふくむすべての参加国が、温室効果ガスの削減目標を自ら決めて取り組むことになった取り決めを何というか。', a: 'パリ協定', exp: '京都議定書では、削減の義務は先進国だけに課されていました。パリ協定では、すべての参加国が自分で目標を決めて取り組むしくみになりました。両者のちがいがよく問われます。' } }
    ],
    more: [
      { lv: 1, q: '地震が発生した地下の場所(震源)の真上にあたる地表の地点を何というか。', a: '震央', exp: '地下で岩盤がずれた場所が震源、その真上の地表の点が震央です。ニュースの地図に×印で示されるのは、ふつう震央です。' },
      { lv: 1, q: '地震そのものの規模(エネルギーの大きさ)を表す尺度はどれか。', choices: ['震度', 'マグニチュード', '気圧', '降水量'], a: 'B(マグニチュード)', exp: 'マグニチュードは地震の規模を表し、1つの地震に1つの値です。震度は、それぞれの場所での揺れの強さを表すので、場所によってちがいます。' },
      { lv: 1, q: '海底で地震が起こり、海底が急に持ち上がったり沈んだりして、海水が大きな波となって伝わる現象を何というか。', a: '津波', exp: '津波は、海の深い所ではとても速く伝わり、海岸に近づくと高くなります。何回もくり返しおし寄せ、1回目より後の波が高いこともあります。' },
      { lv: 1, q: '地球温暖化の主な原因とされる温室効果ガスのうち、化石燃料を燃やすと多く出るものは何か。', a: '二酸化炭素', exp: '石油・石炭・天然ガスを燃やすと二酸化炭素が出ます。温室効果ガスには、ほかにメタンやフロン類などもあります。' },
      { lv: 1, q: 'かつて冷蔵庫やスプレーに使われ、オゾン層を破壊した物質は何か。', a: 'フロン', exp: 'フロンが成層圏でオゾン層をこわすと、有害な紫外線が地表に多く届くようになります。そのため、国際的な取り決めで生産や消費が規制されました。' },
      { lv: 1, q: '火山がもたらす「恵み」として、適切でないものはどれか。', choices: ['温泉', '地熱発電', '美しい景観と観光', '液状化'], a: 'D(液状化)', exp: '液状化は地震のときに砂の地盤で起こる災害で、火山の恵みではありません。火山は、温泉や地熱、観光資源、水はけのよい土地などの恵みももたらします。' },
      { lv: 1, q: '災害のとき、自分や家族の命を自分たちで守ることを何というか。', choices: ['自助', '共助', '公助', '互助'], a: 'A(自助)', exp: '防災では、自分で守る「自助」、地域で助け合う「共助」、国や自治体が支える「公助」の3つが大切だといわれます。大きな災害ほど、公助がすぐには届かないことがあります。' },
      { lv: 2, q: 'まわりの気圧が1005hPaのとき、中心気圧955hPaの台風が近づいた。吸い上げ効果だけを考えると、海面はおよそ何cm上がるか。', a: '約50cm', exp: '気圧の差は 1005−955=50hPa で、1hPaあたり約1cmなので約50cm上がります。強風による吹き寄せも加わると、高潮はさらに高くなります。' },
      { lv: 2, q: '地震のときに液状化が最も起こりやすい土地はどれか。', choices: ['かたい岩盤の山地', '海を埋め立てた砂の多い土地', '台地の上の関東ローム層', '古い火山の溶岩台地'], a: 'B(海を埋め立てた砂の多い土地)', exp: '液状化は、地下水位が高く、ゆるく積もった砂の地盤で起こりやすい現象です。埋立地や、昔の川・沼を埋めた土地などは特に注意が必要です。' },
      { lv: 2, q: '北半球で、北に向かって進む台風の右側(東側)で風が強くなる理由を答えよ。', a: '台風に反時計回りに吹きこむ風と、台風を北へ動かす風の向きが、右側では同じになって重なるから。', exp: '進む方向の右側は「危険半円」とよばれます。左側では2つの風の向きが逆になって打ち消し合うので、右側に比べて風が弱くなります。' },
      { lv: 2, q: '近所の人どうしで声をかけ合って避難したり、救助活動をしたりすることを何というか。', a: '共助', exp: '大きな災害のときは、消防や警察だけでは手が足りません。自主防災組織など、地域の人どうしの助け合いが多くの命を救います。' },
      { lv: 2, q: '高潮の被害が大きくなりやすい湾の地形の条件を答えよ。', a: '台風の風が吹きこむ方向(南など)に湾の口が開いていて、湾の奥が遠浅で低い土地が広がっている所。', exp: '強い風で湾の奥へ海水が押し寄せると、逃げ場のない湾の奥で海面が高くなります。伊勢湾や大阪湾などが、高潮の被害を受けてきた例です。' },
      { lv: 2, q: '地球温暖化が進むと、海面の上昇によって国土が失われるおそれが特に大きいのは、どのような国か。', a: 'ツバルなど、太平洋のサンゴ礁の島々からなる、標高の低い島国', exp: 'サンゴ礁の島は海抜数mほどの所が多く、海面がわずかに上がるだけでも、高潮や浸水の被害を受けやすくなります。井戸水に海水がまじる問題も起こっています。' },
      { lv: 2, q: '大雨のとき、川からあふれた水を一時的にためて、下流の洪水を防ぐためにつくられる土地を何というか。', a: '遊水地(遊水池)', exp: '遊水地は、ふだんは公園や田畑などとして使われ、大雨のときに水をためます。堤防を高くするだけでなく、水を「逃がす場所」をつくる考え方です。' },
      { lv: 2, q: 'マグニチュードが2大きくなると、地震のエネルギーはおよそ何倍になるか。', a: '約1000倍', exp: 'マグニチュードが1大きくなると、エネルギーは約32倍になります。2大きくなると 32×32≒1000倍です。わずかな数字の差が、大きなちがいを表します。' },
      { lv: 3, q: '海溝型の地震と、内陸の活断層で起こる直下型の地震のちがいを、揺れの特徴と起こりうる災害から説明せよ。', a: '海溝型地震は規模が大きくなりやすく、広い範囲が長く揺れ、津波が起こりやすい。直下型地震は震源が浅く、規模が比較的小さくても真上の地域が激しく揺れ、建物の倒壊などの被害が集中しやすい。', exp: '東日本大震災は海溝型、阪神・淡路大震災は直下型の例です。地震の種類によって、備えるべき災害(津波か建物の倒壊か)がちがうことを理解しておきましょう。' },
      { lv: 3, q: '酸性雨は、原因物質を出した国だけでなく、別の国にも被害をもたらす。その理由を説明せよ。', a: '工場や自動車から出た硫黄酸化物や窒素酸化物が、偏西風などの風に運ばれて遠くまで移動し、ほかの国で雨にとけて降るから。', exp: 'このような被害を越境汚染といいます。ヨーロッパでは工業地域から運ばれた物質で北ヨーロッパの森林や湖が被害を受け、国際的な取り組みが進められました。' },
      { lv: 3, q: '熱帯林の破壊が地球温暖化を進めるといわれる理由を、2つの面から説明せよ。', a: '森林が減ると、光合成で吸収される二酸化炭素の量が減る。また、森林を焼いたり分解されたりすると、木にたくわえられていた炭素が二酸化炭素として大気中に出ていく。', exp: '森林は二酸化炭素の「吸収源」であり、炭素の「貯蔵庫」でもあります。焼畑や農地・牧場への転換による熱帯林の減少は、気候変動と生物多様性の両方に影響します。' },
      { lv: 3, q: 'リアス海岸の湾の奥では、津波が特に高くなりやすい。その理由を説明せよ。', a: '湾の入口が広く奥に行くほどせまく浅くなるので、おし寄せた津波のエネルギーがせまい所に集まり、波が高くなるから。', exp: 'V字形の湾では、海水が逃げ場を失って奥に集中します。三陸海岸では、過去の津波でも湾の奥で特に高い波が記録されてきました。良港の多い地形が、津波には弱いという面をもちます。' },
      { lv: 3, q: '海抜ゼロメートル地帯で、高潮や洪水によって浸水すると、水が長い期間引かないことがある。その理由と、ふだんから必要な対策を説明せよ。', a: '土地が海面より低いため、たまった水が自然には海や川へ流れ出ないから。ふだんから堤防を守り、ポンプで水をくみ出す排水機場などを整えておく必要がある。', exp: 'ゼロメートル地帯は、地下水のくみ上げによる地盤沈下などで生まれた所もあります。水が自然に引かないので、浸水すると生活への影響が長引きます。広い範囲で早めに避難する計画も大切です。' }
    ]
  });

  add('ri_seinen', {
    pat: [
      { name: '具体的な場面から防衛機制を判定する', freq: 'とてもよく出る', when: '人物のふるまいが短い場面として書かれ、「どの防衛機制にあたるか」を問われたら、この型です。', how: ['その人の「満たされない欲求」や「認めたくない気持ち」が何かを見つける。', 'それをどう処理しているかを見る(言いわけ→合理化、反対の態度→反動形成、他人のせいにする→投射、別の相手に向ける→置き換え、社会的に価値ある活動へ→昇華、幼い行動へ→退行など)。', '似たもの(置き換えと昇華、合理化と投射)は、向かう先や内容のちがいで区別する。'], ex: { q: '部活動でレギュラーになれなかった生徒が、その悔しさを美術の作品づくりにぶつけ、コンクールで入賞した。この心のはたらきは何か。', a: '昇華', exp: '満たされない気持ちを、社会的に認められる価値の高い活動に向けかえるはたらきを昇華といいます。単に別の相手にあたる「置き換え」とは、向かう先が社会的に価値のある活動かどうかでちがいます。' } },
      { name: 'レヴィンの葛藤の3つの型', freq: 'よく出る', when: '「〜したいが〜もしたい」「〜はいやだが〜もいやだ」のように、2つの気持ちの間で迷う場面が書かれていたら、この型です。', how: ['それぞれの選択肢が「近づきたいもの(+)」か「避けたいもの(−)」かを判断する。', '+と+なら接近−接近、−と−なら回避−回避と決める。', '1つのものに+と−の両方があるなら接近−回避と決める。'], ex: { q: '「新しいゲームを買いたいが、おこづかいが全部なくなるのはいやだ」という状態は、葛藤のどの型か。', a: '接近−回避型', exp: '「ゲームを買う」という1つの行動に、手に入れたい(+)と、お金がなくなる(−)の両方がふくまれています。そのため、近づきたいが避けたいという接近−回避型になります。' } },
      { name: 'マズローの欲求階層に場面をあてはめる', freq: 'よく出る', when: '人の行動の動機が書かれ、マズローの欲求のどれにあたるかを問われたら、この型です。', how: ['下から、生理的欲求→安全の欲求→所属と愛の欲求→承認(自尊)の欲求→自己実現の欲求の順に並べる。', '場面の動機が「体」「安全」「仲間」「評価」「自分の可能性」のどれに向いているかを見る。', '下の4つは欠乏欲求、自己実現は成長欲求として区別する。'], ex: { q: '転校してきた生徒が、クラスの仲間に受け入れられたいと思い、部活動に入った。この動機はマズローのどの欲求にあたるか。', a: '所属と愛の欲求(社会的欲求)', exp: '集団の一員として受け入れられたい、仲間とつながりたいという欲求は、所属と愛の欲求です。人から認められ尊敬されたいという承認の欲求とは、「仲間に入る」か「評価される」かでちがいます。' } },
      { name: 'マーシャのアイデンティティ・ステイタスを判定する', freq: '難関大で出る', when: '進路や生き方について、「迷った経験(危機)があるか」「何かに打ちこんでいるか(傾倒)」が書かれていたら、この型です。', how: ['危機(真剣に迷った経験)があるかを見る。', '傾倒(自分で選んだものに積極的にかかわっているか)があるかを見る。', '危機あり・傾倒あり=達成、危機の最中=モラトリアム、危機なし・傾倒あり=早期完了、傾倒なし=拡散と決める。'], ex: { q: 'いろいろな進路を真剣に調べて悩んだすえ、自分で看護師になると決め、そのための勉強に打ちこんでいる生徒は、どのステイタスにあたるか。', a: 'アイデンティティ達成', exp: '真剣に迷った経験(危機)があり、そのうえで自分で選んだ道に打ちこんでいる(傾倒)ので、アイデンティティ達成です。親に言われるまま迷わず決めた場合は、早期完了になります。' } },
      { name: '青年期を表すことばと人物を結びつける', freq: 'よく出る', when: '「第二の誕生」「マージナルマン」「心理社会的モラトリアム」などのことばと人物の組み合わせを問われたら、この型です。', how: ['ことばの意味から、青年期のどの面をとらえたものかを考える(心の誕生・どっちつかずの立場・猶予の期間など)。', '人物と結びつける(第二の誕生=ルソー、マージナルマン=レヴィン、心理社会的モラトリアム=エリクソン)。', '似たことば(モラトリアムとモラトリアム人間など)の人物のちがいにも注意する。'], ex: { q: '青年を、子どもの集団にも大人の集団にも属しきれない「マージナルマン(境界人)」とよんだ心理学者はだれか。', a: 'レヴィン', exp: '青年は、子どもでもなく大人でもない、2つの集団の境目にいる存在だとレヴィンは考えました。そのため、心が不安定になりやすいと説明しました。「第二の誕生」のルソーとまちがえないようにしましょう。' } }
    ],
    more: [
      { lv: 1, q: '著書『エミール』で、青年期を「第二の誕生」とよんだ思想家はだれか。', a: 'ルソー', exp: 'ルソーは「われわれは2回この世に生まれる。1回目は存在するために、2回目は生きるために」と述べました。2回目の誕生が、自我にめざめる青年期です。' },
      { lv: 1, q: '青年期に自我が強くなり、親や大人の権威に反発するようになる時期を何というか。', a: '第二反抗期', exp: '2〜4歳ごろの第一反抗期に対して、青年期の反抗を第二反抗期といいます。自分で考え、自分で決めたいという気持ちが強くなることの表れです。' },
      { lv: 1, q: '欲求が何らかの理由で満たされず、心が緊張して不快な状態を何というか。', a: '欲求不満(フラストレーション)', exp: '欲求不満になると、人はそれを解消しようとします。原因を見つけて合理的に解決するほか、衝動的な行動や防衛機制などの方法をとることもあります。' },
      { lv: 1, q: '防衛機制のうち、満たされない欲求を、芸術やスポーツなど社会的に価値の高い活動に向けかえるはたらきを何というか。', a: '昇華', exp: '昇華は、防衛機制の中でも社会に受け入れられやすい、前向きなはたらきとされます。フロイトは、芸術や文化の発展にも昇華が関わると考えました。' },
      { lv: 1, q: 'エリクソンが、青年期を、大人としての社会的な責任や義務を一時的に猶予された期間として何とよんだか。', a: '心理社会的モラトリアム', exp: 'モラトリアムは、もともと「支払いの猶予」を意味する経済のことばです。エリクソンは、この猶予期間に試行錯誤しながらアイデンティティを確立すると考えました。' },
      { lv: 1, q: 'マズローの欲求階層説で、集団に属し、仲間に受け入れられたいという欲求はどれか。', choices: ['安全の欲求', '所属と愛の欲求', '承認(自尊)の欲求', '自己実現の欲求'], a: 'B(所属と愛の欲求)', exp: '所属と愛の欲求は、生理的欲求・安全の欲求の次に来る段階です。その上に、他人から認められたいという承認の欲求があります。' },
      { lv: 1, q: '「自分は自分であり、ほかのだれでもない」という確かな感覚を、エリクソンは何とよんだか。', a: 'アイデンティティ(自我同一性)', exp: 'アイデンティティは、過去から今まで自分が一貫しているという感覚と、社会の中で自分の役割が認められているという感覚の両方をふくみます。' },
      { lv: 2, q: '弟が生まれた5歳の子が、急に赤ちゃんのような話し方をして、親にあまえるようになった。この防衛機制は何か。', a: '退行', exp: '退行は、今の状況にたえられず、より幼い発達の段階のふるまいに戻ることです。親の関心を取り戻したいという気持ちの表れと考えられます。' },
      { lv: 2, q: 'あこがれのスポーツ選手と同じ髪型や持ち物をそろえて、自分もえらくなったような気持ちになった。この防衛機制は何か。', a: '同一視(同一化)', exp: '同一視は、自分にない優れた性質をもつ他人と自分を重ね合わせて、満足を得るはたらきです。ファンの心理や、子どもが親のまねをすることにも見られます。' },
      { lv: 2, q: '「見たい映画が2つあるが、上映時間が重なっていてどちらか1つしか見られない」という状態は、レヴィンの葛藤のどの型か。', a: '接近−接近型', exp: 'どちらも近づきたいもの(+)で、片方を選ぶともう片方をあきらめなければならない状態です。比較的解決しやすい葛藤とされます。' },
      { lv: 2, q: '自分が相手のことをきらっているのに、「あの人が自分をきらっている」と思いこむ防衛機制は何か。', a: '投射(投影)', exp: '投射は、自分の中にある認めたくない感情を、他人がもっているものとして相手に移すはたらきです。自分の気持ちと向き合うことを避ける心の動きです。' },
      { lv: 2, q: '将来のことを考えようとせず、何をしたいのかもわからないまま、無気力に毎日を過ごしている状態は、マーシャのアイデンティティ・ステイタスのどれにあたるか。', a: 'アイデンティティ拡散', exp: '拡散は、自分が何者で何をしたいのかがまとまらず、打ちこむものもない状態です。真剣に迷っている最中の「モラトリアム」とは、迷いに向き合っているかどうかでちがいます。' },
      { lv: 2, q: 'シュプランガーの価値類型で、美しいものや調和に最も価値を置く型を何というか。', choices: ['理論型', '経済型', '審美型', '宗教型'], a: 'C(審美型)', exp: 'シュプランガーは、何に価値を置くかで人を6つの型に分けました。理論型・経済型・審美型・社会型・権力型(政治型)・宗教型です。' },
      { lv: 2, q: '他人から能力を認められたい、尊敬されたいという欲求は、マズローの欲求階層説のどれにあたるか。', a: '承認(自尊)の欲求', exp: '承認の欲求は、欠乏欲求の中で最も高い段階です。これが満たされると、自分の可能性を実現しようとする自己実現の欲求があらわれるとされます。' },
      { lv: 2, q: '青年期を「疾風怒濤の時代」とよび、青年心理学の基礎を築いたアメリカの心理学者はだれか。', a: 'ホール', exp: 'ホールは、青年期を激しい感情の動きや不安定さにゆれる時期ととらえ、ドイツの文学運動の名前を借りて「疾風怒濤」と表しました。' },
      { lv: 3, q: '上司にしかられた人が、帰宅後に家族に強くあたった。この防衛機制は何か。また、昇華とのちがいを説明せよ。', a: '置き換え(八つ当たり)。置き換えは、欲求や感情を別の相手に向けかえるだけだが、昇華は、それを社会的に価値の高い活動に向けかえる点がちがう。', exp: 'どちらも「向ける先を変える」点は同じです。向かう先が身近な弱い相手なのか、芸術やスポーツなどの価値ある活動なのかで区別します。' },
      { lv: 3, q: '試験に失敗した生徒が、答案を見直して苦手な分野を見つけ、勉強の方法を変えた。この対処は、欲求不満への対処のうち何とよばれるか。', choices: ['合理的解決', '近道反応', '防衛機制', '退行'], a: 'A(合理的解決)', exp: '原因を筋道立てて考え、現実的な方法で問題を解決しようとするのが合理的解決です。感情にまかせて八つ当たりなどをするのは近道反応、無意識に心を守るのが防衛機制です。' },
      { lv: 3, q: '「部活動をやめて勉強に集中したいが、仲間と離れるのはさびしい」という生徒の葛藤の型を答え、そう判断した理由を説明せよ。', a: '接近−回避型。「部活動をやめる」という1つの選択に、勉強に集中できるという魅力と、仲間と離れるという避けたい面の両方があるから。', exp: '2つの選択肢の比較に見えても、1つの行動に+と−がふくまれていれば接近−回避型です。この型は、決めかねて行ったり来たりしやすく、解決が難しいとされます。' },
      { lv: 3, q: 'エリクソンのライフサイクル論で、乳児期の発達課題として示された心理社会的危機はどれか。', choices: ['自律性 対 恥・疑惑', '基本的信頼 対 不信', '勤勉性 対 劣等感', '親密性 対 孤立'], a: 'B(基本的信頼 対 不信)', exp: '乳児期は、養育者に世話をしてもらう中で、世界や人を信頼できるかどうかが課題になります。自律性は幼児期前期、勤勉性は児童期、親密性は成人期初期の課題です。' },
      { lv: 3, q: '現代の社会では、青年期が以前より長くなっているといわれる。その理由を説明せよ。', a: '高学歴化が進んで学校に通う期間がのび、就職や結婚などで大人としての役割を引き受ける時期がおそくなっている。一方で、体の成熟は早まり、青年期の始まりが早くなっているから。', exp: '青年期の始まり(思春期)が早まり、終わり(社会的な自立)がおそくなると、青年期は長くなります。社会の変化が、人生の区切り方にも影響している例です。' }
    ]
  });

  add('ri_greek', {
    pat: [
      { name: '自然哲学者をアルケー(万物の根源)で見分ける', freq: 'よく出る', when: '「万物の根源は〜」「世界は〜からできている」という主張が示され、人物を問われたら、この型です。', how: ['根源とされたもの(水・火・数・原子・四元素など)を見つける。', '人物と結びつける(水=タレス、火・万物流転=ヘラクレイトス、数=ピタゴラス、原子=デモクリトス、四元素=エンペドクレス)。', '「変化を認めるか(ヘラクレイトス)」「変化を否定するか(パルメニデス)」の対立にも注意する。'], ex: { q: '「世界は、それ以上分けられない無数の小さな粒と、粒が動きまわる空虚からできている」と考えた哲学者はだれか。', a: 'デモクリトス', exp: 'それ以上分けられない粒をアトム(原子)とよび、その結びつき方が変わることで、ものの変化を説明しました。粒そのものは変化しないので、「変化」と「不変」を両立させた考えともいえます。' } },
      { name: 'ソクラテスとソフィストを区別する', freq: 'とてもよく出る', when: '真理や善について「人それぞれ」と考える立場と、「だれにも共通の真理がある」と考える立場が対比されていたら、この型です。', how: ['相対主義(「人間は万物の尺度」=プロタゴラス)か、普遍的な真理を求める立場かを見分ける。', 'ソフィストは弁論術を教え、議論に勝つことを重んじたと確かめる。', 'ソクラテスは問答法で、本当に知っているかを問い直し、よく生きるための徳を求めたと結びつける。'], ex: { q: '「同じ風が、ある人には寒く、ある人には寒くない。だから、ものごとの正しさは人それぞれである」という考えに最も近い人物はだれか。', a: 'プロタゴラス', exp: 'プロタゴラスは「人間は万物の尺度である」と述べ、真理は人によって異なるという相対主義を説きました。ソクラテスはこれに対し、だれにとってもよいもの(善)を問答によって探ろうとしました。' } },
      { name: 'プラトンとアリストテレスを比べる', freq: 'とてもよく出る', when: '「本質は現実の外にあるか、中にあるか」や、理想国家・幸福についての考えを比べる問題は、この型です。', how: ['プラトンは、真の実在(イデア)を感覚の世界の外に置き、理性で求めたと確かめる。', 'アリストテレスは、本質(形相)を個々のものの中に見て、現実を観察したと確かめる。', '政治でも、プラトン=哲人政治(理想)、アリストテレス=中庸を重んじた現実的な国家論、と対比する。'], ex: { q: '「馬の本質は、一頭一頭の馬の中に、その材料と結びついて存在する」という考えに近いのは、プラトンとアリストテレスのどちらか。', a: 'アリストテレス', exp: 'アリストテレスは、ものは質料(材料)と形相(本質・かたち)からなり、形相は個々のものの中にあると考えました。プラトンは、本質であるイデアを、現実の外のイデア界にあるものとしました。' } },
      { name: 'アリストテレスの徳と中庸', freq: 'よく出る', when: '「〜と〜の中間」「習慣によって身につく」などの説明から、アリストテレスの徳を問う問題は、この型です。', how: ['徳を知性的徳(教育で身につく)と、倫理的徳(習慣で身につく)に分ける。', '倫理的徳は、過不足の両極端をさけた中庸にあると確かめる。', '具体的な徳を、両極端の悪徳とセットで考える(勇気=無謀と臆病の中間など)。'], ex: { q: 'アリストテレスの考えでは、正しい行いをくり返すうちに身につく勇気や節制などの徳を何というか。', a: '倫理的徳(習性的徳)', exp: 'アリストテレスは、勇気や節制などは、知っているだけでなく、行いをくり返して習慣にすることで身につくと考えました。知恵や思慮のように教育で身につく知性的徳と区別されます。' } },
      { name: 'ストア派とエピクロス派を区別する', freq: 'とてもよく出る', when: 'ヘレニズム時代の思想で、「理性に従う」「心の平静」「快楽」などのことばが出たら、この型です。', how: ['ストア派=理性(ロゴス)に従い、情念に動かされないアパテイアをめざすと確かめる。', 'エピクロス派=心の平静であるアタラクシアを快楽とし、それをめざすと確かめる。', '「自然に従って生きよ」はストア派、「隠れて生きよ」はエピクロス派と結びつける。'], ex: { q: '「怒りや恐れなどの情念に動かされず、宇宙をつらぬく理性に従って生きることが大切だ」という考えは、どの学派のものか。', a: 'ストア派', exp: 'ストア派は、情念から解放された心の状態(アパテイア)を理想としました。禁欲的な生き方を重んじたので、英語のストイック(禁欲的な)の語源になりました。' } }
    ],
    more: [
      { lv: 1, q: '「人間は万物の尺度である」と述べたソフィストはだれか。', a: 'プロタゴラス', exp: 'プロタゴラスは、真理や善悪の基準は人によって異なると考えました。この立場を相対主義といいます。' },
      { lv: 1, q: 'ソクラテスが大切にした「汝自身を知れ」ということばは、どこの神殿にかかげられていたものか。', a: 'デルフォイのアポロン神殿', exp: 'ソクラテスの友人がこの神殿で「ソクラテスより知恵のある者はいない」という神託を受けました。ソクラテスはその意味を探るため、多くの人と問答を重ねました。' },
      { lv: 1, q: 'プラトンが、理想の国家や正義について論じた対話篇の名前を答えよ。', a: '『国家』', exp: '『国家』では、魂の三分説と国家の三階級を対応させ、哲学者が統治する哲人政治が理想とされています。洞窟の比喩もこの作品に出てきます。' },
      { lv: 1, q: 'アリストテレスが、アテネに開いた学園を何というか。', a: 'リュケイオン', exp: 'プラトンの学園がアカデメイア、アリストテレスの学園がリュケイオンです。アリストテレスは歩きながら講義したといわれ、その学派は逍遥学派ともよばれます。' },
      { lv: 1, q: 'ヘレニズム時代に、ストア派を開いた哲学者はだれか。', a: 'ゼノン(キプロスのゼノン)', exp: 'ゼノンはアテネの柱廊(ストア)で教えたので、その学派はストア派とよばれました。エレア派のゼノンとは別の人物なので注意しましょう。' },
      { lv: 1, q: 'エピクロスが理想とした、心が乱されず平静な状態を何というか。', a: 'アタラクシア', exp: 'エピクロスは、心が不安や恐れから解放された状態を本当の快楽と考えました。ストア派のアパテイア(情念のない状態)と区別して覚えましょう。' },
      { lv: 1, q: 'ソクラテスが、人が生きるうえで最も気をつかうべきだとしたことは何か。', choices: ['財産を増やすこと', '名誉を得ること', '魂をできるだけよいものにすること', '体をきたえること'], a: 'C(魂をできるだけよいものにすること)', exp: 'ソクラテスは、お金や評判よりも、魂(プシュケー)をよくすること(魂への配慮)が大切だと説きました。それが「よく生きる」ことにつながると考えたのです。' },
      { lv: 2, q: 'プラトンが説いた四元徳にふくまれないものはどれか。', choices: ['知恵', '勇気', '節制', '信仰'], a: 'D(信仰)', exp: 'プラトンの四元徳は、知恵・勇気・節制・正義です。信仰は、のちにキリスト教で重んじられた三元徳(信仰・希望・愛)の一つです。' },
      { lv: 2, q: 'プラトンの魂の三分説で、魂の3つの部分と、国家の3つの階級の正しい対応を答えよ。', a: '理性=統治者、気概=防衛者(軍人)、欲望=生産者', exp: 'それぞれの部分が知恵・勇気・節制の徳をそなえ、理性が全体を導くとき、魂にも国家にも正義が実現するとプラトンは考えました。' },
      { lv: 2, q: 'アリストテレスによれば、勇気や節制などの倫理的徳は、主に何によって身につくか。', a: '習慣(よい行いのくり返し)', exp: 'アリストテレスは「人は正しい行いをすることで正しい人になる」と考えました。徳は生まれつきでも知識だけでもなく、行いの積み重ねで身につくものです。' },
      { lv: 2, q: 'ストア派が理想とした、情念に動かされない心の状態を何というか。', a: 'アパテイア', exp: 'アパテイアは「パトス(情念)がない」という意味です。ストア派は、理性に従って生きることで、この状態に達すると考えました。' },
      { lv: 2, q: '死刑の判決を受けたソクラテスが、友人から脱獄をすすめられても応じなかったのは、どのような考えによるか。', a: 'ただ生きることではなく、よく生きることが大切であり、不正に不正で返すような脱獄は、よく生きることに反すると考えたから。', exp: 'ソクラテスは、国の法に従うことを自分の生き方として貫きました。命を守ることより、魂をよい状態に保つことを重んじたのです。' },
      { lv: 2, q: '損害を与えた人に賠償させるなど、人々の間の利害の不均衡を正して等しくするアリストテレスの正義を何というか。', a: '調整的正義', exp: 'アリストテレスは、正義を全体的正義と部分的正義に分け、部分的正義をさらに、功績に応じて分ける配分的正義と、損得を等しくする調整的正義に分けました。' },
      { lv: 2, q: 'ソフィストとよばれた人々は、主に何を教えて報酬を得ていたか。', a: '弁論術(人を説得し、議論に勝つための話し方)', exp: '民主政のアテネでは、民会や裁判で人々を説得する力が求められました。ソフィストはその技術を教えましたが、真理より議論に勝つことを重んじると批判されることもありました。' },
      { lv: 2, q: '万物の根源を「水」としたタレスの考えは、それまでの神話による説明と比べて、どのような点で新しかったか。', a: '世界の成り立ちを神々の物語ではなく、自然そのものの中にある根源から、理性によって説明しようとした点。', exp: 'タレスに始まる自然哲学者たちは、神話(ミュトス)ではなく、筋道立てた考え(ロゴス)で自然を説明しようとしました。ここに哲学の始まりがあるとされます。' },
      { lv: 3, q: 'ソクラテスの「福徳一致」とはどのような考えか。「知徳合一」との関係にふれて説明せよ。', a: '徳とは何かを本当に知れば、人は徳のある行いをする(知徳合一)。そして徳のある生き方をすることが、そのまま幸福につながるという考え。', exp: 'ソクラテスは、悪い行いは無知から生まれると考えました。正しく知ることが正しく行うことにつながり、それが魂をよくし、本当の幸福をもたらすと考えたのです。' },
      { lv: 3, q: 'アリストテレスの中庸の考えで、「気前のよさ」は何と何の中間にあたる徳とされるか。', a: '浪費(使いすぎ)とけち(使わなさすぎ)の中間', exp: 'お金を使いすぎるのも、出し惜しみするのも、どちらも悪徳です。その場にふさわしい使い方ができることが気前のよさという徳です。中庸は、単なる「まん中」ではなく、状況に応じた適切さです。' },
      { lv: 3, q: 'エピクロスは快楽を善としたが、それはぜいたくや欲望のままに生きることをすすめたものではない。その理由を説明せよ。', a: 'エピクロスのいう快楽とは、体の苦痛がなく、心が乱されないアタラクシアの状態のことであり、ぜいたくや過度の欲望はかえって心をかき乱すと考えたから。', exp: 'エピクロスは、質素な食事と友人との交わりを大切にし、政治の争いなどから離れて静かに暮らすことをすすめました。「快楽主義」という名前から誤解しやすいところです。' },
      { lv: 3, q: 'ストア派の「世界市民主義(コスモポリタニズム)」は、ポリスを重んじたアリストテレスの考えとどのようにちがうか。時代の背景にもふれて説明せよ。', a: 'アリストテレスは人間をポリスの中で生きる存在ととらえた。ストア派は、ポリスが力を失い広い帝国が生まれたヘレニズム時代に、すべての人間が理性を分けもつ同じ世界の市民だと考えた。', exp: 'アレクサンドロスの東方遠征のあと、人々の生活の場はポリスをこえて広がりました。所属する共同体が大きく変わったことが、思想の変化の背景にあります。' },
      { lv: 3, q: 'ソクラテスとソフィストのちがいとして、最も適当なものはどれか。', choices: ['ソクラテスは議論に勝つことを重んじ、ソフィストは真理を求めた', 'ソクラテスはだれにも共通する善を問い、ソフィストは真理は人それぞれだと考える傾向があった', 'ソクラテスは自然の根源を探り、ソフィストは人間の生き方を探った', 'ソクラテスは報酬を得て弁論術を教え、ソフィストは無償で問答を行った'], a: 'B(ソクラテスはだれにも共通する善を問い、ソフィストは真理は人それぞれだと考える傾向があった)', exp: 'ソクラテスもソフィストも人間や社会に関心を向けましたが、ソクラテスは普遍的な善を求めました。報酬を得て弁論術を教えたのはソフィストの方です。' }
    ]
  });

  add('ri_religion', {
    pat: [
      { name: '礼拝・聖典・聖地から宗教を判定する', freq: 'とてもよく出る', when: '礼拝の曜日、聖典の名前、聖地、食べ物の決まりなどが示され、どの宗教かを問われたら、この型です。', how: ['聖典を確かめる(ユダヤ教=聖書〔キリスト教でいう旧約聖書〕、キリスト教=旧約・新約聖書、イスラーム=クルアーン)。', '礼拝の日を確かめる(ユダヤ教=安息日の土曜日〔金曜日の日没から〕、キリスト教=日曜日、イスラーム=金曜日の集団礼拝)。', '偶像や食べ物の決まり(イスラームは偶像崇拝を禁じ、豚肉を食べないなど)で一つにしぼる。'], ex: { q: '金曜日に集団で礼拝を行い、聖地の方角に向かって1日5回祈り、偶像をつくることを禁じている宗教はどれか。', a: 'イスラーム', exp: 'イスラームでは、1日5回メッカの方角に向かって礼拝し、金曜日の昼には集団礼拝が行われます。神は唯一で形をもたないので、偶像崇拝はきびしく禁じられています。' } },
      { name: '「救い」の考え方で宗教を比べる', freq: 'よく出る', when: '人がどうすれば救われるか(神の愛・律法・信仰・悟り)が書かれ、どの宗教の考えかを問われたら、この型です。', how: ['ユダヤ教=神との契約を守り律法に従うことで救われる、と確かめる。', 'キリスト教=神の無差別・無償の愛(アガペー)を信じ、信仰によって救われる、と確かめる。', 'イスラーム=唯一神アッラーへの絶対的な帰依(六信五行)、仏教=煩悩を断って悟りに至る、と確かめる。'], ex: { q: '「神の愛は、正しい人にも罪人にも、見返りを求めずに注がれる」という考えは、どの宗教のどの愛を表しているか。', a: 'キリスト教のアガペー', exp: 'アガペーは、相手の価値や見返りに関係なく与えられる神の愛です。イエスはこの愛にならい、隣人や敵をも愛することを説きました。ギリシア哲学のエロース(価値あるものを求める愛)とは方向が逆です。' } },
      { name: '四諦・八正道を具体的な悩みにあてはめる', freq: 'よく出る', when: '悩みや苦しみの場面が書かれ、仏教の教えでどう整理できるかを問われたら、この型です。', how: ['苦諦=人生は思いどおりにならない苦しみであるという真理、と確かめる。', '集諦=苦しみの原因は煩悩(渇愛)にあるという真理、と確かめる。', '滅諦=煩悩をなくせば苦しみがなくなるという真理、道諦=そのための八正道、と順に当てはめる。'], ex: { q: '「もっと人に認められたい」という気持ちが強すぎて苦しんでいる人がいる。この苦しみの原因を自分の執着に見いだすことは、四諦のどれにあたるか。', a: '集諦', exp: '集諦は、苦しみがどこから生まれるかを明らかにする真理です。仏教では、苦しみの原因は、ものごとに執着する心(煩悩・渇愛)にあると考えます。原因がわかれば、それをなくす道(滅諦・道諦)へ進めます。' } },
      { name: 'キリスト教の思想家を見分ける', freq: 'よく出る', when: '「原罪」「信仰義認」「恩寵」「信仰と理性の調和」などのことばから人物を問われたら、この型です。', how: ['パウロ=原罪からの救いはキリストへの信仰による(信仰義認)、と確かめる。', 'アウグスティヌス=人は神の恩寵なしには救われない、三元徳(信仰・希望・愛)、と確かめる。', 'トマス・アクィナス=アリストテレス哲学を取り入れ、信仰と理性の調和をはかった、と確かめる。'], ex: { q: '「人は律法を行うことによってではなく、キリストを信じる信仰によって神に正しい者とされる」と説き、キリスト教を異邦人に広めた人物はだれか。', a: 'パウロ', exp: 'パウロは、もとはキリスト教徒を迫害していましたが、回心して伝道者になりました。人はアダム以来の原罪を負っており、自分の力ではなく、キリストへの信仰によって救われると説きました。' } },
      { name: '教えの「微妙な言いかえ」を見ぬく', freq: '難関大で出る', when: '似た文の選択肢が並び、宗教の教えとして正しいものを1つ選ぶ問題は、この型です。', how: ['選択肢の主語(だれが・どの宗教が)と、述語(何をする・何を認める)を分けて読む。', '「神の子」「預言者」「救世主」などの位置づけのちがいに特に注意する。', '「すべて」「必ず」「だけ」など、言い切りの強いことばが本来の教えと合うかを確かめる。'], ex: { q: '次の文は正しいか。「イスラームでは、イエスは神の子であり、ムハンマドはその教えを受けつぐ弟子とされる。」', a: '誤り', exp: 'イスラームでは、イエスは神の子ではなく、預言者の一人とされます。ムハンマドは最後で最大の預言者です。イエスの位置づけは、キリスト教(神の子・救世主)とイスラーム(預言者)で大きくちがいます。' } }
    ],
    more: [
      { lv: 1, q: 'ユダヤ教の聖典は、キリスト教では何とよばれているか。', a: '旧約聖書', exp: 'ユダヤ教ではこれを単に「聖書」とよびます。「旧約」は、イエスによる新しい契約(新約)に対して古い契約という意味で、キリスト教側からのよび方です。' },
      { lv: 1, q: 'キリスト教徒を迫害していたが回心し、ユダヤ人以外の人々(異邦人)にキリスト教を広めた使徒はだれか。', a: 'パウロ', exp: 'パウロは地中海の各地を旅して教会をつくり、多くの手紙(書簡)を書きました。それらは新約聖書に収められています。' },
      { lv: 1, q: 'イスラームの聖地で、信者が一生に一度は巡礼することが義務とされている都市はどこか。', a: 'メッカ', exp: 'メッカには神殿カーバがあり、礼拝もメッカの方角に向かって行います。巡礼は五行の一つで、体と経済の面で可能な人の義務とされます。' },
      { lv: 1, q: '仏教を開いたブッダ(仏陀)の、出家する前の名前を答えよ。', a: 'ゴータマ=シッダッタ(ガウタマ=シッダールタ)', exp: 'ブッダは「目覚めた人」という意味で、悟りを開いた人をさすことばです。釈迦族の王子として生まれたので、釈迦ともよばれます。' },
      { lv: 1, q: '古代インドの身分制度(ヴァルナ)で、最上位に置かれ、祭祀を担当した身分を何というか。', a: 'バラモン', exp: 'ヴァルナは、バラモン(司祭)・クシャトリヤ(王侯・武士)・ヴァイシャ(庶民)・シュードラ(隷属民)の4つに分かれていました。バラモン教はこの身分を前提にしていました。' },
      { lv: 1, q: '仏教で、すべてのものは他のものとの関係によって成り立っており、それだけで存在するものはないという考えを何というか。', a: '縁起', exp: '縁起は「因(原因)と縁(条件)によって起こる」という意味です。仏教の教えの土台にある考え方で、無常や無我の教えも縁起から導かれます。' },
      { lv: 1, q: 'イスラームの六信で、信じるべき対象にふくまれないものはどれか。', choices: ['天使', '来世', '天命', '偶像'], a: 'D(偶像)', exp: '六信は、神(アッラー)・天使・啓典・預言者・来世・天命です。イスラームでは偶像崇拝はきびしく禁じられています。' },
      { lv: 2, q: '仏教の四諦のうち、「苦しみの原因は、ものごとに執着する煩悩(渇愛)にある」という真理を何というか。', a: '集諦', exp: '四諦は、苦諦(人生は苦である)・集諦(苦の原因は煩悩)・滅諦(煩悩をなくせば苦はなくなる)・道諦(そのための八正道)の4つです。' },
      { lv: 2, q: '仏教の八正道にふくまれないものはどれか。', choices: ['正見', '正語', '正定', '正富'], a: 'D(正富)', exp: '八正道は、正見・正思(正思惟)・正語・正業・正命・正精進・正念・正定です。財産を求める道はふくまれません。快楽と苦行の両極端を離れた中道の実践です。' },
      { lv: 2, q: 'スリランカやタイ、ミャンマーなど東南アジアに主に伝わった仏教の系統を何というか。', a: '上座部仏教', exp: '上座部仏教は、出家して修行し、自ら悟りを開くこと(阿羅漢)を理想とします。中国・朝鮮・日本に伝わったのは、多くの人々の救いを重んじる大乗仏教です。' },
      { lv: 2, q: 'イスラームで、信者が日の出から日没まで飲食をつつしむ断食が行われる月を何というか。', a: 'ラマダーン', exp: '断食(サウム)は五行の一つで、イスラームの暦の第9月にあたるラマダーンに行われます。飢えた人の苦しみを知り、神への感謝を深める意味があるとされます。' },
      { lv: 2, q: 'ユダヤ教の「選民思想」とはどのような考えか。', a: 'ユダヤ人(イスラエルの民)は、神から選ばれ、神と特別な契約を結んだ民族であるという考え。', exp: '選民思想は、神の命令(律法)を守る責任をともなうものとされました。国を失うなどの苦難の中で、民族の結びつきを支える考えにもなりました。' },
      { lv: 2, q: 'インドで、不殺生(アヒンサー)をきびしく守り、苦行を重んじる宗教を開いた人物はだれか。', choices: ['ヴァルダマーナ', 'ナーガールジュナ', 'ムハンマド', 'モーセ'], a: 'A(ヴァルダマーナ)', exp: 'ヴァルダマーナはブッダと同じころの人物で、ジャイナ教を開きました。小さな虫も殺さないようにするなど、徹底した不殺生を説きました。' },
      { lv: 2, q: 'イスラームについての説明として、正しいものはどれか。', choices: ['ムハンマドは神の子とされる', 'イエスも預言者の一人とされる', '聖典は旧約聖書だけである', '偶像を通して神を礼拝する'], a: 'B(イエスも預言者の一人とされる)', exp: 'イスラームでは、モーセやイエスも神のことばを伝えた預言者と認められ、ムハンマドは最後で最大の預言者とされます。聖典はクルアーンで、偶像崇拝は禁じられています。' },
      { lv: 2, q: 'キリスト教で、人間は最初の人間アダムが神にそむいて以来、生まれながらに罪を負っているという考えを何というか。', a: '原罪', exp: 'パウロは、人は原罪のために自分の力では救われず、キリストの十字架の死によって罪がゆるされると説きました。この考えはアウグスティヌスにも引きつがれました。' },
      { lv: 3, q: 'イエスは、ユダヤ教の律法を形式的に守ることを重んじたパリサイ派の人々を批判した。イエスは律法をどのようにとらえ直したか説明せよ。', a: '律法を形の上で守ることではなく、その根本にある神への愛と隣人への愛を実践することこそが大切だととらえ直した。', exp: 'イエスは、安息日でも病人をいやしたり、罪人とされた人とも食事をしたりしました。律法の文字にしばられるのではなく、愛という律法の精神を生きることを説いたのです。' },
      { lv: 3, q: 'キリスト教の「三位一体」とはどのような考えか。', a: '父なる神・子なるキリスト・聖霊は、3つの位格(あり方)をもちながら、本質においては1つの神であるという考え。', exp: '三位一体説は、古代の教会の会議を通じて正統な教えとして確立しました。イエスを神と認めるかどうかは、イスラームやユダヤ教とのちがいの中心でもあります。' },
      { lv: 3, q: 'イスラームで偶像崇拝が禁じられている理由を、神のとらえ方から説明せよ。', a: '神(アッラー)は唯一絶対で、形をもたず、何ものにもたとえられない存在だから。人がつくった像を神のように拝むことは、神以外のものを神と並べる最大の罪とされる。', exp: 'イスラームのモスクには、神や預言者の像がありません。かわりに、アラベスクとよばれる幾何学模様や、クルアーンの文字が装飾に使われています。' },
      { lv: 3, q: 'バラモン教の「梵我一如」と、ブッダの「諸法無我」は、自己(アートマン)のとらえ方がどのようにちがうか説明せよ。', a: 'バラモン教では、変わらない自己の本質(アートマン)があり、それが宇宙の原理(ブラフマン)と一つになると考えた。ブッダは、すべては縁起によって成り立つので、変わらない実体としての自己はないと説いた。', exp: 'ブッダは、固定した自己があると思いこむことが執着を生み、苦しみの原因になると考えました。同じインドの思想でも、自己を「ある」とするか「ない」とするかで大きく分かれます。' },
      { lv: 3, q: '大乗仏教で理想とされる菩薩とは、どのような人か。上座部仏教の阿羅漢と比べて説明せよ。', a: '菩薩は、自分が悟りを求めるだけでなく、慈悲の心で他の人々の救いのために努める人。阿羅漢は、修行によって自分自身が悟りに達した人であり、主に自分の救いをめざす点がちがう。', exp: '大乗とは「大きな乗り物」という意味で、多くの人を救いへ運ぶことを表します。自分だけでなく、他者とともに救われることを重んじるのが大乗仏教の特色です。' }
    ]
  });

  add('ri_china', {
    pat: [
      { name: '人間観から政治論を推理する', freq: 'とてもよく出る', when: '「人は生まれつき善か悪か」と、「どのように国を治めるか」が結びつけて問われたら、この型です。', how: ['人間観を見分ける(性善説=孟子、性悪説=荀子、利益で動く=韓非子)。', '性善説なら、生まれつきの善い心をのばす徳による政治(王道政治)と結びつける。', '性悪説なら、礼によって人を正しく導く礼治主義、さらにきびしい法と賞罰による法治主義へと結びつける。'], ex: { q: '「人は生まれつき利益を好むので、放っておくと争いが起こる。だから礼によって人を教え導かなければならない」と考えた思想家はだれか。', a: '荀子', exp: '荀子は性悪説の立場から、人の性質は努力(偽=人為)によって変えられると考え、そのために礼を重んじました(礼治主義)。弟子の韓非子は、この考えをさらに進めて法と刑罰を重んじました。' } },
      { name: '儒家と墨家・道家の「批判の応酬」を読む', freq: 'よく出る', when: '儒家の考えに対する批判が示され、だれがどの立場から批判したかを問われたら、この型です。', how: ['儒家の仁は、家族への愛から始まる「差のある愛」であることを確かめる。', '墨家は、それを差別的な愛(別愛)と批判し、だれをも等しく愛する兼愛を説いた、と結びつける。', '道家は、仁や礼のような人為的な道徳そのものを、無為自然の道から外れたものと批判した、と結びつける。'], ex: { q: '「自分の親と他人の親を区別して愛するから、争いが起こる。他人の親も自分の親と同じように愛すべきだ」と主張した思想家はだれか。', a: '墨子', exp: '墨子は、儒家の仁を、身近な人を優先する別愛だと批判し、すべての人を区別なく愛する兼愛を説きました。人々が互いに利益をもたらし合うこと(交利)も重んじました。' } },
      { name: '朱子学と陽明学を比べる', freq: 'とてもよく出る', when: '「理」「心」「知と行」などのことばから、朱子学か陽明学かを問われたら、この型です。', how: ['朱子学は、人の本性は理である(性即理)とし、ものの理をきわめる格物致知を重んじる、と確かめる。', '陽明学は、心そのものが理である(心即理)とし、知ることと行うことは一つ(知行合一)とする、と確かめる。', '陽明学では、生まれつきの良知を発揮すること(致良知)が大切だと結びつける。'], ex: { q: '「本当に知っているなら、必ず行いに表れる。知っていて行わないのは、まだ知らないのと同じだ」という考えは、朱子学と陽明学のどちらのものか。', a: '陽明学(王陽明の知行合一)', exp: '王陽明は、朱子学が知ることと行うことを分けて考えがちだと批判し、知と行は本来一つだと説きました。ソクラテスの「知行合一」と同じことばですが、別の思想なので人物を混同しないようにしましょう。' } },
      { name: '老子・荘子の考えを見分ける', freq: 'よく出る', when: '「無為自然」「柔弱」「小国寡民」「万物斉同」「逍遥遊」などのことばが出たら、この型です。', how: ['老子=道に従い、作為をしない無為自然、水のように争わない柔弱謙下、小さな共同体の小国寡民、と確かめる。', '荘子=すべてのものは道から見れば等しい万物斉同、とらわれずに自由に遊ぶ逍遥遊、と確かめる。', '社会や政治のあり方を語るのは老子、個人の心の自由を語るのは荘子、という傾向で見分ける。'], ex: { q: '「国は小さく、人民は少ないのがよい。便利な道具があっても使わず、人々は自分の土地で満ち足りて暮らす」という理想を説いたのはだれか。', a: '老子', exp: 'これは老子の「小国寡民」の理想です。文明や制度が発達するほど欲望や争いが増えると考え、素朴で自然な暮らしを理想としました。' } },
      { name: '名言・ことばから思想家を判定する', freq: 'とてもよく出る', when: '原典のことばや有名な一節が示され、思想家や考えを問われたら、この型です。', how: ['ことばの中のキーワード(仁・礼・義・兼愛・法・道・理・良知など)を探す。', 'キーワードを学派と結びつける(仁・礼=儒家、兼愛・非攻=墨家、法・術=法家、道・無為=道家)。', '同じ学派の中では、性善・性悪、理・心などのちがいでしぼりこむ。'], ex: { q: '「民を貴しと為し、社稷(国家)之に次ぎ、君を軽しと為す」と述べ、民を最も重んじた思想家はだれか。', a: '孟子', exp: '孟子は、政治は民のためにあると考え、民の生活を安定させる王道政治を説きました。民を苦しめる君主は天命を失い、交代させられてもよいという易姓革命の考えにつながります。' } }
    ],
    more: [
      { lv: 1, q: '孔子の思想の中心にある、人を愛する心を何というか。', a: '仁', exp: '仁は、家族への親愛の情(孝悌)から始まり、他の人々へと広げていく愛です。孔子は、仁を身につけた理想の人を君子とよびました。' },
      { lv: 1, q: '孔子が重んじた、仁が外に表れた、社会の秩序を保つための規範を何というか。', a: '礼', exp: '礼は、儀式の作法から日常のふるまいまでをふくむ社会的な規範です。孔子は、仁と礼が一体になることを理想としました。' },
      { lv: 1, q: '人は生まれつき善い心をもっているという性善説を説いた思想家はだれか。', a: '孟子', exp: '孟子は、だれにでも、育てれば仁・義・礼・智の徳になる4つの芽(四端)があると考えました。反対に、性悪説を説いたのは荀子です。' },
      { lv: 1, q: '人の生まれつきの性質は悪であるという性悪説を説いた思想家はだれか。', a: '荀子', exp: '荀子は「人の性は悪なり、その善なるものは偽(人為)なり」と述べました。礼による教育で人を善に導けると考えました。' },
      { lv: 1, q: '道家の祖とされ、「無為自然」を説いた思想家はだれか。', a: '老子', exp: '老子は、人の作為をはなれ、万物を生み出す道に従って自然に生きることを説きました。のちの荘子とあわせて、老荘思想とよばれます。' },
      { lv: 1, q: '明の時代に、「心即理」「知行合一」を説いて陽明学を開いた人物はだれか。', a: '王陽明(王守仁)', exp: '王陽明は、はじめ朱子学を学びましたが、理を外のものに求める考えに疑問をもちました。そして、理は自分の心の中にあると説きました。' },
      { lv: 1, q: '韓非子が属し、法と刑罰によって国を治めることを説いた学派を何というか。', a: '法家', exp: '法家は、戦国時代の厳しい争いの中で、君主の力を強める方法を説きました。秦の始皇帝による中国統一でも、法家の考えが用いられました。' },
      { lv: 2, q: '孔子は、刑罰で民を従わせる政治よりも、どのような政治をよいとしたか。', a: '為政者が徳を身につけ、その徳で民を導く政治(徳治主義)', exp: '孔子は「政を為すに徳を以てす」と述べました。刑罰で治めると民は罰を逃れようとするだけだが、徳と礼で導けば民は恥を知り正しくなる、と考えたのです。' },
      { lv: 2, q: '「小国寡民」を理想とした思想家はだれか。', choices: ['孔子', '墨子', '老子', '韓非子'], a: 'C(老子)', exp: '小国寡民は、小さな国で少ない民が素朴に暮らす社会を理想とする老子の考えです。大きな国家や文明が、争いや欲望を生むと考えました。' },
      { lv: 2, q: '朱子学で重んじられる「格物致知」とは、どのような意味か。', a: '一つ一つの事物の理をきわめて、知識を完全なものにすること。', exp: '朱子は、万物にはそれぞれ理がそなわっていると考え、物の理を一つずつ明らかにしていくことで、全体の理に通じると説きました。陽明学は、これを外に理を求めすぎると批判しました。' },
      { lv: 2, q: '孔子が理想とした、仁と礼を身につけた人格者を何というか。', a: '君子', exp: '君子は、もとは身分の高い人をさしましたが、孔子は徳のある人という意味で使いました。反対に、自分の利益ばかり考える人を小人とよびました。' },
      { lv: 2, q: '「知行合一」ということばで知られる思想家として、正しい組み合わせはどれか。', choices: ['朱子とプラトン', '王陽明とソクラテス', '孟子とアリストテレス', '荀子とエピクロス'], a: 'B(王陽明とソクラテス)', exp: '知行合一は、陽明学の王陽明と、古代ギリシアのソクラテスの考えを表すことばとして使われます。ただし、それぞれの意味の背景はちがうので注意が必要です。' },
      { lv: 2, q: '墨子の「兼愛」は、孔子の「仁」とどのような点でちがうか。', a: '仁は家族などの身近な人から順に広げていく差のある愛だが、兼愛は自分と他人を区別せず、すべての人を等しく愛するという点。', exp: '墨子は、身近な人を優先する愛こそが争いのもとになると考えました。愛の範囲と順序をどう考えるかが、儒家と墨家の大きなちがいです。' },
      { lv: 2, q: '荀子に学び、のちに法家の思想を大成した人物はだれか。', choices: ['孟子', '韓非子', '荘子', '朱子'], a: 'B(韓非子)', exp: '韓非子は、荀子の性悪説を受けつぎつつ、礼ではなく法と賞罰によって人を動かすべきだと考えました。同じく荀子に学んだ李斯は、秦の政治で法家の考えを実行しました。' },
      { lv: 2, q: '『論語』の「学びて思わざれば則ち罔し、思いて学ばざれば則ち殆し」とは、どのような意味か。', a: '学ぶだけで自分で考えなければ、ものごとがはっきりわからない。考えるだけで学ばなければ、ひとりよがりになって危うい。だから、学ぶことと考えることの両方が大切だという意味。', exp: '孔子は、知識を身につけることと、自分の頭で考えることを車の両輪のようにとらえました。学問に対する孔子の基本的な姿勢を表すことばです。' },
      { lv: 3, q: '性悪説の荀子の考えが、弟子の韓非子の法治主義へとつながった筋道を説明せよ。', a: '荀子は、人の性は悪だが、礼による教育で善に導けると考えた。韓非子は、人は利益で動くという見方をさらにおし進め、教育よりも、法にもとづく確実な賞罰で人を動かすべきだと考えた。', exp: 'どちらも「人は放っておけば争う」と見る点は共通しています。人を変える手段として、教育と礼を重んじるか、法と賞罰を重んじるかがちがいです。' },
      { lv: 3, q: '老子が「柔弱謙下」を説き、水を理想のたとえとした理由を説明せよ。', a: '水は柔らかく、争わずに低い所へ流れるが、万物をうるおし、かたい岩をもけずる強さをもつ。このように、へりくだって争わない生き方こそ、本当の強さだと考えたから。', exp: '老子は、強く見えるものほど折れやすく、柔らかいものの方が長く生き残ると考えました。力で競う世の中への批判がこめられています。' },
      { lv: 3, q: '王陽明は、朱子学のどのような点を批判して「心即理」を説いたか。', a: '朱子学が、理を外の事物の中に求め、一つ一つ理をきわめてから行うという、知ることと行うことを分ける考えに立っている点。理は自分の心の中にあり、心の良知に従って行うことが大切だとした。', exp: '王陽明は、竹の理をきわめようとして竹を見つめ続け、病気になったという逸話でも知られます。外に理を求めるのではなく、自分の心の働きに目を向けたのです。' },
      { lv: 3, q: '「天下の利を興し、天下の害を除く」ことを政治の目的とし、手厚い葬儀や音楽をむだとして退けた思想家はだれか。また、その主張の名前を2つ答えよ。', a: '墨子。節葬・非楽', exp: '墨子は、民の生活に役立つかどうか(実利)を重んじました。手厚い葬儀や音楽は、財や時間をむだにして民を苦しめると考え、節葬・非楽を説きました。ほかに兼愛・非攻も重要です。' },
      { lv: 3, q: '韓非子は、昔のやり方にこだわる儒家を「守株(株を守る)」の話でたとえて批判した。この話の内容と、批判の意味を説明せよ。', a: 'うさぎが切り株にぶつかって死んだのを見た農民が、またうさぎが手に入ると思い、畑仕事をやめて切り株を見張り続けたという話。昔の聖王のやり方を今の時代にそのまま当てはめようとする儒家の政治は、時代の変化を無視していると批判した。', exp: '韓非子は、時代が変われば政治のやり方も変えるべきだと考えました。戦国時代の現実に合った方法として、法と賞罰による政治を主張したのです。' }
    ]
  });

  add('ri_west', {
    pat: [
      { name: '帰納法と演繹法を見分ける', freq: 'よく出る', when: '推論の例が示され、「どちらの方法か」「その方法を説いたのはだれか」を問われたら、この型です。', how: ['個々の事実を集めて一般的な法則を導いていれば帰納法(ベーコン)と判断する。', '確実な原理から筋道立てて個々の結論を導いていれば演繹法(デカルト)と判断する。', '帰納法は例外が見つかると結論がくずれる、演繹法は出発点の原理が正しくないと結論も正しくない、という弱点もおさえる。'], ex: { q: '「すべての人間はいつか死ぬ。ソクラテスは人間である。だからソクラテスはいつか死ぬ」という推論は、帰納法と演繹法のどちらか。', a: '演繹法', exp: '一般的な原理(すべての人間は死ぬ)から、個別の結論(ソクラテスは死ぬ)を導いているので演繹法です。デカルトは、疑いえない原理から出発する演繹法を学問の方法としました。' } },
      { name: 'ベーコンの4つのイドラを判定する', freq: 'よく出る', when: '人が思いこみや偏見におちいる場面が示され、どのイドラにあたるかを問われたら、この型です。', how: ['人間という種に共通する感覚や心のくせなら種族のイドラ。', '個人の性格・教育・経験によるせまい見方なら洞窟のイドラ。', 'ことばの不適切な使い方やうわさによるなら市場のイドラ、権威や伝統的な学説をうのみにするなら劇場のイドラと判断する。'], ex: { q: 'ネットで広まったうわさを、確かめもせずに事実だと思いこんだ。これはベーコンのいうどのイドラか。', a: '市場のイドラ', exp: '市場のイドラは、人が集まって話をする中で、ことばが不正確に使われることから生まれる偏見です。うわさや言葉のあいまいさによる思いこみがこれにあたります。' } },
      { name: '社会契約説の三人を比べる', freq: 'とてもよく出る', when: '自然状態のようす・契約の中身・抵抗権・主権のありかなどが示され、ホッブズ・ロック・ルソーのだれかを問われたら、この型です。', how: ['自然状態を確かめる(ホッブズ=万人の万人に対する闘争、ロック=おおむね平和だが不安定、ルソー=自由で平等で平和)。', '契約の中身を確かめる(ホッブズ=主権者に自然権を譲渡、ロック=政府に権力を信託、ルソー=一般意志に従う共同体をつくる)。', '抵抗権を認めるのはロック、直接民主制を重んじるのはルソー、と結びつける。'], ex: { q: '「政府は、人民の生命・自由・財産を守るために権力を信託されたにすぎない。政府がそれを侵すなら、人民は政府をつくりかえることができる」と主張したのはだれか。', a: 'ロック', exp: 'ロックは、政府への権力は「信託」されたものだと考え、政府が信託に反すれば抵抗権(革命権)を行使できると説きました。この考えはアメリカ独立宣言にも影響を与えました。' } },
      { name: 'カントの道徳を場面にあてはめる', freq: 'とてもよく出る', when: '行為の動機が書かれ、「道徳的な価値があるか」「自律か他律か」「定言命法か仮言命法か」を問われたら、この型です。', how: ['行為の結果ではなく、動機(なぜそうしたか)を見る。', '義務だから・正しいからという理由なら、自律にもとづく道徳的な行為と判断する。', 'ほめられたい・得をしたいなど他の目的のためなら他律で、「〜ならば〜せよ」という仮言命法にすぎないと判断する。'], ex: { q: '「健康でいたいなら、毎朝運動しなさい」という命令は、カントのいう定言命法と仮言命法のどちらか。', a: '仮言命法', exp: '「健康でいたいなら」という条件がついていて、その目的のための手段を命じているので仮言命法です。カントは、道徳の命令は「〜ならば」の条件なしに「〜せよ」と無条件に命じる定言命法でなければならないと考えました。' } },
      { name: 'ヘーゲルの弁証法と人倫を読みとる', freq: 'よく出る', when: '対立するものが統一されてより高い段階に進む話や、家族・市民社会・国家の関係が問われたら、この型です。', how: ['ある立場(正)と、それと対立する立場(反)を見つける。', '両方のよい点を生かしながら、より高い段階で統一すること(止揚、アウフヘーベン)を確かめる。', '人倫では、家族(愛の結びつき)と市民社会(欲望の体系)の対立が、国家で止揚されると結びつける。'], ex: { q: 'ヘーゲルの人倫の考えで、人々が自分の利益を求めて競い合い、家族のような愛の結びつきが失われた段階を何とよぶか。', a: '市民社会(欲望の体系)', exp: 'ヘーゲルは、家族では愛によって結びつくが個人の自立がなく、市民社会では個人は自立するが人々がばらばらになると考えました。この対立を止揚したものが国家であり、人倫の最高の形とされます。' } }
    ],
    more: [
      { lv: 1, q: '「知は力なり」と述べ、自然を観察して法則を見いだす学問を重んじたイギリスの思想家はだれか。', a: 'フランシス・ベーコン', exp: 'ベーコンは、正しい知識をもてば自然を利用して人間の生活を豊かにできると考えました。そのために、観察や実験にもとづく帰納法を重んじました。' },
      { lv: 1, q: '「われ思う、ゆえにわれあり」と述べた思想家はだれか。', a: 'デカルト', exp: 'デカルトは、すべてを疑っても、疑っている自分が存在することだけは疑えないと考えました。これを哲学の第一原理とし、大陸合理論の祖とされます。' },
      { lv: 1, q: '『リヴァイアサン』をあらわし、強大な国家の必要を説いたイギリスの思想家はだれか。', a: 'ホッブズ', exp: 'リヴァイアサンは聖書に出てくる巨大な怪物の名前です。ホッブズは、争いを終わらせるために、人々が主権者に自然権をゆずりわたして強い国家をつくるべきだと考えました。' },
      { lv: 1, q: '『社会契約論』をあらわし、一般意志にもとづく政治を説いたフランスの思想家はだれか。', a: 'ルソー', exp: 'ルソーは、私利私欲の集まりである特殊意志や全体意志ではなく、共同体全体の利益をめざす一般意志に従う政治を求めました。' },
      { lv: 1, q: '『純粋理性批判』『実践理性批判』などをあらわしたドイツの哲学者はだれか。', a: 'カント', exp: 'カントは、人間の理性が何を知ることができ、何をなすべきかを批判的に検討しました。経験論と合理論を総合した人物としても知られます。' },
      { lv: 1, q: '1517年に「95か条の論題」を発表し、宗教改革のきっかけをつくった人物はだれか。', a: 'ルター', exp: 'ルターは、お金で罪のゆるしが得られるとする贖宥状(免罪符)の販売を批判しました。人は信仰によってのみ救われると説き、聖書をドイツ語に訳しました。' },
      { lv: 1, q: 'ルネサンス期に、絵画・科学・技術など多くの分野ですぐれた業績を残し、「万能人」の代表とされる人物はだれか。', choices: ['ダンテ', 'レオナルド・ダ・ヴィンチ', 'カルヴァン', 'ホッブズ'], a: 'B(レオナルド・ダ・ヴィンチ)', exp: 'レオナルドは「モナ・リザ」などの絵画のほか、解剖学や機械の設計にも取り組みました。ルネサンスでは、あらゆる能力をのばした人間が理想とされました。' },
      { lv: 2, q: 'ことばの不適切な使い方や、人が集まって話すうちに広まるうわさから生まれる偏見を、ベーコンは何とよんだか。', a: '市場のイドラ', exp: 'ベーコンは、正しい知識をさまたげる偏見をイドラとよび、種族・洞窟・市場・劇場の4つに分けました。ことばや交流から生まれるのが市場のイドラです。' },
      { lv: 2, q: 'ホッブズは、国家がない自然状態での人間のようすを、どのようなことばで表したか。', a: '万人の万人に対する闘争', exp: 'ホッブズは、人間は自分の生命を守ろうとして互いに争うので、自然状態は戦争状態になると考えました。そこで、平和のために強い国家が必要だとしました。' },
      { lv: 2, q: 'ロックが認めた、政府が人民の自然権を侵したときに、人民が政府をつくりかえることができる権利を何というか。', a: '抵抗権(革命権)', exp: 'ロックは、政府は人民から権力を信託されたにすぎないと考えました。この考えは、名誉革命を正当化し、アメリカ独立宣言にも影響を与えました。' },
      { lv: 2, q: 'ルソーが理想とした政治の形として、正しいものはどれか。', choices: ['国王に主権をゆだねる絶対王政', '選挙で選んだ代表にすべてをまかせる間接民主制', '人民が直接政治に参加する直接民主制', '少数の哲学者が統治する哲人政治'], a: 'C(人民が直接政治に参加する直接民主制)', exp: 'ルソーは、主権は人民にあり、ゆずりわたすことも代表させることもできないと考えました。そのため、人民が直接政治に参加する直接民主制を理想としました。' },
      { lv: 2, q: 'ヘーゲルの弁証法で、対立する2つのものを、それぞれのよい点を生かしながらより高い段階で統一することを何というか。', a: '止揚(アウフヘーベン)', exp: '止揚には、「否定する」「保存する」「高める」という3つの意味がふくまれています。ヘーゲルは、世界も歴史もこの弁証法によって発展すると考えました。' },
      { lv: 2, q: 'デカルトが、精神と物体をそれぞれ独立した実体と考えた立場を何というか。', a: '物心二元論(心身二元論)', exp: 'デカルトは、精神の本質は考えること、物体の本質は空間的な広がり(延長)だとしました。この考えは、自然を機械のように見る近代科学の土台になりました。' },
      { lv: 2, q: 'イギリス経験論の思想家として正しいものはどれか。', choices: ['スピノザ', 'ライプニッツ', 'バークリー', 'デカルト'], a: 'C(バークリー)', exp: 'イギリス経験論には、ベーコン・ロック・バークリー・ヒュームなどがいます。デカルト・スピノザ・ライプニッツは、理性による推論を重んじた大陸合理論の思想家です。' },
      { lv: 2, q: '世界は、それ以上分けられない精神的な単位(モナド)からなり、それらは神によってあらかじめ調和するように定められている(予定調和)と考えた思想家はだれか。', a: 'ライプニッツ', exp: 'ライプニッツはドイツの大陸合理論の思想家です。モナドはたがいに影響し合わないが、神の定めた予定調和によって世界全体の秩序が保たれていると考えました。' },
      { lv: 3, q: '「有名な学者が書いた本に書いてあるのだから正しい」と思いこむことは、ベーコンのいうどのイドラにあたるか。また、ベーコンはこれをどう乗りこえるべきだと考えたか。', a: '劇場のイドラ。権威や伝統的な学説をうのみにせず、自分で観察や実験を行い、事実から確かめるべきだと考えた。', exp: '劇場のイドラは、舞台の上の芝居を本物と思いこむように、学説や権威を信じこむ偏見です。ベーコンは、偏見を取り除いたうえで帰納法を用いることを求めました。' },
      { lv: 3, q: '客に正直な値段で品物を売る商人が、「正直にしておくと評判がよくなり、もうかるから」という理由でそうしていた。カントの考えでは、この行為に道徳的な価値はあるか。理由とともに答えよ。', a: '道徳的な価値はない。行為は義務にかなっているが、もうけという別の目的のために行っており、義務そのものを動機としていないから。', exp: 'カントは、義務にかなう行為(適法性)と、義務にもとづく行為(道徳性)を区別しました。結果が同じでも、動機が「正しいから」でなければ道徳的な価値はないとしました。' },
      { lv: 3, q: 'ヘーゲルの考える人倫の3つの段階を順に答え、最後の段階がどのような意味で最高の形とされるのかを説明せよ。', a: '家族→市民社会→国家。国家は、家族の愛による結びつきと、市民社会の個人の自立の両方を生かして統一したもの(止揚)であり、自由が最もよく実現される共同体とされるから。', exp: 'ヘーゲルは、カントの道徳が個人の内面にとどまると批判し、自由は社会の制度や共同体の中で実現されると考えました。それが人倫です。' },
      { lv: 3, q: '「存在するとは知覚されることである」と述べたバークリーの考えを説明せよ。', a: '物は、だれかに見られたりさわられたりして知覚されることで初めて存在するのであり、知覚をはなれて物そのものが存在するとはいえない、という考え。', exp: 'バークリーは、経験論をおし進め、人が知りうるのは自分の知覚だけだと考えました。だれも見ていないときの物の存在は、神が知覚していることで保たれると説明しました。' },
      { lv: 3, q: 'ルソーのいう「一般意志」と「全体意志」のちがいを説明せよ。', a: '一般意志は、共同体全体の利益(公共の利益)をめざす人民の意志である。全体意志は、各人が自分の利益を求める特殊意志を単に合計したものにすぎない。', exp: 'ルソーは、多数決の結果がそのまま一般意志になるとは限らないと考えました。人々が私利私欲をはなれ、公共の利益を考えて決めることが大切だとしたのです。' }
    ]
  });

  add('ri_modern', {
    pat: [
      { name: '功利主義で政策を比べる(量と質)', freq: 'よく出る', when: '複数の政策や行為が、人々にもたらす快楽や幸福の量で比べられていたら、この型です。', how: ['影響を受けるすべての人の快楽(+)と苦痛(−)を合計する(ベンサムの快楽計算)。', 'だれの快楽も等しく1人分として数える。', 'ミルの立場なら、精神的な快楽など「質の高い快楽」を重んじる点も考える。'], ex: { q: '政策Aでは3人がそれぞれ+5の幸福を得て1人が−8の苦痛を受ける。政策Bでは4人がそれぞれ+2の幸福を得る。ベンサムの快楽計算で選ばれるのはどちらか。', a: '政策B', exp: 'Aの合計は 5×3−8=7、Bの合計は 2×4=8 です。合計の大きいBが選ばれます。ベンサムは「最大多数の最大幸福」を基準とし、だれの幸福も1人分として等しく数えました。' } },
      { name: '実存主義者をキーワードで見分ける', freq: 'とてもよく出る', when: '「主体的真理」「超人」「限界状況」「死への存在」「アンガージュマン」などのことばが出たら、この型です。', how: ['キルケゴール=主体的真理・実存の三段階・「あれか、これか」。', 'ニーチェ=神は死んだ・超人・力への意志・永劫回帰。', 'ヤスパース=限界状況・実存的交わり、ハイデッガー=世界内存在・死への存在、サルトル=実存は本質に先立つ・アンガージュマン、と結びつける。'], ex: { q: '「人間は、死・苦悩・争い・罪などの壁にぶつかって挫折することで、自分をこえた存在(包括者)に気づき、本来の自己に目覚める」と考えたのはだれか。', a: 'ヤスパース', exp: 'ヤスパースは、人間がどうしても避けられない壁を限界状況とよびました。そこでの挫折を通して、また他者との実存的交わりを通して、人は本来の自己に目覚めると考えました。' } },
      { name: '思想家どうしの「批判の向き」を押さえる', freq: '難関大で出る', when: '「〜は〜のどこを批判したか」や、論争の相手が問われたら、この型です。', how: ['批判された側の主張の中心をまず確かめる。', '批判した側が、どの点を問題にしたかを結びつける(ロールズ→功利主義、ノージック・サンデル→ロールズ、キルケゴール→ヘーゲル、マルクス→ヘーゲルの観念論など)。', '批判した側が、代わりに何を示したかまで答える。'], ex: { q: 'ノージックは、ロールズの格差原理にもとづく所得の再分配をどのように批判したか。', a: '正当に得た財産を、本人の同意なく税で取り上げて他人に分けることは、個人の自由と所有権の侵害だと批判し、最小国家を主張した。', exp: 'ノージックはリバタリアニズム(自由至上主義)の立場をとりました。国家の役割は、暴力や盗み・詐欺から人々を守ることなどに限るべきだと考えたのです。' } },
      { name: 'ロールズの正義論を事例にあてはめる', freq: 'とてもよく出る', when: '社会のしくみを選ぶ場面や、格差をどこまで認めるかが問われたら、この型です。', how: ['原初状態で、自分の能力や立場がわからない「無知のヴェール」をかけて考える。', '第一原理=基本的な自由はすべての人に平等に保障される。', '第二原理=格差は、公正な機会の均等のもとで、最も恵まれない人の利益を最大にする場合にだけ認める(格差原理)。'], ex: { q: '社会Xでは最も恵まれない人の所得が10で平均が50、社会Yでは最も恵まれない人の所得が20で平均が40である。ロールズの格差原理によれば、どちらの社会が選ばれるか。', a: '社会Y', exp: '格差原理では、最も恵まれない人の状態がよりよくなる方を選びます。Yでは最も恵まれない人の所得が20で、Xの10より高いからです。平均や合計で比べる功利主義なら、Xを選ぶことになります。' } },
      { name: 'プラグマティズムの真理観', freq: 'よく出る', when: '「役に立つかどうか」「結果で確かめる」「知性は問題解決の道具」などの考えが出たら、この型です。', how: ['パース=考えの意味は、それがもたらす実際の結果で明らかになる、と確かめる。', 'ジェームズ=ある考えが生活の中で役に立つなら、それは真理である(真理の有用性)、と確かめる。', 'デューイ=知性は問題を解決するための道具(道具主義・創造的知性)と結びつける。'], ex: { q: '「ある信念が、私たちの生活の中で実際に役に立ち、満足をもたらすなら、その信念は真理である」と考えた思想家はだれか。', a: 'ジェームズ', exp: 'ジェームズは、真理は固定されたものではなく、経験の中で確かめられ、役に立つことで真理になると考えました。宗教の信仰についても、人生に意味を与えるならその人にとって真理だとしました。' } }
    ],
    more: [
      { lv: 1, q: '「最大多数の最大幸福」を道徳と立法の原理とした思想家はだれか。', a: 'ベンサム', exp: 'ベンサムは、快楽を増やし苦痛を減らす行為が善であると考えました。社会全体の幸福の総量を大きくすることを、法律や政治の目標としました。' },
      { lv: 1, q: '「満足した豚であるより、不満足な人間であるほうがよい」と述べ、快楽には質のちがいがあると説いた思想家はだれか。', a: 'J.S.ミル', exp: 'ミルは、ベンサムの量的功利主義を修正し、精神的な快楽は肉体的な快楽より質が高いと考えました。これを質的功利主義といいます。' },
      { lv: 1, q: '『資本論』をあらわし、資本主義のしくみを分析して批判した思想家はだれか。', a: 'マルクス', exp: 'マルクスは、資本家が労働者の生み出した価値の一部を利潤として得ているしくみを分析しました。エンゲルスとともに科学的社会主義を説きました。' },
      { lv: 1, q: 'ニーチェが理想とした、ニヒリズムを乗りこえ、自ら新しい価値を生み出す人間を何というか。', a: '超人', exp: 'ニーチェは、神の死によってそれまでの価値が失われた時代に、力への意志にもとづいて自ら価値を創造する人間を超人とよびました。' },
      { lv: 1, q: '「実存は本質に先立つ」と述べたフランスの思想家はだれか。', a: 'サルトル', exp: 'サルトルは、人間はまず存在し、その後で自分の生き方を選び、自分が何者であるか(本質)をつくっていくと考えました。' },
      { lv: 1, q: '知性は問題を解決するための道具であると考え、道具主義を説いたアメリカの思想家はだれか。', a: 'デューイ', exp: 'デューイはプラグマティズムを大成し、教育の分野でも、子どもが経験を通じて問題を解決していく学習を重んじました。' },
      { lv: 1, q: '『正義論』をあらわし、公正としての正義を説いたアメリカの思想家はだれか。', a: 'ロールズ', exp: 'ロールズは、功利主義では少数者の犠牲が正当化されかねないと批判し、すべての人が合意できる正義の原理を示そうとしました。' },
      { lv: 2, q: '政策Aでは5人がそれぞれ+3の幸福を得て、2人がそれぞれ−4の苦痛を受ける。政策Bでは6人がそれぞれ+1の幸福を得る。ベンサムの快楽計算で選ばれるのはどちらか。', a: '政策A', exp: 'Aの合計は 3×5−4×2=15−8=7、Bの合計は 1×6=6 です。合計の大きいAが選ばれます。苦痛を受ける人がいても、全体の合計で判断するのがベンサムの快楽計算の特徴です。' },
      { lv: 2, q: 'キルケゴールが説いた実存の三段階を、順に答えよ。', a: '美的実存→倫理的実存→宗教的実存', exp: '美的実存は快楽を求めて生きる段階、倫理的実存は義務や責任を引き受けて生きる段階です。どちらにも絶望し、最後に神の前にただひとり立つ宗教的実存に至るとされます。' },
      { lv: 2, q: 'ヤスパースが、真の自己に目覚めた者どうしが、たがいに誠実に向き合い語り合う関係を何とよんだか。', a: '実存的交わり(愛しながらの戦い)', exp: 'ヤスパースは、限界状況での挫折に加えて、他者との実存的交わりによっても、人は本来の自己になれると考えました。なれ合いではなく、真剣に向き合う関係です。' },
      { lv: 2, q: 'サルトルが、人間は社会の問題に自ら関わり、自分の選択に責任をもつべきだとして用いたことばを何というか。', a: 'アンガージュマン(社会参加)', exp: 'サルトルは、自分の選択は人類全体のあり方を選ぶことでもあると考えました。そのため、社会や政治の問題に積極的に関わることを求めました。' },
      { lv: 2, q: 'ノージックが主張した、個人の自由を最も重んじ、国家の役割を最小限にとどめるべきだとする立場を何というか。', a: 'リバタリアニズム(自由至上主義)', exp: 'リバタリアニズムは、税による所得の再分配に反対し、国家の役割を治安や契約の保護などに限る最小国家を理想とします。' },
      { lv: 2, q: '「ある考えが真理かどうかは、それが実際の生活で役に立つかどうかで決まる」という考えに最も近い思想家はだれか。', choices: ['ジェームズ', 'ハイデッガー', 'キルケゴール', 'ベンサム'], a: 'A(ジェームズ)', exp: 'ジェームズは、真理の基準を有用性に置きました。プラグマティズムの思想家には、ほかにパースやデューイがいます。' },
      { lv: 2, q: 'ハーバーマスが、対等な立場で理由を示し合いながら、話し合いによって合意をめざす理性を何とよんだか。', a: '対話的理性(コミュニケーション的合理性)', exp: 'ハーバーマスは、目的を効率よく達成するための道具としての理性だけでなく、対話によって相互の理解と合意をつくる理性を重んじました。' },
      { lv: 2, q: 'マルクスとともに『共産党宣言』をあらわした人物はだれか。', choices: ['ベンサム', 'エンゲルス', 'ミル', 'デューイ'], a: 'B(エンゲルス)', exp: 'エンゲルスはマルクスの協力者で、ともに『共産党宣言』をあらわしました。「万国の労働者よ、団結せよ」ということばで知られています。' },
      { lv: 3, q: 'ベンサムとミルの功利主義のちがいを、「量」と「質」ということばを使って説明せよ。', a: 'ベンサムは、快楽はすべて同じ質であり、量の大小で比べられると考えた(量的功利主義)。ミルは、快楽には質のちがいがあり、精神的な快楽の方が質が高いと考えた(質的功利主義)。', exp: 'ミルは、両方の快楽を知る人は、精神的な快楽の方を選ぶと考えました。また、ベンサムが法律などの外からの制裁を重んじたのに対し、ミルは良心という内的な制裁を重んじました。' },
      { lv: 3, q: 'ロールズのいう「無知のヴェール」とは何か。また、それが正義の原理を選ぶうえでなぜ役立つと考えられたか説明せよ。', a: '自分の能力・財産・性別・社会的な地位などがわからない状態を想定すること。自分が最も恵まれない立場になるかもしれないので、だれにとっても公正なしくみを選ぶようになるから。', exp: '自分の立場がわかっていると、人は自分に有利なルールを選びがちです。立場がわからない状態で選べば、かたよりのない原理に合意できるとロールズは考えました。' },
      { lv: 3, q: 'ニーチェの「永劫回帰」と「運命愛」とは、どのような考えか説明せよ。', a: '永劫回帰は、この人生が目的も意味もないまま、まったく同じように永遠にくり返されるという考え。運命愛は、それを受け入れ、「これが人生か、よし、もう一度」と肯定して生きる態度。', exp: '永劫回帰は、ニヒリズムの最も極端な形です。ニーチェは、それをおそれるのではなく積極的に肯定することこそが、超人の生き方だと考えました。' },
      { lv: 3, q: 'キルケゴールは、ヘーゲルの哲学のどのような点を批判したか。「主体的真理」ということばを使って説明せよ。', a: 'ヘーゲルは世界全体を説明する客観的な体系をつくったが、その中では、この私がどう生きるかという問題が見失われてしまうと批判した。そして、自分がそのために生き、そのために死ねるような主体的真理を求めた。', exp: 'キルケゴールは、普遍的な理論よりも、ひとりの人間が決断して生きることを重んじました。「あれか、これか」の選択をせまられる実存の姿を問題にしたのです。' },
      { lv: 3, q: 'ある政策の結果、社会全体の幸福の合計は増えるが、少数の人々の基本的な自由が大きく制限される。功利主義とロールズの立場では、この政策をどのように評価するか。', a: '功利主義(ベンサム)では、幸福の合計が増えるので認められうる。ロールズは、基本的な自由はすべての人に平等に保障されるべきで(第一原理)、全体の利益のために一部の人の自由を犠牲にすることは認められないと考える。', exp: 'ロールズは、第一原理(平等な自由)を第二原理より優先させました。功利主義が「多数の幸福のための少数の犠牲」を正当化しうる点こそ、ロールズが批判したところです。' }
    ]
  });

  add('ri_japan', {
    pat: [
      { name: '鎌倉仏教の開祖を教えで見分ける', freq: 'とてもよく出る', when: '念仏・坐禅・題目などの修行の方法や、他力・自力の考えが示され、人物や宗派を問われたら、この型です。', how: ['念仏(南無阿弥陀仏)なら浄土系と考え、法然(専修念仏)、親鸞(悪人正機・絶対他力)、一遍(踊念仏)を区別する。', '坐禅なら禅宗と考え、栄西(臨済宗・公案)、道元(曹洞宗・只管打坐)を区別する。', '題目(南無妙法蓮華経)なら日蓮と結びつける。'], ex: { q: 'ひたすら坐禅に打ちこむこと(只管打坐)を説き、坐禅という修行そのものが悟りの表れであると考えた人物はだれか。', a: '道元', exp: '道元は曹洞宗を開きました。修行と悟りは別のものではなく一つである(修証一等)と考えました。公案という問題を考えながら坐禅を行う栄西の臨済宗と区別しましょう。' } },
      { name: '江戸の儒学者を立場で見分ける', freq: 'よく出る', when: '朱子学・陽明学・古学などの立場や、「上下定分の理」「孝」「誠」「先王の道」などのことばから人物を問われたら、この型です。', how: ['朱子学=林羅山(上下定分の理)、と確かめる。', '陽明学=中江藤樹(孝・近江聖人)、と確かめる。', '古学=山鹿素行(士道)、伊藤仁斎(古義学・仁愛と誠)、荻生徂徠(古文辞学・安天下の道)と区別する。'], ex: { q: '『論語』『孟子』の本来の意味を、後の時代の解釈にたよらず直接読みとろうとし、日常の人間関係の中の仁愛と誠を重んじた儒学者はだれか。', a: '伊藤仁斎', exp: '伊藤仁斎は、朱子学の解釈を批判し、孔子・孟子の原典に立ち返る古義学をとなえました。うそいつわりのない心である誠を、人と人の間の愛(仁愛)の根本としました。' } },
      { name: '国学者を「何を重んじたか」で区別する', freq: 'よく出る', when: '『万葉集』『古事記』『源氏物語』などの古典や、「ますらをぶり」「もののあはれ」「真心」などのことばから人物を問われたら、この型です。', how: ['賀茂真淵=『万葉集』に、おおらかで男性的な「ますらをぶり」を見いだした、と確かめる。', '本居宣長=『古事記』『源氏物語』を研究し、「もののあはれ」と「真心」を重んじた、と確かめる。', '平田篤胤=国学を宗教的に発展させた復古神道で、幕末の尊王思想に影響した、と結びつける。'], ex: { q: '『源氏物語』の本質は「もののあはれ」を知ることにあると考えた国学者はだれか。', a: '本居宣長', exp: '本居宣長は、ものごとにふれて素直に心が動くことを「もののあはれ」とよび、それを知る心を重んじました。儒学や仏教の考え方(漢意)を取り除いた、生まれつきの真心を理想としました。' } },
      { name: '近代の思想家を「何を拠りどころにしたか」で区別する', freq: 'とてもよく出る', when: '明治から昭和の思想家の主張が示され、だれの考えかを問われたら、この型です。', how: ['西洋の学問と独立の精神=福沢諭吉、自由民権と人民の権利=中江兆民、と確かめる。', 'キリスト教の信仰と日本=内村鑑三(二つのJ)、個人の内面と生き方=夏目漱石(自己本位)、と確かめる。', '東洋の思想と西洋哲学の統合=西田幾多郎(純粋経験)、人と人との関係=和辻哲郎(間柄的存在)と結びつける。'], ex: { q: '「イエス(Jesus)と日本(Japan)」の2つのJにつかえることを生涯の目標とした思想家はだれか。', a: '内村鑑三', exp: '内村鑑三は、キリスト教の信仰と日本への愛を両立させようとしました。教会の制度にたよらない無教会主義を説き、日露戦争のときには非戦論を主張しました。' } },
      { name: '古代日本人の考え方を読みとる', freq: 'よく出る', when: '神々のとらえ方、罪やけがれ、日常と祭りの区別など、古代の日本人の考え方が問われたら、この型です。', how: ['神は自然の中に数多くいる八百万の神で、恵みをもたらす一方でたたりもおこす、と確かめる。', '罪やけがれは、みそぎやはらいで清められると考えた、と確かめる。', '理想の心は、うそやかくしごとのない清き明き心(清明心)と結びつける。'], ex: { q: '古代の日本人が、罪やけがれを水で洗い清めることを何とよんだか。', a: 'みそぎ', exp: '古代の日本人は、罪やけがれは外からついたもので、水で洗い流したり(みそぎ)、儀式で取り除いたり(はらい)すれば清められると考えました。神社で手や口をすすぐ習慣にも、その考えが残っています。' } }
    ],
    more: [
      { lv: 1, q: '「世間虚仮、唯仏是真(世の中はかりそめで、ただ仏だけが真実である)」ということばを残したとされる人物はだれか。', a: '聖徳太子(厩戸王)', exp: '聖徳太子は仏教を深く信仰し、十七条の憲法でも仏教を重んじることを説きました。このことばには、仏の教えを心の拠りどころとする姿勢が表れています。' },
      { lv: 1, q: '比叡山に延暦寺を開き、天台宗を伝えた平安時代の僧はだれか。', a: '最澄', exp: '最澄は、すべての人が仏になれると説く法華経の教えを重んじました。比叡山は、のちに法然・親鸞・道元・日蓮など、鎌倉仏教の開祖たちが学んだ場所にもなりました。' },
      { lv: 1, q: '「南無阿弥陀仏」とひたすら唱えることだけで、だれでも極楽浄土に往生できると説き、浄土宗を開いた人物はだれか。', a: '法然', exp: '法然は、ほかの修行をすべてやめて念仏だけを唱える専修念仏を説きました。身分や学問に関係なく救われる教えとして、多くの人々に広まりました。' },
      { lv: 1, q: '宋で禅を学び、曹洞宗を開いた人物はだれか。', a: '道元', exp: '道元は越前(福井県)に永平寺を開きました。著書『正法眼蔵』で、ひたすら坐禅をすること(只管打坐)の大切さを説きました。' },
      { lv: 1, q: '『学問のすゝめ』をあらわし、「天は人の上に人を造らず人の下に人を造らず」と述べた人物はだれか。', a: '福沢諭吉', exp: '福沢諭吉は、人は生まれながらに平等であるという天賦人権の考えを紹介しました。そのうえで、実際の差は学問をするかどうかで生まれるとし、実学をすすめました。' },
      { lv: 1, q: '古代の日本人が理想とした、うそやかくしごとのない、すんだ心を何というか。', a: '清き明き心(清明心)', exp: '清き明き心は、神々に対して何もかくさず、いつわりのない心です。のちの時代の「誠」や「正直」の考えにも受けつがれたとされます。' },
      { lv: 1, q: '民俗学で、祭りや年中行事などの特別な日を「ハレ」とよぶのに対して、ふだんの日常を何とよぶか。', a: 'ケ', exp: '柳田国男らの民俗学は、ハレとケの区別によって、人々の暮らしのリズムを説明しました。ハレの日には、晴れ着を着たり特別な食事をしたりします。' },
      { lv: 2, q: '各地を旅して、念仏を唱えながらおどる踊念仏を広め、時宗の開祖とされる人物はだれか。', choices: ['親鸞', '一遍', '栄西', '日蓮'], a: 'B(一遍)', exp: '一遍は、家や財産をすてて全国を旅し、念仏札を配って人々に念仏をすすめました。そのため「捨聖」ともよばれました。' },
      { lv: 2, q: '栄西が伝えた臨済宗で、坐禅とともに行われる、師から与えられる問題を考える修行を何というか。', a: '公案', exp: '公案は、ふつうの論理では答えられないような問いを考えぬくことで、悟りに近づこうとする修行です。坐禅だけに打ちこむ曹洞宗との大きなちがいです。' },
      { lv: 2, q: '陽明学を学び、「孝」をすべての道徳の根本とし、「近江聖人」とよばれた江戸時代の儒学者はだれか。', a: '中江藤樹', exp: '中江藤樹は、孝を親に対する愛だけでなく、すべての人や天地をつらぬく根本の原理と考えました。身分に関係なく、人々に道徳を説きました。' },
      { lv: 2, q: '伊藤仁斎が、仁愛を実現するために最も重んじた、うそいつわりのない心を何というか。', a: '誠(真実無偽)', exp: '伊藤仁斎は、誠を儒学の道の中心に置きました。日常の人間関係の中で、自分も他人もいつわらない心を大切にしたのです。' },
      { lv: 2, q: '『万葉集』の研究を通して、古代の日本人のおおらかで力強い気風を「ますらをぶり」とよんで重んじた国学者はだれか。', a: '賀茂真淵', exp: '賀茂真淵は本居宣長の師です。『万葉集』の歌に見られる素直で男性的な心を理想としました。宣長は『古今和歌集』以降のやさしい気風(たをやめぶり)の価値も認めました。' },
      { lv: 2, q: '本居宣長が、ものごとにふれて素直に心が動き、しみじみと感じることを何とよんだか。', a: 'もののあはれ', exp: '宣長は、『源氏物語』の価値は道徳を教えることではなく、もののあはれを描いた点にあると考えました。儒学の勧善懲悪の読み方を批判したのです。' },
      { lv: 2, q: '中江兆民は、民権を「恩賜的民権」と「回復的民権」に分けた。それぞれの意味を答えよ。', a: '恩賜的民権は、君主などの上から人民に恵み与えられた権利。回復的民権は、イギリスやフランスのように人民が自ら勝ち取った権利。', exp: '兆民は、日本の民権は恩賜的民権だが、それを大切に育てて、実質的に回復的民権と同じものにしていくべきだと説きました。ルソーの『社会契約論』を翻訳したことでも知られます。' },
      { lv: 2, q: '1911年に雑誌『青鞜』を創刊し、「元始、女性は実に太陽であった」と述べて女性の自立をうったえた人物はだれか。', a: '平塚らいてう', exp: '平塚らいてうは、女性が自分の力で生きることを求めました。のちに市川房枝らと新婦人協会をつくり、女性の政治参加などを求める運動も進めました。' },
      { lv: 3, q: '道元の「修証一等」とは、どのような考えか説明せよ。', a: '修行(修)と悟り(証)は別のものではなく一つであり、坐禅という修行は悟りのための手段ではなく、それ自体が悟りの表れであるという考え。', exp: '道元は、悟りを得たら修行が終わるのではないと考えました。ひたすら坐禅をすること(只管打坐)によって、身心が一切のとらわれから解放される(身心脱落)と説きました。' },
      { lv: 3, q: '伊藤仁斎と荻生徂徠は、ともに朱子学を批判した。2人に共通する学問の方法と、2人の考えのちがいを説明せよ。', a: '共通点は、後の時代の解釈にたよらず、孔子・孟子などの古典の原典に直接立ち返って学ぶ古学の方法をとったこと。仁斎は日常の人間関係の中の仁愛や誠を重んじたが、徂徠は、道とは先王がつくった制度(礼楽刑政)であり、世を治め民を安んじるためのものだと考えた。', exp: '仁斎は個人の道徳を、徂徠は政治や制度を重んじた点がちがいます。徂徠の考えは、のちの経世論や国学の方法にも影響を与えました。' },
      { lv: 3, q: '平田篤胤の思想は、幕末の社会にどのような影響を与えたか。', a: '国学を宗教的に発展させた復古神道を説き、天皇を中心とする古代の道を重んじたため、幕末の尊王攘夷運動に大きな影響を与えた。', exp: '平田篤胤の考えは、農村の有力者などにも広まりました。国学が学問の世界にとどまらず、政治の動きと結びついていった例です。' },
      { lv: 3, q: '和辻哲郎は『風土』で、世界の風土を3つの型に分けた。その3つの型を答え、日本はどの型にふくまれるとしたか答えよ。', a: 'モンスーン型・砂漠型・牧場型。日本はモンスーン型にふくまれるとした。', exp: '和辻は、モンスーン型では自然の恵みと暴威の両方を受けるため、人々は受容的・忍従的になると考えました。風土が人間のあり方に影響するという見方は、間柄的存在の考えとも結びついています。' },
      { lv: 3, q: '夏目漱石は、講演「私の個人主義」で「自己本位」を説いた。この考えは、わがままとどのようにちがうか説明せよ。', a: '自己本位は、他人や西洋の考えのまねをせず、自分の考えにもとづいて生きることだが、同時に他人の個性も尊重し、自分の自由には義務と責任がともなうとする。自分だけの勝手を通すわがままとはちがう。', exp: '漱石は、西洋の文化をまねるだけの近代化を「外発的」と批判しました。自分の内面から出発しつつ、他者の自由も認める倫理的な個人主義をめざしたのです。' }
    ]
  });

  add('ri_bio', {
    pat: [
      { name: '事例を生命倫理の四原則にあてはめる', freq: 'とてもよく出る', when: '医療の場面が示され、どの原則が問題になっているか、どの原則どうしが対立しているかを問われたら、この型です。', how: ['自律尊重(本人の決定を尊重する)、無危害(害を与えない)、善行(本人の利益をはかる)、正義(公平に分ける)の4つを確かめる。', '場面の中の「本人の希望」「害」「利益」「公平さ」を、それぞれの原則に結びつける。', '対立する原則を見つけ、本人への十分な説明と話し合いなど、調整の方法まで考える。'], ex: { q: '数が限られた臓器を、待っている患者のだれに移植するかを、医学的な基準や待機期間にもとづいて公平に決める。これは四原則のどれを重んじたものか。', a: '正義原則', exp: '正義原則は、医療の資源や利益・負担を、人々の間で公平に分配することを求めます。限られた臓器や医療の配分を、地位やお金で決めないことが、この原則の具体的な表れです。' } },
      { name: '臓器移植法の内容と改正点', freq: 'よく出る', when: '脳死・臓器提供の条件や、本人の意思と家族の承諾の関係が問われたら、この型です。', how: ['1997年の臓器移植法では、本人の書面による意思表示と家族の承諾が必要で、15歳未満は提供できなかった、と確かめる。', '2009年の改正(2010年施行)で、本人の意思が不明でも家族の承諾で提供できるようになった、と確かめる。', 'これにより15歳未満からの提供も可能になり、親族への優先提供の意思表示も認められた、と結びつける。'], ex: { q: '2009年の臓器移植法の改正後、本人が臓器提供について意思を示していなかった場合、脳死後の臓器提供はできるか。', a: '家族が書面で承諾すれば提供できる。', exp: '改正前は本人の書面による意思表示が必要でした。改正後は、本人が提供を拒否していなければ、家族の承諾で提供できるようになりました。そのため、15歳未満の子どもからの提供も可能になりました。' } },
      { name: '安楽死・尊厳死・緩和ケアを区別する', freq: 'よく出る', when: '終末期の医療の場面が示され、それが何にあたるかを問われたら、この型です。', how: ['薬などで積極的に死期を早めるのは積極的安楽死と判断する。', '延命治療を差し控えたり中止したりして、自然な死をむかえるのは尊厳死(消極的安楽死)と判断する。', '死期を早めずに、痛みや不安をやわらげることを重んじるのは緩和ケア(ホスピス)と判断する。'], ex: { q: '回復の見込みのない患者が、あらかじめ書いておいた意思にもとづき、人工呼吸器による延命治療を受けずに自然な最期をむかえた。これは何にあたるか。', a: '尊厳死', exp: '尊厳死は、延命だけを目的とした治療を行わず、人間らしく自然な死をむかえることです。患者の意思を事前に示す書面をリビング・ウィルといいます。薬で死期を早める積極的安楽死とは区別されます。' } },
      { name: '環境倫理の3つの主張を見分ける', freq: 'とてもよく出る', when: '環境問題に関する意見が示され、自然の生存権・世代間倫理・地球全体主義のどれかを問われたら、この型です。', how: ['人間だけでなく、動物・植物・生態系にも生存の権利があるとするのが自然の生存権。', '現在の世代は、将来の世代の生存の可能性に責任を負うとするのが世代間倫理。', '地球の資源や環境は有限で、地球全体の生存を優先して考えるのが地球全体主義。'], ex: { q: '「私たちが今、資源を使いつくしてしまえば、まだ生まれていない人たちが生きる条件をうばうことになる」という意見は、環境倫理のどの主張にもとづくか。', a: '世代間倫理', exp: '将来の世代は、今の私たちの決定に反対することもできません。そのため、現在の世代が将来の世代への責任を負うべきだと考えるのが世代間倫理です。持続可能な開発の考え方とも結びついています。' } },
      { name: '情報社会の問題を概念にあてはめる', freq: 'よく出る', when: 'インターネットやSNSにかかわる場面が示され、それを表すことばや問題点を問われたら、この型です。', how: ['好みに合う情報だけが表示され、ちがう意見が見えなくなる→フィルターバブル。', '同じ意見の人どうしで意見が反響し、強まっていく→エコーチェンバー。', '情報機器を使える人と使えない人の格差→デジタルデバイド、個人の情報を自分で管理する権利→プライバシーの権利(自己情報コントロール権)と結びつける。'], ex: { q: '高齢者や所得の低い人などがインターネットを十分に使えず、行政の情報やサービスを受けにくくなる問題を何というか。', a: 'デジタルデバイド(情報格差)', exp: '手続きや情報の提供がインターネット中心になるほど、使えない人は不利になります。機器の普及や使い方の支援、紙や窓口での対応を残すことなどが対策になります。' } }
    ],
    more: [
      { lv: 1, q: '医師が病状や治療法について十分に説明し、患者がそれを理解したうえで治療に同意することを何というか。', a: 'インフォームド・コンセント', exp: 'インフォームド・コンセントは、患者の自己決定権を尊重するための考え方です。医師が一方的に決めるのではなく、患者が自分で選べるようにします。' },
      { lv: 1, q: '生命倫理で、生命の長さだけでなく、その人がどれだけ自分らしく満足して生きられるかを重んじる考えを、アルファベット3文字で何というか。', a: 'QOL(生命の質・生活の質)', exp: 'QOLは、Quality of Life の略です。延命を何よりも重んじるSOL(生命の尊厳)の考え方と対比されることがあります。' },
      { lv: 1, q: '脳全体の機能が停止し、回復することのない状態を何というか。', a: '脳死', exp: '脳死では、人工呼吸器によって心臓が動いていても、脳の機能は回復しません。脳幹の機能が残り、自発的な呼吸ができる植物状態とは区別されます。' },
      { lv: 1, q: '自分が死んだときに臓器を提供するかどうかの意思を記入しておくカードを何というか。', a: '臓器提供意思表示カード(ドナーカード)', exp: '健康保険証や運転免許証などの裏の欄にも、臓器提供の意思を記入できます。提供する意思だけでなく、提供しない意思も示すことができます。' },
      { lv: 1, q: '1972年にストックホルムで開かれた国連人間環境会議のスローガンは何か。', a: '「かけがえのない地球(Only One Earth)」', exp: 'この会議で人間環境宣言が採択され、国連環境計画(UNEP)が設立されました。環境問題を国際的に話し合う出発点となった会議です。' },
      { lv: 1, q: '私生活をみだりに公開されない権利として生まれ、現在では自分の情報を自分で管理する権利をふくむと考えられている新しい人権を何というか。', a: 'プライバシーの権利', exp: '情報社会では、個人の情報が大量に集められ、本人の知らないところで使われるおそれがあります。そのため、自分の情報の扱いを自分で決める権利(自己情報コントロール権)として考えられるようになりました。' },
      { lv: 1, q: '子どもをもちたい夫婦が、ほかの女性に妊娠・出産を依頼する方法を何というか。', a: '代理出産(代理懐胎)', exp: '代理出産では、依頼した夫婦と出産した女性のどちらが母親なのか、出産する女性の体への負担や、お金による依頼の是非などが問題になります。' },
      { lv: 2, q: '2009年に改正された臓器移植法の内容として正しいものはどれか。', choices: ['本人の書面による意思表示がなければ、臓器提供はできない', '本人の意思が不明でも、家族の承諾があれば臓器提供ができる', '15歳未満の子どもからの臓器提供は、引き続き禁止された', '臓器の売買が条件つきで認められた'], a: 'B(本人の意思が不明でも、家族の承諾があれば臓器提供ができる)', exp: '改正によって、本人が拒否していなければ家族の承諾で提供できるようになり、15歳未満からの提供も可能になりました。臓器の売買は、改正後も禁止されています。' },
      { lv: 2, q: '生命医学倫理の四原則のうち、「患者に害を与えてはならない」という原則を何というか。', a: '無危害原則', exp: '四原則は、自律尊重・無危害・善行・正義です。無危害原則は、ヒポクラテスの誓いにも見られる、医療の古くからの原則です。' },
      { lv: 2, q: '環境倫理の「地球全体主義」とは、どのような考えか。', a: '地球は資源も環境も限られた閉じた世界であり、個人や国の利益よりも、地球全体の生態系の維持と人類の生存を優先して考えるべきだという考え。', exp: '「宇宙船地球号」ということばに表れるように、地球を一つのシステムとしてとらえます。個人の自由な活動を制限する根拠にもなりうる点が、議論の対象になります。' },
      { lv: 2, q: 'SNSなどで、自分と似た意見の人とばかりつながることで、同じ意見が反響し合い、それが正しいと思いこみやすくなる現象を何というか。', a: 'エコーチェンバー', exp: 'エコーチェンバーは「反響室」という意味です。ちがう意見にふれにくくなると、意見が極端になったり、社会の分断が深まったりするおそれがあります。' },
      { lv: 2, q: '1992年の地球サミット(国連環境開発会議)で、環境と開発を両立させるための基本理念とされた考えを何というか。', a: '持続可能な開発', exp: '持続可能な開発は、将来の世代の必要を満たす能力をそこなわずに、現在の世代の必要を満たす開発のことです。のちのSDGs(持続可能な開発目標)にもつながりました。' },
      { lv: 2, q: '2003年に、人間の遺伝情報の全体の解読がほぼ完了したと発表された国際的な研究計画を何というか。', a: 'ヒトゲノム計画', exp: '遺伝情報の解読は、病気の原因の解明や治療に役立つと期待されています。一方で、遺伝情報による就職や保険での差別、プライバシーの保護などが課題になります。' },
      { lv: 2, q: '医師が、患者のためになると考えて、患者本人の意思を確かめずに治療方針を決めてしまうような態度を何というか。', a: 'パターナリズム(父権的温情主義)', exp: 'パターナリズムは、親が子どもを守るように、本人の利益のために本人に代わって決めることです。自己決定権を重んじる立場からは、批判の対象になります。' },
      { lv: 2, q: '『動物の解放』をあらわし、苦痛を感じる能力がある動物の利益も平等に考慮すべきだと説いた思想家はだれか。', choices: ['ピーター・シンガー', 'レイチェル・カーソン', 'ハーディン', 'ロールズ'], a: 'A(ピーター・シンガー)', exp: 'シンガーは功利主義の立場から、人間だけを特別あつかいすることを「種差別」と批判しました。動物実験や工場的な畜産のあり方を問い直す議論につながっています。' },
      { lv: 3, q: '信仰上の理由で輸血を拒否していた患者に、医師が説明しないまま手術中に輸血を行った裁判で、最高裁判所(2000年)はどのような判断を示したか。', a: '患者が、自分の宗教上の信念に反する医療を拒否する意思決定をする権利は、人格権の一内容として尊重されなければならないとし、説明を怠った病院側の責任を認めた。', exp: 'この判決は、医療における自己決定権を重視したものとして知られます。医師には、輸血の可能性がある場合にそれを説明し、患者が手術を受けるかどうかを選べるようにする義務があるとされました。' },
      { lv: 3, q: '「持続可能な開発」という考え方は、環境倫理の世代間倫理とどのように結びついているか説明せよ。', a: '持続可能な開発は、将来の世代が必要とするものを満たす能力をそこなわない範囲で、現在の世代が開発を行うという考えであり、現在の世代が将来の世代に責任を負うという世代間倫理を、開発のあり方に具体化したものといえる。', exp: '資源の使いすぎや環境の破壊は、将来の世代の選択肢をうばいます。今の豊かさと将来の生存条件のバランスをとることが、両者に共通する考え方です。' },
      { lv: 3, q: '積極的安楽死と消極的安楽死(尊厳死)のちがいを説明し、日本での積極的安楽死の法的な扱いについて答えよ。', a: '積極的安楽死は、薬物の投与などによって意図的に死期を早めること。消極的安楽死は、延命治療を差し控えたり中止したりして自然な死にまかせること。日本では、積極的安楽死を認める法律はない。', exp: 'オランダなど一部の国では、条件つきで積極的安楽死を認める法律があります。日本では、過去の裁判で許される条件が議論されたものの、法律で認められてはいません。' },
      { lv: 3, q: '『責任という原理』をあらわし、科学技術の力が大きくなった現代では、未来の人類に対する責任が必要だと説いた哲学者はだれか。', a: 'ハンス・ヨナス', exp: 'ヨナスは、これまでの倫理は目の前の人どうしの関係しか考えてこなかったと指摘しました。技術の影響が遠い未来にまで及ぶ今、人類が存続できる条件を守る責任があると説き、世代間倫理の土台を築きました。' },
      { lv: 3, q: '第三者から提供された精子や卵子を使う生殖補助医療で生まれた子どもについて、「出自を知る権利」が議論されている。この権利が求められる理由を説明せよ。', a: '自分の遺伝上の親がだれかを知ることは、自分のアイデンティティの確立や、遺伝する病気への備えなどにかかわる大切なことだから。', exp: '一方で、提供者のプライバシーを守ることや、提供者が減るおそれなども考える必要があります。子どもの権利と、提供者や親の利益をどう調整するかが課題です。' }
    ]
  });

  add('pk_kenpo', {
    pat: [
      { name: '具体的な権利を人権の分類にあてはめる', freq: 'とてもよく出る', when: '「〜する権利」「〜の自由」が示され、自由権・社会権・参政権・請求権などのどれにあたるかを問われたら、この型です。', how: ['国家に口出しさせない権利(国家からの自由)なら自由権と考え、さらに精神・身体・経済の自由に分ける。', '国家に生活の保障を求める権利(国家による自由)なら社会権と考える。', '政治に参加する権利なら参政権、国に何かを求めて救済を受ける権利(裁判・賠償など)なら請求権と判断する。'], ex: { q: '「職業選択の自由」は、自由権のうち、精神の自由・身体の自由・経済の自由のどれにあたるか。', a: '経済の自由', exp: '職業選択の自由(第22条)は、居住・移転の自由や財産権(第29条)とともに経済の自由にふくまれます。経済の自由は、公共の福祉による制限を、精神の自由より広く受けると考えられています。' } },
      { name: '判例と争われた権利を結びつける', freq: 'とてもよく出る', when: '裁判の名前や事件の内容が示され、何の権利・原則が争われたか、どんな判断が出たかを問われたら、この型です。', how: ['事件の中で、だれが何を制限されたかを読みとる。', '制限された内容から、争われた権利や原則を決める(政教分離・表現の自由・平等権・生存権など)。', '合憲か違憲か、そのときに使われた考え方(目的効果基準・統治行為論など)をあわせて答える。'], ex: { q: '愛媛県が、靖国神社などの例大祭に玉串料を公金から支出したことが争われた愛媛玉串料訴訟で、最高裁判所(1997年)はどのような判断をしたか。', a: '政教分離の原則に反し、違憲と判断した。', exp: '最高裁は目的効果基準を用いて、この支出は特定の宗教を援助・助長する効果があると判断しました。同じ基準を用いながら合憲とした津地鎮祭訴訟と、結論のちがいを比べておきましょう。' } },
      { name: '憲法改正の手続きを順に答える', freq: 'よく出る', when: '憲法改正の発議・国民投票・公布の順序や、必要な賛成の数を問われたら、この型です。', how: ['国会の各議院で、総議員の3分の2以上の賛成で発議する。', '国民投票で、有効投票の過半数の賛成で承認される。', '天皇が国民の名で、この憲法と一体をなすものとして公布する。'], ex: { q: '憲法改正の発議に必要な賛成の数として正しいものはどれか。「各議院の出席議員の過半数」「各議院の出席議員の3分の2以上」「各議院の総議員の3分の2以上」から選べ。', a: '各議院の総議員の3分の2以上', exp: '憲法改正の発議は、法律の制定よりきびしい条件になっています。「出席議員」ではなく「総議員」が基準なので、欠席した議員も分母にふくまれます。このように改正の手続きがきびしい憲法を硬性憲法といいます。' } },
      { name: '経済の自由の規制を「目的」で判断する', freq: '難関大で出る', when: '営業や職業に関する規制が合憲か違憲かを、規制の目的とあわせて問われたら、この型です。', how: ['規制の目的が、国民の生命や健康への害を防ぐこと(消極目的)か、経済的な弱者を守るなどの政策(積極目的)かを見分ける。', '消極目的の規制は、より緩やかな手段で目的を達成できないかを厳しく審査する(薬事法距離制限事件は違憲)。', '積極目的の規制は、国会の判断を尊重して緩やかに審査する(小売市場距離制限事件は合憲)。'], ex: { q: '中小の小売商を過当競争から守るため、小売市場の開設に距離制限を設けた規定について、最高裁判所(1972年)はどのように判断したか。', a: '合憲と判断した。', exp: '経済的な弱者を守る積極目的の規制であり、国会の判断が著しく不合理とはいえないとされました。一方、薬局の距離制限は、国民の健康を守る消極目的の規制で、必要以上の制限だとして違憲とされました。' } },
      { name: '新しい人権を場面から判定する', freq: 'よく出る', when: '憲法に直接書かれていない権利が、具体的な場面とともに示されたら、この型です。', how: ['良い環境で暮らしたい→環境権、政府の情報を知りたい→知る権利、私生活を守りたい→プライバシーの権利と考える。', '自分の生き方を自分で決めたい→自己決定権、マスメディアに意見を出したい→アクセス権と考える。', '根拠となる条文(第13条の幸福追求権、第25条の生存権、第21条の表現の自由など)を結びつける。'], ex: { q: '住民が、県が持っている公共事業の資料を見せるよう求めた。この住民が主張している新しい人権は何か。', a: '知る権利', exp: '知る権利は、表現の自由(第21条)を、情報を受けとる側から考えたものです。国民が政治について判断するためには、行政の情報を知ることが欠かせません。情報公開制度は、この権利を実現するためのしくみです。' } }
    ],
    more: [
      { lv: 1, q: '日本国憲法の三大原則をすべて答えよ。', a: '国民主権・基本的人権の尊重・平和主義', exp: 'この3つは、日本国憲法の前文などに示された基本的な原則です。大日本帝国憲法の天皇主権とのちがいとして、国民主権がよく問われます。' },
      { lv: 1, q: '日本国憲法第1条で、天皇は日本国と日本国民統合の何であると定められているか。', a: '象徴', exp: '天皇は象徴であり、その地位は主権者である国民の総意にもとづくとされます。天皇は政治的な権限をもたず、内閣の助言と承認によって国事行為を行います。' },
      { lv: 1, q: '日本国憲法が施行された年月日を答えよ。', a: '1947年5月3日', exp: '日本国憲法は1946年11月3日に公布され、半年後の1947年5月3日に施行されました。5月3日は憲法記念日、11月3日は文化の日として祝日になっています。' },
      { lv: 1, q: '日本国憲法第9条が定めている内容にふくまれないものはどれか。', choices: ['戦争の放棄', '戦力の不保持', '交戦権の否認', '国防軍の設置'], a: 'D(国防軍の設置)', exp: '第9条は、戦争の放棄・戦力の不保持・交戦権の否認を定めています。自衛隊がこの規定とどう関わるかは、長く議論されてきました。' },
      { lv: 1, q: '日本国憲法が定める国民の三大義務をすべて答えよ。', a: '子どもに普通教育を受けさせる義務・勤労の義務・納税の義務', exp: '憲法は、国民の権利を多く定めていますが、義務はこの3つが中心です。「教育を受ける」のは子どもの権利で、義務を負うのは保護者であることに注意しましょう。' },
      { lv: 1, q: '国王や政府であっても、正しい法に従わなければならないという考え方を何というか。', a: '法の支配', exp: '法の支配は、権力者が思いのままに支配する「人の支配」に反対する考えです。イギリスで、国王も法の下にあるという考えとして発展しました。' },
      { lv: 1, q: '思想・良心の自由や表現の自由は、自由権のうちどれに分類されるか。', choices: ['精神の自由', '身体の自由', '経済の自由', '社会権'], a: 'A(精神の自由)', exp: '精神の自由には、思想・良心の自由、信教の自由、表現の自由、学問の自由などがふくまれます。心の中や、考えを表すことに関わる自由です。' },
      { lv: 2, q: '憲法改正の国民投票で、改正案が承認されるための条件を答えよ。', a: '賛成の投票数が、投票総数(賛成と反対の票の合計)の2分の1をこえること。', exp: '国民投票法では、無効票をのぞいた賛成と反対の合計を分母にして、過半数の賛成で承認されると定めています。有権者全体の過半数ではないことに注意しましょう。' },
      { lv: 2, q: '次のうち、社会権ではないものはどれか。', choices: ['生存権', '教育を受ける権利', '勤労の権利', '裁判を受ける権利'], a: 'D(裁判を受ける権利)', exp: '裁判を受ける権利は、権利が侵害されたときに国に救済を求める請求権です。社会権には、生存権・教育を受ける権利・勤労の権利・労働基本権があります。' },
      { lv: 2, q: '日本国憲法で、人権を制限する根拠として示されている、社会全体の利益や他の人の人権との調整を表すことばを何というか。', a: '公共の福祉', exp: '人権は最大限尊重されますが、他人の人権とぶつかるときには調整が必要です。その調整の原理が公共の福祉です。ただし、安易に人権を制限する理由にしてはならないとされます。' },
      { lv: 2, q: '大阪空港の夜間飛行の差し止めなどを求めた大阪空港公害訴訟で、住民が主張した新しい人権は何か。', a: '環境権', exp: '住民は、よい環境で暮らす権利として環境権を主張しました。最高裁判所は損害賠償の一部を認めましたが、夜間飛行の差し止めの請求は退け、環境権そのものについても判断を示しませんでした。' },
      { lv: 2, q: 'どのような行為が犯罪となり、どのような刑罰が科されるかを、あらかじめ法律で定めておかなければならないという原則を何というか。', a: '罪刑法定主義', exp: '罪刑法定主義は、身体の自由を守るための大切な原則です。後から法律をつくって、以前の行為を罰すること(遡及処罰)も禁止されています。' },
      { lv: 2, q: '自衛隊の基地建設をめぐる長沼ナイキ基地訴訟で、札幌地方裁判所(1973年)はどのような判断を示したか。', choices: ['自衛隊は合憲であると判断した', '自衛隊は憲法第9条が禁じる戦力にあたり違憲であると判断した', '統治行為論により判断しなかった', '訴えを受理しなかった'], a: 'B(自衛隊は憲法第9条が禁じる戦力にあたり違憲であると判断した)', exp: '一審の札幌地裁は自衛隊を違憲としましたが、札幌高裁は統治行為論にふれて憲法判断をさけ、最高裁は訴えの利益がないとして上告を退けました。最高裁は自衛隊の合憲・違憲を判断していません。' },
      { lv: 2, q: '日本国憲法第13条で保障され、新しい人権の主な根拠とされている権利を何というか。', a: '幸福追求権', exp: '第13条は「生命、自由及び幸福追求に対する国民の権利」を定めています。プライバシーの権利や自己決定権などは、この幸福追求権を根拠として主張されてきました。' },
      { lv: 2, q: '日本国憲法第21条が禁止している、行政機関が表現物の内容を発表前に審査し、不適当なものの発表を禁止することを何というか。', a: '検閲', exp: '憲法は「検閲は、これをしてはならない」と定めています。発表される前に表現を止めてしまうと、国民はその内容を知ることも批判することもできなくなるからです。' },
      { lv: 3, q: '経済の自由の規制について、「消極目的の規制」と「積極目的の規制」で審査のきびしさがちがう理由を説明せよ。', a: '消極目的の規制は、国民の生命や健康への害を防ぐためのもので、より緩やかな手段がないかを裁判所が判断しやすいので、きびしく審査する。積極目的の規制は、経済的な弱者の保護などの政策判断をふくむので、国会の判断を尊重して緩やかに審査する。', exp: 'この考え方を規制目的二分論といいます。社会・経済政策の判断は、国民の代表である国会の方が適していると考えられるため、裁判所は国会の判断を尊重する傾向があります。' },
      { lv: 3, q: '日本国憲法が「硬性憲法」とよばれる理由と、そのようなしくみにしている理由を説明せよ。', a: '改正するために、各議院の総議員の3分の2以上の賛成による発議と国民投票での過半数の賛成が必要で、ふつうの法律よりも改正の手続きがきびしいから。そのときどきの多数派が、人権の保障や国の基本的なしくみを簡単に変えられないようにするため。', exp: '立憲主義の考えでは、憲法は国家権力をしばるものです。権力をもつ側が都合よく憲法を変えられないよう、改正には国民の強い合意が必要とされています。' },
      { lv: 3, q: '衆議院の議員定数の不均衡について、最高裁判所(1976年)は違憲と判断したが、選挙そのものは無効にしなかった。その理由として使われた考え方を何というか。また、その内容を説明せよ。', a: '事情判決の法理。選挙を無効にすると、その選挙で選ばれた議員がいなくなり、かえって大きな混乱や不都合が生じるため、違法であることを宣言するにとどめて選挙は有効とした。', exp: '違憲であると判断しながら、結果を取り消さないという判決です。その後も「違憲状態」の判決が続き、国会は定数の見直しを重ねてきました。' },
      { lv: 3, q: '定住外国人の地方選挙の選挙権について、最高裁判所(1995年)はどのような考えを示したか。', a: '憲法は日本国民に選挙権を保障しており、外国人に選挙権を保障したものではない。しかし、永住者などの定住外国人に、法律で地方選挙の選挙権を与えることは、憲法上禁止されていないという考えを示した。', exp: '最高裁は、外国人に選挙権がないことは違憲ではないとしつつ、地方の政治は住民の生活に密接に関わることから、法律で選挙権を与える道を否定しませんでした。実際に選挙権を与える法律はつくられていません。' },
      { lv: 3, q: '女性にだけ再婚禁止期間を設けた民法の規定について、最高裁判所(2015年)はどのように判断したか。', a: '再婚禁止期間のうち、100日をこえる部分は、合理性を欠く過剰な制約であり、法の下の平等や婚姻の自由に反して違憲であると判断した。', exp: '父親の推定が重なることを避けるという目的には100日で足りるとされました。判決を受けて、国会は期間を100日に短くし、その後の民法改正で再婚禁止期間そのものが廃止されました。' }
    ]
  });

  add('pk_seiji', {
    pat: [
      { name: 'ドント式で比例代表の議席を配分する', freq: 'とてもよく出る', when: '比例代表の各党の得票数と定数が示され、各党の議席数を問われたら、この型です。', how: ['各党の得票数を1、2、3…でわっていく。', 'できた商(わり算の答え)を、大きい順に定数の数だけ選ぶ。', '各党が何個選ばれたかを数え、それが議席数になる。'], ex: { q: '定数5の比例代表選挙で、A党8400票、B党5000票、C党2600票を得た。ドント式で配分すると、各党の議席はいくつか。', a: 'A党3議席、B党1議席、C党1議席', exp: '商はA党8400・4200・2800・2100、B党5000・2500、C党2600…です。大きい順に5つ選ぶと、8400(A)・5000(B)・4200(A)・2800(A)・2600(C)なので、A党3、B党1、C党1です。2500(B)は6番目で選ばれません。' } },
      { name: '衆議院の優越の場面を判定する', freq: 'とてもよく出る', when: '衆議院と参議院の議決が異なったときにどうなるかを、法律案・予算・条約・首相指名ごとに問われたら、この型です。', how: ['法律案は、衆議院で出席議員の3分の2以上の賛成で再可決すれば成立する。', '予算・条約の承認は、両院協議会でも一致しないか、参議院が30日以内に議決しないと、衆議院の議決が国会の議決になる。', '首相の指名は、両院協議会でも一致しないか、参議院が10日以内に議決しないと、衆議院の議決が国会の議決になる。'], ex: { q: '衆議院で可決した法律案を参議院が否決した。この法律案を成立させるには、どうすればよいか。', a: '衆議院で、出席議員の3分の2以上の賛成で再び可決すればよい。', exp: '法律案では、両院協議会を開くことはできますが、開かなくてもかまいません。衆議院の再可決には、出席議員の3分の2以上というきびしい条件があります。予算や条約のように、自動的に衆議院の議決が優先されるしくみとはちがいます。' } },
      { name: '三権の抑制と均衡の「矢印」を答える', freq: 'よく出る', when: '国会・内閣・裁判所の間で、だれがだれに対して何ができるかを問われたら、この型です。', how: ['国会→内閣:首相の指名、内閣不信任の決議。内閣→国会:衆議院の解散、国会の召集。', '国会→裁判所:弾劾裁判。内閣→裁判所:最高裁長官の指名とその他の裁判官の任命。', '裁判所→国会・内閣:違憲審査(法律・命令・処分が憲法に合うかを判断)。国民→最高裁:国民審査。'], ex: { q: '最高裁判所長官を指名するのはどこか。また、任命するのはだれか。', a: '内閣が指名し、天皇が任命する。', exp: '最高裁長官以外の最高裁判所の裁判官と、下級裁判所の裁判官は、内閣が任命します。裁判官を選ぶことで、内閣は裁判所に対して一定の抑制を働かせています。' } },
      { name: '地方の直接請求の署名数と請求先', freq: 'よく出る', when: '条例の制定・監査・首長の解職・議会の解散などの直接請求について、必要な署名数や請求先を問われたら、この型です。', how: ['条例の制定・改廃は、有権者の50分の1以上の署名で首長に請求する。', '事務の監査は、有権者の50分の1以上の署名で監査委員に請求する。', '首長・議員の解職や議会の解散は、原則として有権者の3分の1以上の署名で選挙管理委員会に請求し、住民投票で過半数の賛成があれば成立する。'], ex: { q: '有権者が12万人の市で、条例の制定を請求するには、何人以上の署名が必要か。また、だれに請求するか。', a: '2400人以上の署名で、市長に請求する。', exp: '120000÷50=2400人です。条例の制定・改廃の請求を受けた首長は、議会にかけて結果を公表します。住民投票で決まるのではなく、最終的には議会が判断する点に注意します。' } },
      { name: '一票の格差を計算する', freq: 'よく出る', when: '選挙区ごとの有権者数と定数が示され、格差が何倍かを問われたら、この型です。', how: ['各選挙区で、議員1人あたりの有権者数(有権者数÷定数)を求める。', '最も多い選挙区の値を、最も少ない選挙区の値でわる。', '倍数が大きいほど、1人あたりの有権者が少ない選挙区の一票が重く、法の下の平等から問題になると説明する。'], ex: { q: '選挙区Aは有権者60万人で定数2、選挙区Bは有権者25万人で定数1である。一票の格差は何倍か。', a: '1.2倍', exp: '議員1人あたりの有権者数は、Aが 60÷2=30万人、Bが25万人です。30÷25=1.2倍になります。定数が1でない選挙区があるときは、必ず定数でわってから比べましょう。' } }
    ],
    more: [
      { lv: 1, q: '衆議院議員の任期は何年か。また、参議院議員の任期は何年か。', a: '衆議院4年(解散がある)、参議院6年(3年ごとに半数を改選)', exp: '衆議院は任期が短く解散もあるので、国民の意思をより反映しやすいと考えられています。これが衆議院の優越の理由の一つです。' },
      { lv: 1, q: '内閣総理大臣は、どのような人の中から、どのようにして選ばれるか。', a: '国会議員の中から、国会の議決によって指名される。', exp: '首相は国会が指名し、天皇が任命します。国務大臣は首相が任命し、その過半数は国会議員でなければなりません。' },
      { lv: 1, q: '毎年1回、1月に召集され、主に次の年度の予算を審議する国会を何というか。', a: '通常国会(常会)', exp: '通常国会の会期は150日です。ほかに、必要に応じて開かれる臨時国会(臨時会)、衆議院の総選挙後に開かれる特別国会(特別会)などがあります。' },
      { lv: 1, q: '地方自治の本旨のうち、地域の政治をその地域の住民の意思にもとづいて行うことを何というか。', a: '住民自治', exp: '地方自治の本旨は、住民自治と団体自治の2つからなります。住民が首長や議員を選ぶことや、直接請求権は住民自治の表れです。' },
      { lv: 1, q: '選挙の基本原則のうち、だれに投票したかを他人に知られないようにする原則を何というか。', choices: ['普通選挙', '平等選挙', '直接選挙', '秘密選挙'], a: 'D(秘密選挙)', exp: '選挙の4原則は、普通選挙・平等選挙・直接選挙・秘密選挙です。秘密選挙によって、だれにも圧力をかけられずに自由に投票できます。' },
      { lv: 1, q: '自分たちの利益を実現するために、政府や政党にはたらきかける団体を何というか。', a: '圧力団体(利益集団)', exp: '圧力団体には、経済団体・労働組合・農業団体などがあります。政権をとることを目的とせず、特定の利益の実現をめざす点で、政党とちがいます。' },
      { lv: 1, q: '最高裁判所の裁判官がその職にふさわしいかを、国民が投票で判断する制度を何というか。', a: '国民審査', exp: '国民審査は、任命後に初めて行われる衆議院議員総選挙のときに行われ、その後10年を経過するごとに審査されます。やめさせるべきだという票が過半数になると罷免されます。' },
      { lv: 2, q: '定数4の比例代表選挙で、A党6000票、B党4200票、C党1500票を得た。ドント式で配分すると各党の議席はいくつか。', a: 'A党2議席、B党2議席、C党0議席', exp: '商はA党6000・3000・2000、B党4200・2100、C党1500です。大きい順に4つ選ぶと、6000(A)・4200(B)・3000(A)・2100(B)なので、A党2、B党2になります。' },
      { lv: 2, q: '衆議院で可決し、参議院で否決された法律案を、衆議院で再可決するために必要な賛成の数を答えよ。', a: '出席議員の3分の2以上', exp: '法律案の再可決は、出席議員の3分の2以上です。憲法改正の発議(各議院の総議員の3分の2以上)と、分母がちがうことに注意しましょう。' },
      { lv: 2, q: '条約の承認について、衆議院が承認し、参議院が承認しなかった。両院協議会でも意見が一致しない場合、どうなるか。', a: '衆議院の議決が国会の議決となり、条約は承認される。', exp: '条約の承認は予算と同じあつかいで、両院協議会で一致しないとき、または参議院が30日以内に議決しないときは、衆議院の議決が優先されます。法律案のような再可決は必要ありません。' },
      { lv: 2, q: '地方公共団体の事務の監査を請求するには、有権者の何分の1以上の署名を集めて、だれに請求するか。', a: '50分の1以上の署名で、監査委員に請求する。', exp: '監査請求は、税金が正しく使われているかを住民がチェックするしくみです。条例の制定・改廃の請求と同じく、50分の1以上の署名が必要です。' },
      { lv: 2, q: '選挙区Aは有権者48万人で定数1、選挙区Bは有権者20万人で定数1である。一票の格差は何倍か。', a: '2.4倍', exp: '48÷20=2.4倍です。Bの有権者の一票は、Aの有権者の一票の2.4倍の重みをもつことになります。人口が都市に集中すると、このような格差が広がりやすくなります。' },
      { lv: 2, q: '内閣が国会に対して行うことができるものとして、正しいものはどれか。', choices: ['内閣総理大臣の指名', '衆議院の解散の決定', '弾劾裁判所の設置', '国政調査権の行使'], a: 'B(衆議院の解散の決定)', exp: '衆議院の解散は、内閣の助言と承認にもとづく天皇の国事行為として行われます。首相の指名・弾劾裁判所の設置・国政調査権は、どれも国会の権限です。' },
      { lv: 2, q: '地方公共団体が条例にもとづいて行う住民投票について、正しい説明はどれか。', choices: ['結果には必ず法的な拘束力がある', '憲法で、すべての地方公共団体に実施が義務づけられている', '結果に法的な拘束力はないことが多いが、住民の意思を示す手段になる', '国会議員の選挙と同時にしか実施できない'], a: 'C(結果に法的な拘束力はないことが多いが、住民の意思を示す手段になる)', exp: '原子力発電所や基地、市町村合併などをめぐって、条例による住民投票が行われてきました。結果に法的な拘束力はなくても、首長や議会の判断に大きな影響を与えます。' },
      { lv: 2, q: '国の行政に対する国民の苦情を受けつけ、中立の立場で調査し、改善を勧告する制度を何というか。', a: 'オンブズマン(オンブズパーソン)制度', exp: 'オンブズマン制度は北ヨーロッパで始まりました。日本では国の制度としては導入されていませんが、川崎市など一部の地方公共団体が設けています。' },
      { lv: 3, q: '衆議院の比例代表で、同じ順位に重複立候補した候補者XとYがいる。Xは小選挙区で60000票(当選者は80000票)、Yは小選挙区で72000票(当選者は100000票)を得た。惜敗率の高い方を答えよ。', a: 'X(Xの惜敗率75%、Yの惜敗率72%)', exp: 'Xは 60000÷80000×100=75%、Yは 72000÷100000×100=72% です。得票数はYの方が多くても、当選者との差の割合で比べるので、Xが先に当選します。' },
      { lv: 3, q: '定数6の比例代表選挙で、A党12000票、B党7000票、C党4500票、D党2000票を得た。ドント式で配分すると各党の議席はいくつか。', a: 'A党3議席、B党2議席、C党1議席、D党0議席', exp: '商を大きい順に並べると、12000(A)・7000(B)・6000(A)・4500(C)・4000(A)・3500(B)で、6つ目までが当選です。7つ目は3000(A)なので選ばれません。' },
      { lv: 3, q: '有権者が30万人の市で、市長の解職を請求するには何人以上の署名が必要か。また、その後どのような手続きで解職が決まるか。', a: '10万人以上の署名を集めて選挙管理委員会に請求し、住民投票で過半数の賛成があれば市長は解職される。', exp: '有権者が40万人以下の場合は3分の1以上の署名が必要で、300000÷3=100000人です。解職は、議会ではなく住民投票で決まる点が、条例の制定・改廃の請求とのちがいです。' },
      { lv: 3, q: 'アメリカの大統領制と、日本の議院内閣制のちがいを、議会と行政府の関係から説明せよ。', a: '議院内閣制では、内閣が国会の信任にもとづいて成立し、衆議院は内閣不信任を決議でき、内閣は衆議院を解散できる。大統領制では、大統領は国民の選挙で選ばれて議会から独立しており、議会は大統領を不信任できず、大統領も議会を解散できない。', exp: 'アメリカの大統領は議会に法案を出せない一方で、議会が可決した法案を拒否する権限(拒否権)をもちます。厳格な権力分立が大統領制の特色です。' },
      { lv: 3, q: '衆議院の解散中に開かれた参議院の緊急集会で決めたことは、その後どうなるか。', a: '臨時のものであり、次の国会が開会した後10日以内に衆議院の同意がなければ、その効力を失う。', exp: '緊急集会は、衆議院がない間に国に緊急の必要が生じたとき、内閣の求めで開かれます。あくまで一時的な措置なので、新しく選ばれた衆議院の同意を必要とするのです。' }
    ]
  });

  add('pk_keizai', {
    pat: [
      { name: '曲線のシフトを判定する', freq: 'とてもよく出る', when: '「所得が増えた」「原材料が値上がりした」などの出来事が示され、均衡価格と取引量の変化を問われたら、この型です。', how: ['その出来事が、買い手(需要)と売り手(供給)のどちらの事情かを見分ける。', '需要が増えれば需要曲線は右へ、供給が減れば供給曲線は左へ、と動く向きを決める。', '新しい交点を読み、価格と取引量がそれぞれ上がるか下がるかを答える。', 'その商品自体の価格の変化は、曲線の移動ではなく曲線上の移動であることに注意する。'], ex: { q: 'ある果物が健康によいとテレビで紹介され、人気が急に高まった。需要曲線・供給曲線のどちらがどちらへ動き、均衡価格と取引量はどう変わるか。', a: '需要曲線が右へ動き、均衡価格は上がり、取引量は増える。', exp: '人気の高まりは、どの価格でも前より多く買いたいという買い手の事情なので、需要曲線が右へ移動します。供給曲線との新しい交点は右上になるので、価格も取引量も増えます。' } },
      { name: '需要・供給の式から均衡を計算する', freq: 'よく出る', when: '需要曲線と供給曲線が式で示され、均衡価格や取引量、税の影響を問われたら、この型です。', how: ['需要の式と供給の式を等しいとおいて、取引量Qを求める。', 'Qをどちらかの式に代入して、価格Pを求める。', '1個あたりの税が売り手にかかるときは、供給の式の価格に税額を加えてから、同じように解く。'], ex: { q: '需要曲線が P=100−Q、供給曲線が P=20+Q で表される。均衡価格と均衡取引量を求めよ。', a: '均衡価格60、均衡取引量40', exp: '100−Q=20+Q より 2Q=80、Q=40 です。P=100−40=60 になります。代入したら、もう一方の式(20+40=60)でも同じ値になるか確かめると、計算ミスを防げます。' } },
      { name: '付加価値の合計でGDPを求める', freq: 'よく出る', when: '生産の段階ごとの売上が示され、GDPや付加価値の合計を問われたら、この型です。', how: ['各段階の付加価値=売上−原材料などの中間生産物の額 を求める。', '付加価値をすべて足す。', '最終生産物の価格と等しくなることを確かめる(中間生産物を二重に数えない)。'], ex: { q: '鉄鉱石が50億円で売られ、それを使った鋼材が130億円で売られ、その鋼材で自動車が300億円で売られた。付加価値の合計はいくらか。', a: '300億円', exp: '付加価値は、鉄鉱石50億円、鋼材 130−50=80億円、自動車 300−130=170億円で、合計300億円です。最終生産物である自動車の価格と一致します。売上を全部足す(480億円)と、中間生産物を二重に数えてしまいます。' } },
      { name: '市場の失敗の型を判定する', freq: 'とてもよく出る', when: '市場にまかせるとうまくいかない例が示され、その種類を問われたら、この型です。', how: ['少数の企業が市場を支配→独占・寡占。', '取引の外の人に害や利益が及ぶ→外部不経済・外部経済。', 'お金を払わない人も利用でき、みんなで同時に使える→公共財。売り手と買い手の情報の量がちがう→情報の非対称性。'], ex: { q: '工場の排煙で、近くの住民が健康被害を受けたが、その費用は製品の価格にふくまれていない。これは市場の失敗のどの例か。', a: '外部不経済', exp: '市場の取引に参加していない第三者に、不利益が及ぶことを外部不経済といいます。費用が価格にふくまれないので、製品は社会的に望ましい量より多くつくられてしまいます。税や規制で是正をはかります。' } },
      { name: '名目と実質を区別して計算する', freq: 'よく出る', when: '名目GDPと物価指数、名目成長率と物価上昇率などが示されたら、この型です。', how: ['名目は、その時の価格で計算した値、実質は物価の変化を取り除いた値と確かめる。', '実質GDP=名目GDP÷GDPデフレーター×100 で計算する。', '成長率なら、実質成長率≒名目成長率−物価上昇率 と考える。'], ex: { q: 'ある年の名目GDPが550兆円、GDPデフレーター(基準年=100)が110だった。この年の実質GDPを求めよ。', a: '500兆円', exp: '550÷110×100=500兆円です。物価が基準年より10%高くなっている分を取り除くと、実際に生み出されたものの量は500兆円分だとわかります。' } }
    ],
    more: [
      { lv: 1, q: 'ふつうの商品では、価格が上がると需要量はどうなるか。', a: '減る', exp: '価格が上がると、買いたい人や買いたい量が減ります。そのため、需要曲線は右下がりになります。反対に、供給量は価格が上がると増えるので、供給曲線は右上がりです。' },
      { lv: 1, q: '需要量と供給量が一致するところで決まる価格を何というか。', a: '均衡価格', exp: '価格が均衡価格より高いと売れ残り(超過供給)が生じて価格は下がり、低いと品不足(超過需要)が生じて価格は上がります。こうして価格は均衡価格に向かいます。' },
      { lv: 1, q: '株式会社で、株主が集まって経営の基本方針や役員を決める最高の意思決定機関を何というか。', a: '株主総会', exp: '株主総会では、原則として持っている株の数に応じて議決権が与えられます(1株1票)。取締役の選任や、利益の配当などが決められます。' },
      { lv: 1, q: '株式会社の株主が、会社の借金について、出資した金額の範囲までしか責任を負わないことを何というか。', a: '有限責任', exp: '有限責任のおかげで、多くの人が安心して出資でき、大きな資金を集めることができます。会社が倒産しても、株主は出資した株の価値を失うだけですみます。' },
      { lv: 1, q: '次のうち、外部不経済の例として正しいものはどれか。', choices: ['駅ができて周りの土地の価値が上がった', '工場の騒音で近くの住民が眠れなくなった', '人気商品の価格が上がった', '企業が新商品を開発した'], a: 'B(工場の騒音で近くの住民が眠れなくなった)', exp: '取引に関係のない人に不利益を与えるのが外部不経済です。駅ができて周りが得をするのは、反対の外部経済の例です。' },
      { lv: 1, q: '景気の変動の4つの局面を、好況から順に答えよ。', a: '好況→後退→不況→回復', exp: '景気は、好況・後退・不況・回復の4つの局面をくり返しながら変動します。後退が急激に起こることを恐慌といいます。' },
      { lv: 1, q: '1つの企業が市場を支配し、競争相手がいない状態を何というか。', a: '独占', exp: '独占では、競争がないため、価格が高く設定されたり、品質の改善が進まなかったりしやすくなります。そのため、独占禁止法で不当な独占が規制されています。' },
      { lv: 2, q: '需要曲線が P=90−2Q、供給曲線が P=30+Q で表されるとき、均衡価格と均衡取引量を求めよ。', a: '均衡価格50、均衡取引量20', exp: '90−2Q=30+Q より 3Q=60、Q=20 です。P=30+20=50 で、需要の式でも 90−40=50 となり一致します。傾きの数字がちがう式でも、等しいとおいて解く手順は同じです。' },
      { lv: 2, q: '人々の所得が増えた。ふつうの商品の需要曲線はどちらへ動き、均衡価格はどうなるか。', a: '需要曲線は右へ動き、均衡価格は上がる。', exp: '所得が増えると、同じ価格でも前より多く買えるので、需要曲線が右へ移動します。供給曲線は変わらないので、価格は上がり、取引量は増えます。' },
      { lv: 2, q: 'ある商品の原材料の価格が上がった。供給曲線はどちらへ動き、均衡価格と取引量はどう変わるか。', a: '供給曲線は左へ動き、均衡価格は上がり、取引量は減る。', exp: '原材料が高くなると、生産費が上がり、同じ価格では前より少ない量しか売りに出せません。そのため供給曲線が左へ移動します。' },
      { lv: 2, q: '綿花が40億円で売られ、それを使った綿糸が90億円、その綿糸で織った布が160億円、その布でつくったシャツが250億円で売られた。布の段階で生み出された付加価値と、全体の付加価値の合計を答えよ。', a: '布の段階は70億円、合計は250億円', exp: '布の段階の付加価値は 160−90=70億円です。全体は 40+50+70+90=250億円で、最終生産物であるシャツの価格と一致します。売上をすべて足すと中間生産物を二重に数えてしまいます。' },
      { lv: 2, q: '中古車の売り手は車の状態をよく知っているが、買い手はよく知らない。このような状態を何というか。', a: '情報の非対称性', exp: '情報が売り手にかたよっていると、買い手は品質を見分けられず、良い商品まで安くしか売れなくなるなど、市場がうまく働かなくなります。保証制度や情報開示が対策になります。' },
      { lv: 2, q: '景気循環のうち、技術革新などを原因とする、周期が約50年の長い波を何というか。', choices: ['キチンの波', 'ジュグラーの波', 'クズネッツの波', 'コンドラチェフの波'], a: 'D(コンドラチェフの波)', exp: 'キチンの波は在庫投資による約40か月、ジュグラーの波は設備投資による約10年、クズネッツの波は建設投資による約20年、コンドラチェフの波は技術革新による約50年の周期です。' },
      { lv: 2, q: 'ガソリンの価格が大きく上がったところ、自動車の需要が減った。ガソリンと自動車のように、一緒に使われる関係にある財を何というか。', a: '補完財', exp: '補完財は、片方の価格が上がると、もう片方の需要も減る関係にあります。バターとマーガリンのように、片方の代わりに使える関係は代替財といいます。' },
      { lv: 2, q: '名目GDPが630兆円、GDPデフレーター(基準年=100)が105のとき、実質GDPを求めよ。', a: '600兆円', exp: '実質GDP=名目GDP÷GDPデフレーター×100 なので、630÷105×100=600兆円です。物価の上昇分を取り除いて、実際の生産の量を比べるのが実質GDPです。' },
      { lv: 3, q: '需要曲線が P=120−Q、供給曲線が P=Q+20 で表される商品がある。政府がこの商品1個あたり10の税を売り手に課した。課税後の均衡価格と取引量を求め、税10のうち買い手と売り手がそれぞれいくら負担するかを答えよ。', a: '課税後の価格75、取引量45。買い手の負担5、売り手の負担5', exp: '課税前は 120−Q=Q+20 より Q=50、P=70 です。課税後の供給曲線は P=Q+30 となり、120−Q=Q+30 より Q=45、P=75 です。買い手は 75−70=5 多く払い、売り手の手取りは 75−10=65 で、5 減ります。' },
      { lv: 3, q: '外部不経済を出している企業に対して、その害の大きさに応じた税をかけて生産量をへらすという考え方を何というか。また、そのねらいを説明せよ。', a: 'ピグー税(環境税など)。社会にかけている費用を企業の生産費に組みこむことで、生産量を社会的に望ましい水準まで減らすこと。', exp: '外部不経済があると、企業は社会への害を費用として考えないので、作りすぎになります。税で害の分を価格に反映させることを「外部不経済の内部化」といいます。' },
      { lv: 3, q: 'ある国の実質GDPが、前の年の500兆円から今年は520兆円になった。実質経済成長率を求めよ。', a: '4%', exp: '(520−500)÷500×100=4% です。成長率は、増えた分をもとの年の値でわって求めます。今年の値でわらないように注意しましょう。' },
      { lv: 3, q: '企業が利益を追求するだけでなく、環境の保護や地域社会への貢献など、社会の一員としての責任を果たすべきだという考えを何というか。また、企業の経営を株主などが監視するしくみを何というか。', a: '企業の社会的責任(CSR)。コーポレート・ガバナンス(企業統治)', exp: '企業は、株主だけでなく、従業員・消費者・地域社会など多くの利害関係者(ステークホルダー)とかかわっています。不正を防ぎ、信頼を得るために、両方が重視されるようになりました。' },
      { lv: 3, q: 'ある商品の価格を10%上げたところ、需要量は2%しか減らなかった。需要の価格弾力性を求め、この値上げで売上(価格×数量)が増えるか減るかを答えよ。', a: '弾力性は0.2(非弾力的)。売上は増える(およそ1.1×0.98=1.078倍)。', exp: '弾力性は 2÷10=0.2 で、1より小さいので非弾力的です。価格の上がり方の方が需要量の減り方より大きいので、売上は約7.8%増えます。生活必需品などに見られる性質です。' }
    ]
  });

  add('pk_zaisei', {
    pat: [
      { name: '景気に合わせた政策の「向き」を答える', freq: 'とてもよく出る', when: '「不況のとき」「景気が過熱しているとき」に、政府や日本銀行がとる政策を問われたら、この型です。', how: ['まず、景気を良くしたい(需要を増やす)のか、おさえたい(需要を減らす)のかを決める。', '財政政策なら、不況のときは減税・公共事業の増加、過熱のときは増税・公共事業の削減と考える。', '金融政策なら、不況のときは買いオペ・金利の引き下げ(資金を増やす)、過熱のときは売りオペ・金利の引き上げ(資金を減らす)と考える。'], ex: { q: '景気が過熱し、物価が上がり続けている。日本銀行が行う公開市場操作として適切なのは、買いオペと売りオペのどちらか。', a: '売りオペ(資金吸収オペレーション)', exp: '日銀が銀行に国債などを売ると、銀行の手元の資金が減り、金利が上がります。お金を借りにくくなるので、投資や消費がおさえられ、景気の過熱や物価の上昇がしずまります。' } },
      { name: '信用創造の額を計算する', freq: 'よく出る', when: '最初の預金額と支払準備率が示され、銀行全体で生まれる預金の額を問われたら、この型です。', how: ['預金の総額=最初の預金÷支払準備率 を求める。', '信用創造額=預金の総額−最初の預金 を求める。', '問われているのが「総額」か「新たに生み出された額」かを必ず確かめる。'], ex: { q: '最初の預金が500万円、支払準備率が20%のとき、銀行全体で新たに生み出される預金(信用創造額)はいくらか。', a: '2000万円', exp: '預金の総額は 500÷0.2=2500万円です。そこから最初の預金500万円を引いて、2000万円が新たに生み出された額です。準備率が低いほど、信用創造の額は大きくなります。' } },
      { name: '乗数効果で国民所得の増加を求める', freq: '難関大で出る', when: '限界消費性向と、公共事業や減税の額が示され、国民所得がどれだけ増えるかを問われたら、この型です。', how: ['公共事業の乗数は 1÷(1−限界消費性向) で求める。', '減税の乗数は 限界消費性向÷(1−限界消費性向) で求める(減税分の一部は貯蓄されるので、最初の一回分が小さい)。', '乗数に政策の額をかけて、国民所得の増加を出す。'], ex: { q: '限界消費性向が0.75の国で、政府が公共事業を20兆円増やした。国民所得は最終的に何兆円増えるか。', a: '80兆円', exp: '乗数は 1÷(1−0.75)=4 なので、20×4=80兆円です。同じ額の減税なら、乗数は 0.75÷0.25=3 で60兆円となり、公共事業より効果が小さくなります。' } },
      { name: '超過累進税率で税額を計算する', freq: 'よく出る', when: '所得の区分ごとの税率が表で示され、ある人の税額を問われたら、この型です。', how: ['所得を、税率の区分ごとに分ける。', 'それぞれの区分の金額に、その区分の税率をかける。', '区分ごとの税額を合計する(所得全体に最も高い税率をかけない)。'], ex: { q: '税率が、所得200万円以下の部分は10%、200万円をこえ500万円以下の部分は20%、500万円をこえる部分は30%とする。所得600万円の人の税額はいくらか。', a: '110万円', exp: '200万円×10%=20万円、300万円×20%=60万円、100万円×30%=30万円で、合計110万円です。600万円全体に30%をかける(180万円)のはまちがいです。区分ごとに計算するのが超過累進税率です。' } },
      { name: '名目金利と実質金利、インフレの有利・不利', freq: 'よく出る', when: '金利と物価上昇率が示され、実質的な負担や、だれが有利・不利になるかを問われたら、この型です。', how: ['実質金利≒名目金利−物価上昇率 で求める。', 'インフレでは、お金の価値が下がるので、借りている人(債務者)は実質的に返す負担が軽くなり有利、貸している人や預金者は不利と考える。', 'デフレでは、その逆になる(借金の実質的な重さが増す)と考える。'], ex: { q: '名目金利が1%、物価上昇率が3%のとき、実質金利はおよそ何%か。', a: '約−2%', exp: '1−3=−2% です。実質金利がマイナスなら、お金を借りても、物価の上昇によって返すお金の実質的な価値が小さくなります。そのため、借りる人には有利で、預金している人には不利になります。' } }
    ],
    more: [
      { lv: 1, q: '財政の3つの機能をすべて答えよ。', a: '資源配分の機能・所得の再分配の機能・景気の安定化の機能', exp: '資源配分は公共財の提供、所得の再分配は累進課税や社会保障による格差の是正、景気の安定化は景気の波をなだらかにする働きです。' },
      { lv: 1, q: '国の予算のうち、税金などを主な財源とし、社会保障や公共事業などの基本的な支出をまかなう会計を何というか。', a: '一般会計', exp: '国の予算には、一般会計のほか、特定の事業のための特別会計、政府関係機関予算があります。ニュースで「国の予算」というときは、ふつう一般会計をさします。' },
      { lv: 1, q: '所得が多い人ほど、高い税率が適用されるしくみを何というか。', a: '累進課税', exp: '所得税は累進課税のしくみをとっています。所得の多い人がより多くの税を負担することで、所得の格差を小さくする働き(所得の再分配)があります。' },
      { lv: 1, q: '日本銀行の3つの役割を答えよ。', a: '発券銀行・銀行の銀行・政府の銀行', exp: '日本銀行は、日本銀行券(紙幣)を発行し、銀行との間でお金の貸し借りを行い、政府のお金(国庫金)を管理します。' },
      { lv: 1, q: 'ものやサービスの価格(物価)が、持続的に上がり続ける現象を何というか。', a: 'インフレーション(インフレ)', exp: 'インフレでは、同じ金額で買えるものが少なくなるので、お金の価値が下がります。反対に、物価が下がり続けることをデフレーションといいます。' },
      { lv: 1, q: '道路や橋などの公共事業の財源にあてるため、財政法で発行が認められている国債を何というか。', a: '建設国債', exp: '公共事業でつくる道路などは将来の世代も使うので、借金で建設することが認められています。それ以外の支出の不足を補う赤字国債(特例国債)は、毎年特別な法律をつくって発行します。' },
      { lv: 1, q: '消費税は、直接税と間接税のどちらか。', choices: ['直接税', '間接税', '地方税だけにある税', '税ではなく社会保険料'], a: 'B(間接税)', exp: '消費税は、税を負担する人(消費者)と、税を納める人(事業者)がちがうので間接税です。所得税や法人税のように、負担する人と納める人が同じなのが直接税です。' },
      { lv: 2, q: '最初の預金が800万円、支払準備率が20%のとき、銀行全体で新たに生み出される預金(信用創造額)はいくらか。', a: '3200万円', exp: '預金の総額は 800÷0.2=4000万円です。最初の預金800万円を引くと、3200万円が新たに生み出された額です。' },
      { lv: 2, q: '限界消費性向が0.8の国で、政府が公共事業を10兆円増やした。国民所得は最終的に何兆円増えるか。', a: '50兆円', exp: '乗数は 1÷(1−0.8)=5 なので、10×5=50兆円です。所得が増えた人がその8割を消費に回し、それがまた別の人の所得になる、という波及がくり返されます。' },
      { lv: 2, q: '不況のときに政府が行う財政政策として、適切な組み合わせはどれか。', choices: ['増税と公共事業の削減', '減税と公共事業の増加', '増税と公共事業の増加', '減税と公共事業の削減'], a: 'B(減税と公共事業の増加)', exp: '不況のときは、減税で人々の使えるお金を増やし、公共事業で政府自身の支出を増やして、社会全体の需要を大きくします。このような政策をフィスカル・ポリシー(裁量的財政政策)といいます。' },
      { lv: 2, q: '名目金利が2%、物価上昇率が3%のとき、実質金利はおよそ何%か。', a: '約−1%', exp: '2−3=−1% です。利息がついても、物価の上がり方の方が大きいので、預金の実質的な価値は減ってしまいます。' },
      { lv: 2, q: '消費税には「逆進性」があるといわれる。その意味を説明せよ。', a: '所得の低い人ほど、所得のうち消費に使う割合が高いため、所得にしめる消費税の負担の割合が大きくなること。', exp: '消費税は、だれでも同じ税率で払います。しかし、所得の多い人は所得の一部を貯蓄に回すので、所得にしめる税の割合は低くなります。食料品などに軽減税率を設けるのは、この逆進性をやわらげるためです。' },
      { lv: 2, q: '日本銀行が売りオペレーションを行うと、市場の資金量と金利はどうなるか。', a: '市場の資金量は減り、金利は上がる。', exp: '日銀が国債などを銀行に売ると、銀行はその代金を払うので手元の資金が減ります。お金が貸し出しにくくなり、金利が上がります。景気の過熱をおさえるときに行われます。' },
      { lv: 2, q: '企業が株式や社債を発行して、家計などから直接お金を集めることを何というか。', a: '直接金融', exp: '直接金融では、お金を出す人が、だれに出すかを自分で決め、そのリスクも負います。銀行が預金を集めて企業に貸し出すしくみは間接金融といいます。' },
      { lv: 2, q: '税の負担について、「所得が同じなら同じ税を負担する」という公平の考え方を何というか。', choices: ['垂直的公平', '水平的公平', '世代間の公平', '応益の公平'], a: 'B(水平的公平)', exp: '同じ所得の人どうしが同じ負担をするのが水平的公平、所得の多い人ほど多く負担するのが垂直的公平です。消費税は水平的公平、累進課税の所得税は垂直的公平にすぐれています。' },
      { lv: 3, q: '税率が、所得200万円以下の部分は10%、200万円をこえ500万円以下の部分は20%、500万円をこえる部分は30%とする。所得800万円の人の税額と、所得にしめる税の割合を求めよ。', a: '税額170万円、割合は約21%', exp: '200万円×10%=20万円、300万円×20%=60万円、300万円×30%=90万円で、合計170万円です。170÷800×100=21.25% で、最高税率の30%よりかなり低くなります。' },
      { lv: 3, q: '限界消費性向が0.8の国で、10兆円の減税を行った。国民所得は最終的に何兆円増えるか。また、同じ額の公共事業より効果が小さくなる理由を説明せよ。', a: '40兆円。減税された10兆円のうち、最初に消費に回るのは8割の8兆円だけで、残りは貯蓄されるから。', exp: '減税の乗数は 0.8÷(1−0.8)=4 なので、10×4=40兆円です。公共事業は10兆円がそのまま需要になるので乗数は5で50兆円になり、減税より効果が大きくなります。' },
      { lv: 3, q: '政府が大量の国債を発行して資金を集めると、金利が上がり、民間企業の投資が減ってしまうことがある。この現象を何というか。', a: 'クラウディング・アウト', exp: 'クラウディング・アウトは「押しのける」という意味です。政府の借り入れが資金を奪い合う形になり、民間の投資を押しのけてしまうため、財政政策の効果が弱まると考えられます。' },
      { lv: 3, q: 'インフレーションが進むと、住宅ローンなどでお金を借りている人には有利になりやすい。その理由を説明せよ。', a: '借りたお金の額は変わらないが、物価や賃金が上がるとお金の価値が下がるので、返すお金の実質的な負担が軽くなるから。', exp: 'たとえば借金1000万円は、物価が2倍になると、実質的には半分の重さになります。反対に、お金を貸している人や、預金・年金で暮らす人は不利になります。' },
      { lv: 3, q: '日本銀行の伝統的な金融政策で、誘導の目標とされてきた、銀行どうしが短期間お金を貸し借りするときの金利を何というか。', a: '無担保コールレート(翌日物)', exp: '日銀は公開市場操作によって市場の資金量を調節し、この金利を目標の水準に誘導します。金利がゼロに近づいて下げられなくなると、資金の量を目標にする量的緩和などの非伝統的な政策がとられました。' }
    ]
  });

  add('pk_rodo', {
    pat: [
      { name: '労働三権・労働三法を場面にあてはめる', freq: 'とてもよく出る', when: '労働者や労働組合の行動が示され、どの権利や法律にもとづくかを問われたら、この型です。', how: ['労働組合をつくる・加わる→団結権、会社と話し合う→団体交渉権、ストライキなど→団体行動権(争議権)と判断する。', '労働条件の最低基準なら労働基準法、労働組合と不当労働行為なら労働組合法、争議の調整なら労働関係調整法と結びつける。', '権利の主体(労働者か使用者か)も確かめる。'], ex: { q: '労働組合が、賃金の引き上げを求めて、会社の代表と話し合いの場をもった。これは労働三権のどれにもとづくか。', a: '団体交渉権', exp: '団体交渉権は、労働組合が使用者と労働条件などについて対等に話し合う権利です。使用者が正当な理由なく話し合いを拒むことは、労働組合法の不当労働行為として禁止されています。' } },
      { name: '不当労働行為かどうかを判定する', freq: 'よく出る', when: '使用者(会社)のふるまいが示され、労働組合法に反するかを問われたら、この型です。', how: ['組合に入ったこと・組合活動をしたことを理由に、解雇や不利益なあつかいをしていないかを見る。', '組合に入らないことを雇用の条件にしていないか(黄犬契約)を見る。', '正当な理由のない団体交渉の拒否や、組合の運営への介入・経費の援助をしていないかを見る。'], ex: { q: '会社が、採用のときに「労働組合に入らないこと」を条件にした。これは許されるか。', a: '許されない。不当労働行為(黄犬契約)にあたる。', exp: '労働組合に加入しないことや脱退することを雇用の条件にする契約を黄犬契約といい、労働組合法で不当労働行為として禁止されています。団結権を侵害するからです。' } },
      { name: '社会保障の4本の柱を判定する', freq: 'とてもよく出る', when: '具体的な制度が示され、社会保険・公的扶助・社会福祉・公衆衛生のどれにあたるかを問われたら、この型です。', how: ['保険料を払っておき、病気・老後・失業などのときに給付を受ける→社会保険(医療・年金・雇用・労災・介護)。', '生活に困っている人に、税金で最低限度の生活を保障する→公的扶助(生活保護)。', '児童・高齢者・障害者などへの支援サービス→社会福祉、感染症の予防や上下水道などの健康の基盤づくり→公衆衛生と判断する。'], ex: { q: '仕事を失った人が、ハローワークで手続きをして、一定期間の給付を受けた。これは社会保障のどの柱にふくまれる制度か。', a: '社会保険(雇用保険)', exp: '雇用保険は、働いている間に保険料を払っておき、失業したときに給付を受ける社会保険です。保険料の負担がなく税金でまかなわれる生活保護(公的扶助)とは、財源と給付の条件がちがいます。' } },
      { name: '年金の財政方式と少子高齢化', freq: 'よく出る', when: '積立方式・賦課方式のちがいや、少子高齢化の影響が問われたら、この型です。', how: ['積立方式=自分が払った保険料を積み立て、将来それを受けとるしくみ、と確かめる。', '賦課方式=その年の現役世代が払う保険料で、その年の高齢者の年金をまかなうしくみ、と確かめる。', '少子高齢化が進むと、賦課方式では現役世代1人あたりの負担が重くなり、積立方式ではインフレに弱いという課題があることをおさえる。'], ex: { q: '「その年に働く世代が払った保険料で、その年の高齢者の年金をまかなう」しくみは、積立方式と賦課方式のどちらか。', a: '賦課方式', exp: '賦課方式は、物価が上がっても、その時の現役世代の保険料で年金を払えるので、インフレに強いという長所があります。一方で、高齢者が増え現役世代が減ると、1人あたりの負担が重くなります。' } },
      { name: '労働市場の需給と最低賃金を計算する', freq: '難関大で出る', when: '労働の需要と供給が式で示され、均衡の賃金や、最低賃金を決めたときの影響を問われたら、この型です。', how: ['需要の式と供給の式を等しいとおいて、均衡の賃金と雇用量を求める。', '最低賃金が均衡の賃金より高いときは、その賃金を両方の式に代入する。', '供給(働きたい人)−需要(雇われる人)が、働きたいのに働けない人(失業)の数になる。'], ex: { q: 'ある地域の時給をW円、労働者の数をL人として、労働の需要が L=360−0.2W、供給が L=0.1W で表される。均衡の時給と雇用量を求めよ。', a: '時給1200円、雇用量120人', exp: '360−0.2W=0.1W より 0.3W=360、W=1200 です。L=0.1×1200=120人 になります。需要の式でも 360−240=120 となり、一致することを確かめましょう。' } }
    ],
    more: [
      { lv: 1, q: '労働三権をすべて答えよ。', a: '団結権・団体交渉権・団体行動権(争議権)', exp: '労働三権は、日本国憲法第28条で保障されています。1人では弱い立場にある労働者が、団結して使用者と対等に交渉できるようにするための権利です。' },
      { lv: 1, q: '労働三法をすべて答えよ。', a: '労働基準法・労働組合法・労働関係調整法', exp: '労働基準法は労働条件の最低基準、労働組合法は労働組合の活動の保障、労働関係調整法は労働争議の予防と解決について定めています。' },
      { lv: 1, q: '生活に困っている人に、国が税金を使って最低限度の生活を保障する制度を何というか。', a: '生活保護(公的扶助)', exp: '生活保護は、生活・住宅・教育・医療などの扶助を行います。日本国憲法第25条の生存権にもとづく、社会保障の最後のセーフティネットです。' },
      { lv: 1, q: '感染症の予防や、上下水道の整備など、人々の健康の基盤を整える社会保障の柱を何というか。', a: '公衆衛生', exp: '公衆衛生は、地域全体の健康を守るための取り組みです。保健所による健康づくりや、予防接種なども公衆衛生にふくまれます。' },
      { lv: 1, q: '社会保障制度の根拠となっている、日本国憲法の条文は第何条か。', a: '第25条', exp: '第25条は、すべての国民に「健康で文化的な最低限度の生活を営む権利」を保障し、国に社会福祉・社会保障・公衆衛生の向上に努める義務を定めています。' },
      { lv: 1, q: 'パートタイム労働者・派遣労働者・契約社員など、期間の定めのない正社員以外の働き方をまとめて何というか。', a: '非正規雇用', exp: '非正規雇用は、働く時間や場所を選びやすい面がある一方で、賃金が低く、雇用が不安定になりやすいという課題があります。' },
      { lv: 1, q: '社会保険にふくまれないものはどれか。', choices: ['医療保険', '年金保険', '雇用保険', '生活保護'], a: 'D(生活保護)', exp: '生活保護は公的扶助で、保険料を払っていなくても、生活に困っていれば税金によって給付を受けられます。社会保険は、医療・年金・雇用・労災・介護の5つです。' },
      { lv: 2, q: '会社が、労働組合の活動に熱心な社員を、そのことを理由に地方へ転勤させた。これは労働組合法でどのように扱われるか。', a: '組合活動を理由にした不利益なあつかいにあたり、不当労働行為として禁止されている。', exp: '組合員であることや組合活動を理由に、解雇・降格・転勤などの不利益なあつかいをすることは禁止されています。労働者は労働委員会に救済を申し立てることができます。' },
      { lv: 2, q: '労働関係調整法による労働争議の調整方法のうち、労働委員会が出した判断に、労使の双方が従わなければならないものはどれか。', choices: ['斡旋', '調停', '仲裁', '団体交渉'], a: 'C(仲裁)', exp: '斡旋は話し合いの仲立ち、調停は調停案を示して受け入れをすすめるもので、従う義務はありません。仲裁の裁定は労働協約と同じ効力をもち、双方をしばります。' },
      { lv: 2, q: '労働基準法で、入社後6か月間続けて勤務し、全労働日の8割以上出勤した労働者に与えられる年次有給休暇は何日か。', a: '10日', exp: '年次有給休暇は、賃金をもらいながら休める休暇です。勤続年数が増えるにつれて日数も増えます。2019年からは、年に5日は確実に取得させることが使用者に義務づけられました。' },
      { lv: 2, q: '育児・介護休業法で、育児休業を取ることができるのはだれか。', a: '女性だけでなく、男性の労働者も取ることができる。', exp: '育児休業は、子どもを育てる男女どちらの労働者にも認められています。男性の取得をうながすため、子どもが生まれた直後に取りやすい制度も設けられています。' },
      { lv: 2, q: '公的年金の財政方式のうち、自分が払った保険料を積み立てておき、将来その積立金から年金を受けとるしくみを何というか。', a: '積立方式', exp: '積立方式は、人口構成の変化の影響を受けにくい一方で、物価が大きく上がると積立金の価値が目減りするという弱点があります。日本の公的年金は、賦課方式を基本にしています。' },
      { lv: 2, q: '2008年に始まった、75歳以上の人が加入する医療保険の制度を何というか。', a: '後期高齢者医療制度', exp: '後期高齢者医療制度は、高齢者の医療費が増える中で、現役世代と高齢者の負担を明確にするためにつくられました。財源は公費・現役世代からの支援金・高齢者の保険料です。' },
      { lv: 2, q: '派遣労働者が雇用契約を結んでいる相手と、実際に指揮命令を受けて働く相手の組み合わせとして正しいものはどれか。', choices: ['雇用契約も指揮命令も派遣先', '雇用契約は派遣元、指揮命令は派遣先', '雇用契約は派遣先、指揮命令は派遣元', '雇用契約も指揮命令も派遣元'], a: 'B(雇用契約は派遣元、指揮命令は派遣先)', exp: '派遣労働者は、派遣会社(派遣元)と雇用契約を結び、派遣された会社(派遣先)の指示を受けて働きます。雇う会社と働く会社がちがうことが、派遣の特徴です。' },
      { lv: 2, q: '仕事と、家庭生活や地域活動、自分の時間などとの調和をはかることを何というか。', a: 'ワーク・ライフ・バランス', exp: '長時間労働を減らし、育児や介護、学び直しなどと両立できる働き方をめざす考え方です。少子化対策や、健康を守るうえでも大切だとされています。' },
      { lv: 3, q: 'ある地域の時給をW円、労働者の数をL人として、労働の需要が L=360−0.2W、供給が L=0.1W で表される。最低賃金が1500円に定められたとき、雇われる人の数と、働きたいのに働けない人の数を求めよ。', a: '雇われる人は60人、働けない人は90人', exp: '時給1500円では、需要は 360−300=60人、供給は 150人です。働きたい人が雇われる人を 150−60=90人 上回ります。均衡の時給(1200円)より高い最低賃金は、失業を生む可能性があることを示しています。' },
      { lv: 3, q: '2018年の働き方改革関連法で、時間外労働(残業)にどのような上限が設けられたか。', a: '原則として月45時間・年360時間とし、特別な事情がある場合でも年720時間以内などの上限が、罰則つきで定められた。', exp: 'それまでは36協定に特別な条項を設ければ、事実上上限なく残業させることができました。過労死などの問題を受けて、法律で上限が定められたのです。' },
      { lv: 3, q: '男女雇用機会均等法は、1985年の制定後、どのように改正されてきたか。主な改正の内容を2つ答えよ。', a: '1997年の改正で、募集・採用・配置・昇進での女性差別が努力義務から禁止に変わり、セクシュアル・ハラスメントの防止への配慮が求められた。2006年の改正で、男性に対する差別も禁止され、間接差別も禁止された。', exp: '制定当初は、差別をしないよう「努める」義務にとどまる部分がありました。改正を重ねて禁止の範囲が広がり、性別にかかわらず差別を禁じる法律へと変わってきました。' },
      { lv: 3, q: '日本で労働組合の組織率が長期的に低下してきた理由を説明せよ。', a: '組合の少ないサービス業で働く人や、組合に加入しにくいパート・派遣などの非正規雇用の人が増えたこと、働き方や考え方が多様になったことなどから。', exp: '日本の労働組合は企業ごとの企業別組合が中心で、正社員を主な組合員としてきました。非正規雇用の増加により、組合に守られない労働者が増えていることが課題です。' },
      { lv: 3, q: '生活保護法の「補足性の原理」とはどのような考えか。', a: '生活に困っている人が、自分の資産や働く能力、ほかの法律による給付などをすべて活用しても、なお最低限度の生活ができない場合に、その不足分を補うという考え。', exp: '生活保護は、国民の権利としての最後のセーフティネットです。一方で、必要な人が申請をためらったり、制度を知らなかったりして、保護を受けられていないことも課題とされています。' }
    ]
  });

  add('pk_kokusai', {
    pat: [
      { name: '比較生産費説で特化する財を決める', freq: 'とてもよく出る', when: '2つの国で、2つの財をつくるのに必要な人数(労働量)が表で示され、どちらの財に特化すべきかを問われたら、この型です。', how: ['各国で、一方の財をつくるのに、もう一方の財の何倍の労働が必要か(比率)を出す。', '比率を国どうしで比べ、相対的に少ない労働でつくれる財を、その国の比較優位の財とする。', '両国がそれぞれ比較優位の財に特化すると、全体の生産量が増えることを確かめる。'], ex: { q: 'A国では機械1単位に3人、衣料1単位に6人が必要で、B国では機械1単位に10人、衣料1単位に5人が必要である。A国とB国はそれぞれどちらの財に特化すればよいか。', a: 'A国は機械、B国は衣料に特化する。', exp: 'A国では機械は衣料の 3÷6=0.5倍の労働でつくれますが、B国では 10÷5=2倍かかります。A国は機械が相対的に得意、B国は衣料が相対的に得意です。特化するとA国は9人で機械3単位、B国は15人で衣料3単位をつくれ、両国合わせた生産は各財とも2単位から3単位に増えます。' } },
      { name: '円高・円安と為替の計算', freq: 'とてもよく出る', when: '為替相場の変化が示され、円での金額の変化や、輸出・輸入への影響を問われたら、この型です。', how: ['1ドル=○円の数字が小さくなれば円高、大きくなれば円安と判断する。', 'ドルの金額×1ドルあたりの円 で、円に換算する。', '円高は輸入に有利・輸出に不利、円安は輸出に有利・輸入に不利と、影響を考える。'], ex: { q: '1ドル=100円から1ドル=125円になった。これは円高・円安のどちらか。また、1万ドルの製品をアメリカに輸出している企業が受けとる代金は、円でいくらからいくらに変わるか。', a: '円安。100万円から125万円に変わる。', exp: '1ドルを手に入れるのに必要な円が増えたので、円の価値が下がった円安です。1万ドル×100円=100万円が、1万ドル×125円=125万円になり、輸出企業の円での売上は増えます。' } },
      { name: '国際収支の項目を判定する', freq: 'よく出る', when: '取り引きの例が示され、国際収支のどの項目に記録されるかを問われたら、この型です。', how: ['ものの輸出入→貿易収支、輸送・旅行・特許の使用料など→サービス収支。', '投資から得る利子・配当や、外国で働いて得た給料→第一次所得収支、対価のない援助や仕送り→第二次所得収支。', '外国の工場や株などを買う投資→金融収支と判断する。'], ex: { q: '日本の企業が、海外の子会社から配当を受けとった。これは国際収支のどの項目に記録されるか。', a: '第一次所得収支', exp: '投資の見返りとして受けとる利子や配当は、第一次所得収支に記録されます。日本は海外への投資が多いので、この項目が大きな黒字になっています。子会社をつくる投資そのものは、金融収支に記録されます。' } },
      { name: '国連の機関と議決のしくみを区別する', freq: 'とてもよく出る', when: '総会・安全保障理事会・国際司法裁判所などの権限や、議決の方法を問われたら、この型です。', how: ['総会=全加盟国が1国1票、決議は勧告で法的な拘束力はない、と確かめる。', '安全保障理事会=常任理事国5か国と非常任理事国10か国。実質事項は常任理事国すべてをふくむ9か国以上の賛成が必要(拒否権)。決定には拘束力がある、と確かめる。', '国際司法裁判所=国家どうしの争いを、当事国の同意があるときに裁く、と結びつける。'], ex: { q: '安全保障理事会で、ある決議案に14か国が賛成し、常任理事国の1か国だけが反対した。この決議案は採択されるか。', a: '採択されない(否決される)。', exp: '実質事項の決議には、9か国以上の賛成に加えて、常任理事国がすべて反対しないことが必要です。常任理事国が1か国でも反対すれば否決されます。これを拒否権といいます。棄権は反対とはみなされない慣行があります。' } },
      { name: '購買力平価で為替相場を考える', freq: '難関大で出る', when: '同じ商品の2国での価格が示され、理論上の為替レートや、実際の相場との比較を問われたら、この型です。', how: ['購買力平価=日本での価格÷外国での価格 で、1ドル=○円を求める。', '実際の相場と比べ、実際の方が円の数字が小さければ、円は購買力平価より高く評価されている(円高)と判断する。', '物価が上がる国の通貨は、長い目で見ると安くなっていくと考える。'], ex: { q: 'あるハンバーガーが、日本では450円、アメリカでは3ドルで売られている。このハンバーガーで見た購買力平価は、1ドル=何円か。', a: '1ドル=150円', exp: '450÷3=150 なので、1ドル=150円です。同じものが同じ値段で買えるような為替レートが購買力平価です。実際の相場がこれより円安なら、日本の商品は外国から見て割安になります。' } }
    ],
    more: [
      { lv: 1, q: '国際連合の本部がある都市はどこか。', a: 'ニューヨーク', exp: '国連本部はアメリカのニューヨークにあります。国際司法裁判所はオランダのハーグにあり、本部とは別の場所であることに注意しましょう。' },
      { lv: 1, q: '国連の安全保障理事会の常任理事国5か国をすべて答えよ。', a: 'アメリカ・イギリス・フランス・ロシア・中国', exp: '常任理事国は、第二次世界大戦の主な戦勝国です。実質的な事項の決議で拒否権をもっています。' },
      { lv: 1, q: '国家が成り立つための三つの要素を答えよ。', a: '領域・国民・主権', exp: '領域は領土・領海・領空からなります。主権は、国内では最高の権力であり、外国に対しては独立して自分のことを決める権利です。' },
      { lv: 1, q: '国家どうしが文書で結んだ合意で、国際法の一つとなるものを何というか。', a: '条約', exp: '国際法には、文書で結ばれた条約と、長い間の慣行が法として認められた国際慣習法があります。日本では、内閣が条約を締結し、国会がそれを承認します。' },
      { lv: 1, q: '1ドル=120円から1ドル=100円になった。これは円高・円安のどちらか。', a: '円高', exp: '1ドルを手に入れるのに必要な円が少なくなったので、円の価値が上がった円高です。数字が小さくなるのに「高」というので、まちがえないようにしましょう。' },
      { lv: 1, q: '関税の撤廃だけでなく、投資や人の移動、知的財産の保護など幅広い分野で経済の結びつきを強める協定を、アルファベット3文字で何というか。', a: 'EPA(経済連携協定)', exp: '関税などの撤廃を中心とする協定をFTA(自由貿易協定)、それに投資や人の移動などを加えた、より幅広い協定をEPAといいます。' },
      { lv: 1, q: '国家どうしの争いを、国際法にもとづいて裁判する国連の機関を何というか。', choices: ['国際刑事裁判所', '国際司法裁判所', '国連人権理事会', '国際原子力機関'], a: 'B(国際司法裁判所)', exp: '国際司法裁判所は、当事国が裁判に同意した場合に、国家どうしの争いを裁きます。個人の戦争犯罪などを裁くのは、国際刑事裁判所です。' },
      { lv: 2, q: 'A国では自動車1単位に4人、小麦1単位に8人が必要で、B国では自動車1単位に12人、小麦1単位に10人が必要である。比較生産費説にしたがうと、A国とB国はそれぞれどちらに特化すればよいか。', a: 'A国は自動車、B国は小麦に特化する。', exp: 'A国では自動車は小麦の 4÷8=0.5倍の労働でつくれ、B国では 12÷10=1.2倍かかります。A国は自動車、B国は小麦が相対的に得意なので、それぞれに特化すると両国全体の生産が増えます。' },
      { lv: 2, q: '1ドル=110円から1ドル=130円になったとき、2万ドルの製品をアメリカから輸入している日本の企業が支払う代金は、円でいくらからいくらに変わるか。', a: '220万円から260万円に変わる(支払いが増える)。', exp: '2万ドル×110円=220万円が、2万ドル×130円=260万円になります。円安になると、同じドルの金額の輸入品を買うのにより多くの円が必要になり、輸入に頼る企業や消費者には不利になります。' },
      { lv: 2, q: '外国人旅行者が日本のホテルに泊まって支払ったお金は、日本の国際収支のどの項目に、受け取りとして記録されるか。', a: 'サービス収支(旅行収支)', exp: '旅行者が宿泊・食事・買い物などに使ったお金は、サービス収支の中の旅行収支に記録されます。訪日外国人が増えると、日本の旅行収支は黒字になりやすくなります。' },
      { lv: 2, q: '1950年に国連総会で採択された「平和のための結集」決議とは、どのようなしくみか。', a: '安全保障理事会が拒否権の行使によって機能しないとき、総会が緊急特別総会を開いて、平和のための措置を加盟国に勧告できるようにしたしくみ。', exp: '東西冷戦の中で、安保理は拒否権によって動けなくなることが多くありました。そのため、総会が代わりに行動できる道をつくったのです。ただし、総会の決議は勧告にとどまります。' },
      { lv: 2, q: '日本がPKO(国連平和維持活動)に参加するための「参加5原則」にふくまれないものはどれか。', choices: ['紛争当事者の間で停戦の合意があること', '受け入れ国などが日本の参加に同意していること', '中立の立場を守ること', '国連安全保障理事会の常任理事国が全員参加していること'], a: 'D(国連安全保障理事会の常任理事国が全員参加していること)', exp: '参加5原則は、停戦の合意、受け入れの同意、中立の厳守、条件が満たされなくなったときの撤収、武器使用は必要最小限、の5つです。常任理事国の参加は条件ではありません。' },
      { lv: 2, q: '外国で働く人が、母国の家族に生活費を仕送りした。これは国際収支のどの項目に記録されるか。', a: '第二次所得収支', exp: '第二次所得収支は、対価をともなわない資金の移動を記録します。仕送りのほか、食料や医薬品などの無償の援助、国際機関への拠出金などがふくまれます。' },
      { lv: 2, q: '地域統合のうち、加盟国の間の関税をなくすだけでなく、域外の国に対しては共通の関税をかけるものを何というか。', choices: ['自由貿易協定', '関税同盟', '共同市場', '経済同盟'], a: 'B(関税同盟)', exp: '自由貿易協定は域内の関税の撤廃まで、関税同盟はそれに域外への共通関税を加えたもの、共同市場は人や資本の移動も自由にしたもの、経済同盟は経済政策まで共通にしたものです。' },
      { lv: 2, q: '国連の総会の議決について、正しいものはどれか。', choices: ['常任理事国だけが拒否権をもつ', '加盟国は国の大きさにかかわらず1国1票をもつ', '決議は加盟国を法的に強くしばる', '出資の多い国ほど多くの票をもつ'], a: 'B(加盟国は国の大きさにかかわらず1国1票をもつ)', exp: '総会では、大国も小国も同じ1票をもつ主権平等の原則がとられています。総会の決議は勧告であり、法的な拘束力はありません。拒否権は安全保障理事会のしくみです。' },
      { lv: 3, q: 'A国では機械1単位に2人、衣料1単位に4人、B国では機械1単位に9人、衣料1単位に3人が必要で、A国には6人、B国には12人の労働者がいる。両国がそれぞれ機械と衣料を1単位ずつつくる場合と、比較優位の財に特化した場合とで、両国合わせた生産量はどう変わるか。', a: '特化前は機械2単位・衣料2単位だが、A国が機械に、B国が衣料に特化すると、機械3単位・衣料4単位になる。', exp: 'A国は機械が衣料の 2÷4=0.5倍、B国は 9÷3=3倍の労働が必要なので、A国は機械、B国は衣料に比較優位があります。A国の6人で機械 6÷2=3単位、B国の12人で衣料 12÷3=4単位をつくれ、両国全体の生産が増えます。' },
      { lv: 3, q: 'ある飲み物が日本で520円、アメリカで4ドルで売られている。実際の為替相場が1ドル=150円のとき、円は購買力平価と比べて高く評価されているか、低く評価されているか。', a: '購買力平価は1ドル=130円なので、実際の1ドル=150円は円が低く評価されている(購買力平価より円安)。', exp: '520÷4=130 より購買力平価は1ドル=130円です。実際は1ドルに150円必要なので、円の価値は購買力平価より低いことになります。日本人がアメリカで買うと 4×150=600円で、日本で買う方が安くなります。' },
      { lv: 3, q: '急激な円高が進むと、日本経済にどのような影響が出やすいか。よい影響と悪い影響を1つずつ答えよ。', a: 'よい影響:原油や原材料などの輸入品が安くなる。悪い影響:輸出品が外国で値上がりして売れにくくなり、輸出企業の利益が減ったり、工場の海外移転(産業の空洞化)が進んだりする。', exp: '円高は、輸入に頼る企業や消費者には有利ですが、輸出企業には不利です。1985年のプラザ合意後の急激な円高では、多くの企業が生産拠点を海外へ移しました。' },
      { lv: 3, q: '1971年のニクソン・ショックの後、為替相場の制度はどのように移り変わったか。順に説明せよ。', a: '1971年のスミソニアン協定で、ドルを切り下げて固定相場制を立て直した(1ドル=308円)。しかし維持できず、1973年に主要国は変動相場制に移り、1976年のキングストン合意で変動相場制が正式に認められた。', exp: 'ドルと金の交換停止によって、ブレトンウッズ体制の固定相場制はゆらぎました。立て直しの試みは長く続かず、為替相場は市場の需要と供給で決まる変動相場制へと移りました。' },
      { lv: 3, q: '安全保障理事会で、ある決議案に13か国が賛成し、常任理事国の2か国が棄権した。この決議案は採択されるか。理由とともに答えよ。', a: '採択される。賛成が9か国以上あり、常任理事国の棄権は拒否権の行使(反対)とはみなされない慣行があるから。', exp: '拒否権とは、常任理事国が「反対」することで決議を成立させない権限です。棄権や欠席は反対とは扱われないため、ほかの条件を満たしていれば決議は採択されます。' }
    ]
  });

})(WPS.LESSONS);
